INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摸起来", "is_correct": false, "explanation": "语义：“摸起来”指用手触摸的感觉，用来说人“很累”不合逻辑。"}, {"text": "吃起来", "is_correct": false, "explanation": "搭配：“吃起来”多用于食物的口感，不用来说人的状态。"}, {"text": "闻起来", "is_correct": false, "explanation": "语义：“闻起来”指通过气味来判断，与“很累”无关。"}, {"text": "看起来", "is_correct": true, "explanation": "“看起来”指根据外表判断给人的样子，与“他很累”的判断相符。"}], "explanations": {"摸起来": "语义：“摸起来”指用手触摸的感觉，用来说人“很累”不合逻辑。", "吃起来": "搭配：“吃起来”多用于食物的口感，不用来说人的状态。", "闻起来": "语义：“闻起来”指通过气味来判断，与“很累”无关。", "看起来": "“看起来”指根据外表判断给人的样子，与“他很累”的判断相符。"}, "sentence_index": 0, "correct_answer": "看起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌看起来很好听。", "explanation": "这里应该用〈听起来〉。判断声音好不好听要用听起来；看起来只用于说外表或样子。"}, {"text": "这个铃声看起来太吵了。", "explanation": "这里应该用〈听起来〉。铃声吵不吵要靠耳朵判断，应说听起来；看起来只用于说外表或样子。"}, {"text": "这段音乐看起来很悦耳。", "explanation": "这里应该用〈听起来〉。“悦耳”说的是声音，要靠听来判断；看起来只用于说外表或样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尝起来", "is_correct": false, "explanation": "搭配：“尝起来”多用于食物的味道，不用来说饭馆干净与否。"}, {"text": "走起来", "is_correct": false, "explanation": "语义：“走起来”指行走时的感觉，与饭馆的干净不相干。"}, {"text": "跑起来", "is_correct": false, "explanation": "语义：“跑起来”指奔跑时的状态，与“很干净”的判断无关。"}, {"text": "看起来", "is_correct": true, "explanation": "“看起来”指根据外表判断饭馆给人的样子，与“很干净”相符。"}], "explanations": {"尝起来": "搭配：“尝起来”多用于食物的味道，不用来说饭馆干净与否。", "走起来": "语义：“走起来”指行走时的感觉，与饭馆的干净不相干。", "跑起来": "语义：“跑起来”指奔跑时的状态，与“很干净”的判断无关。", "看起来": "“看起来”指根据外表判断饭馆给人的样子，与“很干净”相符。"}, "sentence_index": 6, "correct_answer": "看起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段旋律看起来很动人。", "explanation": "这里应该用〈听起来〉。旋律动不动人要靠听来判断，应说听起来；看起来只用于外表或样子。"}, {"text": "这条鱼看起来很腥。", "explanation": "这里应该用〈闻起来〉。“腥”是气味，要靠鼻子判断，应说闻起来；看起来不能用来判断气味。"}, {"text": "这台收音机看起来很响。", "explanation": "这里应该用〈听起来〉。判断声音响不响要用听起来；看起来只用于说外表或样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子看起来了很干净，像是刚打扫过。", "corrected_sentence": "这间屋子看起来很干净，像是刚打扫过。", "error_description": "体标误用：“看起来”后不能加“了”，应说“这间屋子看起来很干净”，“了”误加在“看起来”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈看起来了很开心，今天买了新衣服。", "corrected_sentence": "妈妈看起来很开心，今天买了新衣服。", "error_description": "体标误用：“看起来”后不能加“了”，应说“看起来很开心”，“了”误加在“看起来”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "精神", "is_correct": true, "explanation": "正确：困指想睡、没精神，精神指精力充沛，两者是反义关系。"}, {"text": "饿", "is_correct": false, "explanation": "与“困”无反义关系，饿指想吃东西。"}, {"text": "冷", "is_correct": false, "explanation": "与“困”无反义关系，冷指温度低。"}, {"text": "高兴", "is_correct": false, "explanation": "与“困”无反义关系，高兴指心情愉快。"}], "correct_answer": "精神", "explanations": {"精神": "正确：困指想睡、没精神，精神指精力充沛，两者是反义关系。", "饿": "与“困”无反义关系，饿指想吃东西。", "冷": "与“困”无反义关系，冷指温度低。", "高兴": "与“困”无反义关系，高兴指心情愉快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "正确：困指想睡，清醒指头脑清楚、不困，两者是反义关系。"}, {"text": "忙", "is_correct": false, "explanation": "与“困”无反义关系，忙指事情多、没有空闲。"}, {"text": "疼", "is_correct": false, "explanation": "与“困”无反义关系，疼指身体某部位感到痛。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“困”无反义关系，漂亮指外表好看。"}], "correct_answer": "清醒", "explanations": {"清醒": "正确：困指想睡，清醒指头脑清楚、不困，两者是反义关系。", "忙": "与“困”无反义关系，忙指事情多、没有空闲。", "疼": "与“困”无反义关系，疼指身体某部位感到痛。", "漂亮": "与“困”无反义关系，漂亮指外表好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "想睡觉，没有力气。", "primary_collocate": null, "pronunciation": "kùn", "ipa": "kʰuən˥˩", "syllable_count": 1, "sentences": [{"text": "吃完午饭，大家都觉得有点困。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨晚只睡了四个小时，现在好困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了半个小时的报告，他困极了。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝困了，一直在揉眼睛。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看起来很困，是不是没睡好？", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不困，还想再看一会儿书。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开了一整天的车，他又累又困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气暖和的时候，人总是容易困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是困了，就别再玩手机了。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲课太慢，同学们都困了。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯困", "label": "复合"}, {"form": "困倦", "label": "复合"}, {"form": "困意", "label": "复合"}], "register": "口语", "sense_fingerprint": "想睡觉且没力气的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799fe1c-43b6-4a21-9cbd-d99f80002a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困，kùn（第四声），指想睡觉、没有力气。"}, {"text": "捆", "is_correct": false, "explanation": "kǔn（第三声）与 kùn（第四声）声调不同，意思是捆绑。"}, {"text": "混", "is_correct": false, "explanation": "hùn 与 kùn 声母不同（h 与 k），意思是混合。"}, {"text": "棍", "is_correct": false, "explanation": "gùn 与 kùn 声母不同（g 与 k），意思是棍子。"}], "explanations": {"困": "正确：困，kùn（第四声），指想睡觉、没有力气。", "捆": "kǔn（第三声）与 kùn（第四声）声调不同，意思是捆绑。", "混": "hùn 与 kùn 声母不同（h 与 k），意思是混合。", "棍": "gùn 与 kùn 声母不同（g 与 k），意思是棍子。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困指想睡觉、没有力气，符合吃完饭后的状态。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌好看，用来说吃完饭后的感受不通，与句意不符。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”指身高或位置低，与吃完午饭后的感受无关。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”形容厚度小，不能用来说大家的感觉，句意不通。"}], "explanations": {"困": "正确：困指想睡觉、没有力气，符合吃完饭后的状态。", "漂亮": "语义：“漂亮”形容外貌好看，用来说吃完饭后的感受不通，与句意不符。", "矮": "语义：“矮”指身高或位置低，与吃完午饭后的感受无关。", "薄": "语义：“薄”形容厚度小，不能用来说大家的感觉，句意不通。"}, "sentence_index": 0, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题太困了，我做不出来。", "explanation": "这里应该用〈难〉。困指想睡或没力气，不能用来形容题目难。"}, {"text": "听到这个好消息，他困得跳了起来。", "explanation": "这里应该用〈兴奋〉。困表示想睡、没精神，不能用来形容激动的情绪。"}, {"text": "听完这个笑话，大家都困得笑个不停。", "explanation": "这里应该用〈好笑〉。困指想睡、没力气，不能用来形容笑话让人发笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困，kùn（第四声），指想睡觉、没有力气。"}, {"text": "滚", "is_correct": false, "explanation": "gǔn（第三声）与 kùn（第四声）声母和声调都不同，意思是翻滚。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 kùn 韵母不同（a 与 u），意思是看见。"}, {"text": "顿", "is_correct": false, "explanation": "dùn 与 kùn 声母不同（d 与 k），意思是一顿（饭）。"}], "explanations": {"困": "正确：困，kùn（第四声），指想睡觉、没有力气。", "滚": "gǔn（第三声）与 kùn（第四声）声母和声调都不同，意思是翻滚。", "看": "kàn 与 kùn 韵母不同（a 与 u），意思是看见。", "顿": "dùn 与 kùn 声母不同（d 与 k），意思是一顿（饭）。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困指想睡觉、没有力气，与“又累又”的语境相符。"}, {"text": "醉", "is_correct": false, "explanation": "语义：开了一整天的车，司机不能处于醉酒状态，与“开车”的语境冲突。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线或颜色，不用来形容人的身体状态。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能用来形容人。"}], "explanations": {"困": "正确：困指想睡觉、没有力气，与“又累又”的语境相符。", "醉": "语义：开了一整天的车，司机不能处于醉酒状态，与“开车”的语境冲突。", "亮": "搭配：“亮”形容光线或颜色，不用来形容人的身体状态。", "厚": "搭配：“厚”形容物体的厚度，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听完批评，困得把门摔上了。", "explanation": "这里应该用〈生气〉。困指想睡、没精神，不能用来表示发脾气。"}, {"text": "她在台上困得脸都红了。", "explanation": "这里应该用〈害羞〉。困指想睡觉，与脸红的情绪无关。"}, {"text": "考试前，他困得手心直冒汗。", "explanation": "这里应该用〈紧张〉。困不表示焦虑，也不会引起出汗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹困着了，靠在沙发上睡着了。", "corrected_sentence": "妹妹困了，靠在沙发上睡着了。", "error_description": "错误形式：“困着了”；正确形式：“困了”。表示状态出现要用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他困地要死，趴在桌上睡着了。", "corrected_sentence": "他困得要死，趴在桌上睡着了。", "error_description": "错误形式：“困地要死”；正确形式：“困得要死”。“地”用于动词前修饰动作，“困”后接程度补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '570641a8-e2ac-4a4f-80ff-048b0244bfcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
