INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或事物当前所处的情况、样子。", "primary_collocate": null, "pronunciation": "zhuàng tài", "ipa": "ʈʂwɑŋ˥˩ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他最近的状态不太好。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员要保持好状态。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡够八个小时，我的状态好多了。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一直处于关机状态。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯咖啡让他进入了工作状态。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体状态已经恢复了。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在零度以下会变成固体状态。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没有学习状态，只想睡觉。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他的状态，明天的比赛应该没问题。", "target_word": "状态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台服务器一直处于正常的运行状态。", "target_word": "状态", "complexity_tier": "T3", "furigana": "zhè tái fúwùqì yìzhí chǔyú zhèngcháng de yùnxíng zhuàngtài.", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神状态", "label": "复合"}, {"form": "工作状态", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指人或事物表现出来的情况、样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "状态", "is_correct": true, "explanation": "状态：本句的答案，指人当前的身体或精神情况，可以“不太好”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不属于人，不能说“他最近的天气”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体的高度，不能用“不太好”来评价。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，与“不太好”这种评价不符。"}], "explanations": {"状态": "状态：本句的答案，指人当前的身体或精神情况，可以“不太好”。", "天气": "搭配：“天气”不属于人，不能说“他最近的天气”。", "身高": "语义：“身高”是身体的高度，不能用“不太好”来评价。", "体温": "语义：“体温”是身体的温度，与“不太好”这种评价不符。"}, "sentence_index": 0, "correct_answer": "状态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的状态很贵。", "explanation": "这里应该用〈价格〉。状态指情况或样子，不能用来说价钱。"}, {"text": "他的状态是三十岁。", "explanation": "这里应该用〈年龄〉。状态指情况或样子，不能用来表示年纪。"}, {"text": "我的状态减轻了两公斤。", "explanation": "这里应该用〈体重〉。状态表示情况或样子，不能用来说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "状态", "is_correct": true, "explanation": "状态：本句的答案，指物质所处的形态，如固体、液体、气体。"}, {"text": "液体", "is_correct": false, "explanation": "语义：“液体”也是物质的形态，但句中已有“固体”，两者相矛盾，不能说“变成固体液体”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是物质的形态，不能“变成固体”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“变成”后接物质的形态，“脾气”不能与“固体”搭配。"}], "explanations": {"状态": "状态：本句的答案，指物质所处的形态，如固体、液体、气体。", "液体": "语义：“液体”也是物质的形态，但句中已有“固体”，两者相矛盾，不能说“变成固体液体”。", "声音": "语义：“声音”不是物质的形态，不能“变成固体”。", "脾气": "搭配：“变成”后接物质的形态，“脾气”不能与“固体”搭配。"}, "sentence_index": 6, "correct_answer": "状态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的状态很快。", "explanation": "这里应该用〈速度〉。状态指情况或样子，不能用来表示快慢。"}, {"text": "这幅画的状态一共三米。", "explanation": "这里应该用〈尺寸〉。状态表示情况或样子，不能用来说画的长宽。"}, {"text": "这块蛋糕的状态很甜。", "explanation": "这里应该用〈味道〉。状态表示情况或样子，不能用来形容味道的甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他处于一只很好的状态。", "corrected_sentence": "他处于一种很好的状态。", "error_description": "量词错误：“状态”应与量词“种”搭配，说“一种状态”；“只”用于动物或小件物品，不能修饰“状态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的身体状态很高大。", "corrected_sentence": "他的身体状态很好。", "error_description": "搭配错误：“高大”形容体型，不能修饰“状态”；“状态”应搭配“好”“不好”等评价，改为“很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有趣", "is_correct": true, "explanation": "有趣：与“无聊”反义，指有意思、令人愉快。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：指速度快，与“无聊”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：与“吵闹”相对，与“无聊”不构成反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢：指不怕困难和危险，与“无聊”没有反义关系。"}], "correct_answer": "有趣", "explanations": {"有趣": "有趣：与“无聊”反义，指有意思、令人愉快。", "迅速": "迅速：指速度快，与“无聊”没有反义关系。", "安静": "安静：与“吵闹”相对，与“无聊”不构成反义关系。", "勇敢": "勇敢：指不怕困难和危险，与“无聊”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有趣", "is_correct": true, "explanation": "有趣：与“无聊”反义，指有意思、令人愉快。"}, {"text": "紧张", "is_correct": false, "explanation": "紧张：指心里不安、精神绷紧，与“无聊”没有反义关系。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静：指不慌乱、情绪平稳，与“无聊”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实：指说实话、不欺骗，与“无聊”没有反义关系。"}], "correct_answer": "有趣", "explanations": {"有趣": "有趣：与“无聊”反义，指有意思、令人愉快。", "紧张": "紧张：指心里不安、精神绷紧，与“无聊”没有反义关系。", "冷静": "冷静：指不慌乱、情绪平稳，与“无聊”没有反义关系。", "诚实": "诚实：指说实话、不欺骗，与“无聊”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没事做、没有意思，因而觉得烦闷、不开心。", "primary_collocate": null, "pronunciation": "wú liáo", "ipa": "u˧˥ liɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "周末一个人在家，我觉得很无聊。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一个人在宿舍，无聊得不知道该做什么。", "target_word": "无聊", "complexity_tier": "T3", "furigana": "wǒ yí gè rén zài sùshè, wúliáo de bù zhīdào gāi zuò shénme.", "sentence_source": "generated"}, {"text": "下雨天不能出去，孩子们很无聊。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天只是坐着，觉得生活很无聊。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无聊的时候，我喜欢听音乐。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏玩久了，会让人觉得无聊。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等车的时候很无聊，他就拿出手机看。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时他觉得无聊，一直看着窗外。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友都不在，我今天真无聊。", "target_word": "无聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假第三天，我已经开始无聊了。", "target_word": "无聊", "complexity_tier": "T3", "furigana": "fàngjià dì sān tiān, wǒ yǐjīng kāishǐ wúliáo le.", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容词，因没事做或没有意思而感到烦闷、不开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无聊", "is_correct": true, "explanation": "无聊：本句的答案，指没事做、没有意思，与“一个人在家”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声音，与“一个人在家”的情境矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人多、挤，一个人在家不会拥挤。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”指价格低，不能用来说一个人在家的感受。"}], "explanations": {"无聊": "无聊：本句的答案，指没事做、没有意思，与“一个人在家”的语境相符。", "热闹": "语义：“热闹”指人多、有声音，与“一个人在家”的情境矛盾。", "拥挤": "语义：“拥挤”指人多、挤，一个人在家不会拥挤。", "便宜": "语义：“便宜”指价格低，不能用来说一个人在家的感受。"}, "sentence_index": 0, "correct_answer": "无聊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛赢了，大家都很无聊，一起欢呼起来。", "explanation": "这里应该用〈兴奋〉。无聊指没事做、没意思，不能用来形容比赛获胜后的激动。"}, {"text": "这部电影很感人，我看得很无聊。", "explanation": "这里应该用〈感动〉。无聊指没事做、没意思，与“很感人”的感受相矛盾。"}, {"text": "失去亲人后，她哭得很无聊。", "explanation": "这里应该用〈伤心〉。无聊指没事做、没意思，不能用来形容哭泣时的悲伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无聊", "is_correct": true, "explanation": "无聊：本句的答案，指没事可做、感到烦闷，与“拿出手机看”相符。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容声音或笑容，不能说“等车的时候很甜美”。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，不能用来描述等车时的状态。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”多用于空间，不能说“等车的时候很宽敞”。"}], "explanations": {"无聊": "无聊：本句的答案，指没事可做、感到烦闷，与“拿出手机看”相符。", "甜美": "语义：“甜美”形容声音或笑容，不能说“等车的时候很甜美”。", "辛辣": "语义：“辛辣”形容味道，不能用来描述等车时的状态。", "宽敞": "搭配：“宽敞”多用于空间，不能说“等车的时候很宽敞”。"}, "sentence_index": 6, "correct_answer": "无聊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的同学都很无聊，考试成绩全部第一。", "explanation": "这里应该用〈优秀〉。无聊指没事做、没意思，与“成绩全部第一”的情况相矛盾。"}, {"text": "收到生日礼物，她很无聊。", "explanation": "这里应该用〈开心〉。无聊表示没事做或没意思，不表示高兴的情绪。"}, {"text": "他为这次比赛的胜利很高兴，每天都无聊地笑。", "explanation": "这里应该用〈欣喜〉。无聊指没事做、没意思，不能用来形容因胜利而欣喜的笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午没有课，我无聊的坐在窗前发呆。", "corrected_sentence": "下午没有课，我无聊地坐在窗前发呆。", "error_description": "状语错误：“无聊”修饰动词“坐”时应用“地”，写作“无聊地坐”；“的”用于名词前的定语，不能修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午的会议太长了，我无聊的直打哈欠。", "corrected_sentence": "下午的会议太长了，我无聊得直打哈欠。", "error_description": "补语标记错误：“无聊得直打哈欠”中“得”引出补语，应用“得”，写作“无聊得直打哈欠”；“的”用于名词前的定语，不能引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
