INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友上学上课的地方。", "primary_collocate": null, "pronunciation": "jiào shì", "ipa": "tɕjɑʊ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "小明的教室里有很多画。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们坐在教室里听故事。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教室墙上贴着花和小鸟。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上，小朋友高兴地跑进教室。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的小椅子都是红色的。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室门口等着小朋友。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，小朋友们在教室里玩游戏。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新教室又大又亮，小朋友都很喜欢。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我要带一只小兔子到教室。", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的玩具都收好了吗？", "target_word": "教室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "小朋友上学上课的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确答案。教室（jiào shì）指小朋友上课的地方。"}, {"text": "教师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是老师。"}, {"text": "解释", "is_correct": false, "explanation": "jiě 与 jiào 韵母、声调不同，意思是说明原因。"}, {"text": "就是", "is_correct": false, "explanation": "jiù 与 jiào 韵母不同，意思是就是。"}], "explanations": {"教室": "正确答案。教室（jiào shì）指小朋友上课的地方。", "教师": "shī（第一声）与 shì（第四声）声调不同，意思是老师。", "解释": "jiě 与 jiào 韵母、声调不同，意思是说明原因。", "就是": "jiù 与 jiào 韵母不同，意思是就是。"}, "sentence_index": null, "correct_answer": "教室"}, "level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确。小明的教室里摆着画，是小朋友上课的地方，语境相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是小朋友上学的地方，与“小明的……里有很多画”的语境不符。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱是关押罪犯的地方，与小朋友上学的语境相去甚远。"}, {"text": "法庭", "is_correct": false, "explanation": "语域：“法庭”属于庄重的司法语域，与“小明”的儿童语境不协调。"}], "explanations": {"教室": "正确。小明的教室里摆着画，是小朋友上课的地方，语境相符。", "银行": "语义：银行不是小朋友上学的地方，与“小明的……里有很多画”的语境不符。", "监狱": "语义：监狱是关押罪犯的地方，与小朋友上学的语境相去甚远。", "法庭": "语域：“法庭”属于庄重的司法语域，与“小明”的儿童语境不协调。"}, "sentence_index": 0, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋教室的墙上贴着画。", "explanation": "这里应该用〈间〉。教室是房间，“栋”用于整幢建筑，不能用来数教室。"}, {"text": "幼儿园的教室有三层，小朋友在一楼玩。", "explanation": "这里应该用〈教学楼〉。几层楼、一楼玩要说教学楼，教室只是一间房。"}, {"text": "幼儿园的教室有三千名小朋友。", "explanation": "这里应该用〈学校〉。教室只是一间房，不能指整所幼儿园的孩子人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": true, "explanation": "正确。雨天里小朋友可以在室内的教室玩游戏，语境相符。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场在室外，下雨了不适合在里面玩游戏。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地是施工场所，环境危险，不适合小朋友在里面玩游戏。"}, {"text": "洗手间", "is_correct": false, "explanation": "配价：“玩游戏”需要能容纳一群孩子活动的场所，洗手间不具备这一条件。"}], "explanations": {"教室": "正确。雨天里小朋友可以在室内的教室玩游戏，语境相符。", "操场": "语义：操场在室外，下雨了不适合在里面玩游戏。", "工地": "语义：工地是施工场所，环境危险，不适合小朋友在里面玩游戏。", "洗手间": "配价：“玩游戏”需要能容纳一群孩子活动的场所，洗手间不具备这一条件。"}, "sentence_index": 6, "correct_answer": "教室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的教室里长着很多草，周末可以在里面踢球。", "explanation": "这里应该用〈操场〉。草和踢球是室外操场的特点，教室是室内房间。"}, {"text": "这颗教室很漂亮。", "explanation": "这里应该用〈间〉。教室是房间，“颗”用于粒状的小东西，不能用来数教室。"}, {"text": "我的教室里有一张大床，晚上我睡在上面。", "explanation": "这里应该用〈卧室〉。床和晚上睡觉是卧室的特点，教室里摆的是桌椅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师每天在这张教室给小朋友讲故事。", "corrected_sentence": "老师每天在这间教室给小朋友讲故事。", "error_description": "“教室”是房间，量词应用“间”，不用“张”。错误形式：这张教室；正确形式：这间教室。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那栋教室又大又亮，小朋友都很喜欢。", "corrected_sentence": "那间教室又大又亮，小朋友都很喜欢。", "error_description": "“教室”是房间，量词应用“间”，不用“栋”（“栋”用于整幢建筑）。错误形式：那栋教室；正确形式：那间教室。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
