INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信号是告诉我们要做什么事情的消息或记号。", "primary_collocate": null, "pronunciation": "xìn hào", "ipa": "ɕin⁵¹ xaʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "红灯亮了，这是让车停下来的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师举起手，这是请大家安静的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哨声一响，这就是比赛开始的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的人用旗子发出求救信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头，给了我们出发的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用手做出停车的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯是可以走的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声是下课的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眨了眨眼睛，给我一个信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到信号，司机慢慢把车停下来。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个信号", "label": "量词"}, {"form": "信号灯", "label": "复合"}, {"form": "信号弹", "label": "复合"}], "register": "中性", "sense_fingerprint": "用声音、灯光、动作等传达行动指示的消息或记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a662146-0fe1-4053-b97b-687a43040117') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：“让车停下来的信号”指传达行动指示的记号，与红灯的语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是传达行动指示的记号，不能让车停下来。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“让车停下来的”修饰螺丝不搭配，螺丝不是指示行动的记号。"}, {"text": "歌谣", "is_correct": false, "explanation": "语义：歌谣是口头作品，不能作为让车停下的指示。"}], "explanations": {"信号": "正确：“让车停下来的信号”指传达行动指示的记号，与红灯的语境相符。", "食物": "语义：食物不是传达行动指示的记号，不能让车停下来。", "螺丝": "搭配：“让车停下来的”修饰螺丝不搭配，螺丝不是指示行动的记号。", "歌谣": "语义：歌谣是口头作品，不能作为让车停下的指示。"}, "sentence_index": 0, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气吃掉了那个信号。", "explanation": "这里应该用〈饼干〉。信号是传达行动指示的消息或记号，不能被吃掉，应说〈饼干〉。"}, {"text": "工人把信号铺在了客厅里。", "explanation": "这里应该用〈地毯〉。信号是传达行动指示的消息或记号，不能铺在地上，应说〈地毯〉。"}, {"text": "他用信号炒了一盘菜。", "explanation": "这里应该用〈青椒〉。信号是消息或记号，不能当作食材炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：绿灯是允许行走的记号，“可以走的信号”与语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是交通指示，“可以走的作业”不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是传达行动指示的记号，不能表示“可以走”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的形体，不能说“可以走的身材”。"}], "explanations": {"信号": "正确：绿灯是允许行走的记号，“可以走的信号”与语境相符。", "作业": "语义：“作业”是学习任务，不是交通指示，“可以走的作业”不通。", "数字": "语义：数字不是传达行动指示的记号，不能表示“可以走”。", "身材": "体貌：身材描述人的形体，不能说“可以走的身材”。"}, "sentence_index": 6, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他撑开了那个信号，走进了雨里。", "explanation": "这里应该用〈伞〉。撑开的是伞，信号是传达行动指示的消息或记号，不能撑开。"}, {"text": "他拿出那个信号打开了门。", "explanation": "这里应该用〈钥匙〉。打开门要用钥匙，信号是消息或记号，不能用来开门。"}, {"text": "妈妈织了一个信号送给我。", "explanation": "这里应该用〈毛衣〉。织的是毛衣，信号是消息或记号，不能织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一只信号很清楚，司机都看见了。", "corrected_sentence": "这个信号很清楚，司机都看见了。", "error_description": "量词“只”多用于动物或成对器物之一，信号应用“个”或“种”，此处应为“这一个信号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一座明确的信号。", "corrected_sentence": "这是一种明确的信号。", "error_description": "量词“座”用于山、楼房等大型固定物，信号应用“种”或“个”，此处应为“一种明确的信号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5836933-6da4-40fd-b175-01f565777b70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：隐藏与显示是一对反义词，显示是让人看见，隐藏是不让人看见。"}, {"text": "思考", "is_correct": false, "explanation": "无关：思考是脑力活动，与“显示”没有反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "无关：学习与“显示”在语义上没有对立关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：旅行与“显示”没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：隐藏与显示是一对反义词，显示是让人看见，隐藏是不让人看见。", "思考": "无关：思考是脑力活动，与“显示”没有反义关系。", "学习": "无关：学习与“显示”在语义上没有对立关系。", "旅行": "无关：旅行与“显示”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：隐藏与显示是反义词，隐藏是不让人看见。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：跑步是身体运动，与“显示”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：吃饭与“显示”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉与“显示”没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：隐藏与显示是反义词，隐藏是不让人看见。", "跑步": "无关：跑步是身体运动，与“显示”没有反义关系。", "吃饭": "无关：吃饭与“显示”没有反义关系。", "睡觉": "无关：睡觉与“显示”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人看到。", "primary_collocate": null, "pronunciation": "xiǎn shì", "ipa": "ɕiɛn˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "手机屏幕上显示现在是三点。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字显示天气会变冷。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑显示我的密码错了。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上显示前面有一家医院。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩显示他学得很好。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上显示着一行红字。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表显示今年的人数更多了。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯里的灯显示我们在五楼。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容显示他很满意。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器上显示出一个大大的“好”字。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显示了", "label": "体标（了）"}, {"form": "显示着", "label": "体标（着）"}, {"form": "显示出", "label": "补语"}, {"form": "显示器", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，屏幕、数据、表格等把信息或情况明显地表现出来让人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c1a906-ea1f-4e51-bb2e-ae63d5c674b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确答案：显示 xiǎn shì，让人看到信息或情况。"}, {"text": "现实", "is_correct": false, "explanation": "现实 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是客观存在的情况。"}, {"text": "小事", "is_correct": false, "explanation": "小事 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是小的事情。"}, {"text": "闲事", "is_correct": false, "explanation": "闲事 xián shì 第一个音节声调不同（xián 与 xiǎn），意思是与自己无关的事。"}], "explanations": {"显示": "正确答案：显示 xiǎn shì，让人看到信息或情况。", "现实": "现实 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是客观存在的情况。", "小事": "小事 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是小的事情。", "闲事": "闲事 xián shì 第一个音节声调不同（xián 与 xiǎn），意思是与自己无关的事。"}, "sentence_index": null, "correct_answer": "显示"}, "level_3": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确：“屏幕上显示”指让人看到信息，符合句子的语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：屏幕不能唱歌，“屏幕上唱歌现在是三点”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“现在是三点”作宾语，也与屏幕不搭。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”不能用于屏幕，屏幕不会生长。"}], "explanations": {"显示": "正确：“屏幕上显示”指让人看到信息，符合句子的语境。", "唱歌": "语义：屏幕不能唱歌，“屏幕上唱歌现在是三点”说不通。", "散步": "配价：“散步”是不及物动词，不能带“现在是三点”作宾语，也与屏幕不搭。", "生长": "搭配：“生长”不能用于屏幕，屏幕不会生长。"}, "sentence_index": 0, "correct_answer": "显示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆正在显示一批古画。", "explanation": "这里应该用〈展示〉。显示多指通过屏幕或仪表让人看到信息和情况，展示古画等作品要用〈展示〉。"}, {"text": "这个孩子显示了很多朋友。", "explanation": "这里应该用〈有〉。显示指让人看到信息或情况，朋友是人，不能用“显示”，应说“有很多朋友”。"}, {"text": "妈妈每天在厨房里显示很多饭菜。", "explanation": "这里应该用〈做〉。显示指让人看到信息或情况，饭菜是要做出来的实物，应说“做很多饭菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确答案：显示 xiǎn shì，让人看到信息或情况。"}, {"text": "限时", "is_correct": false, "explanation": "限时 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是限定时间。"}, {"text": "现世", "is_correct": false, "explanation": "现世 xiàn shì 第一个音节声调不同（xiàn 与 xiǎn），意思是现在的世界。"}, {"text": "小试", "is_correct": false, "explanation": "小试 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是稍微试一下。"}], "explanations": {"显示": "正确答案：显示 xiǎn shì，让人看到信息或情况。", "限时": "限时 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是限定时间。", "现世": "现世 xiàn shì 第一个音节声调不同（xiàn 与 xiǎn），意思是现在的世界。", "小试": "小试 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是稍微试一下。"}, "sentence_index": null, "correct_answer": "显示"}, "level_3": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确：“这张表显示”指用表格让人看到信息，符合句子的语境。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：表格不会哭泣，“这张表哭泣今年的人数”说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不能用于表格，表格不能跳舞。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：表格不会游泳，句子所说的是人数。"}], "explanations": {"显示": "正确：“这张表显示”指用表格让人看到信息，符合句子的语境。", "哭泣": "语义：表格不会哭泣，“这张表哭泣今年的人数”说不通。", "跳舞": "搭配：“跳舞”不能用于表格，表格不能跳舞。", "游泳": "语义：表格不会游泳，句子所说的是人数。"}, "sentence_index": 6, "correct_answer": "显示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人显示了很多工作。", "explanation": "这里应该用〈完成〉。显示指让人看到信息或情况，工作是要做完的事，应说“完成很多工作”。"}, {"text": "他的成绩显示了很多钱。", "explanation": "这里应该用〈赚〉。显示用于信息或水平，钱是挣来的，应说“赚了很多钱”。"}, {"text": "他的脚上显示了一个大大的“好”字。", "explanation": "这里“显示”需要屏幕、仪器等载体呈现信息，脚上不能“显示”字，应改用“写”或“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上显示着了今天的日期。", "corrected_sentence": "屏幕上显示着今天的日期。", "error_description": "“显示着”后面不能再加“了”，两个体标同时出现是错误的，应为“显示着今天的日期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕上显示来了一行字。", "corrected_sentence": "屏幕上显示出了一行字。", "error_description": "“显示出”的“出”是补语，表示显现出来。“显示来”搭配错误，应为“显示出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
