INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一起学习的人。", "primary_collocate": null, "pronunciation": "tóng xué", "ipa": "tʰʊŋ˧˥ ɕɥœ˧˥", "syllable_count": 2, "sentences": [{"text": "他是我的好同学。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢和同学一起玩。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学帮我捡起了书。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的同学都来了。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学坐在同一张桌子旁。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学借了我一支笔。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学今年也上三年级。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我要和同学去公园。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位同学的字写得很好看。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会做，就问同学。", "target_word": "同学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "同学们", "label": "复数"}, {"form": "老同学", "label": "复合"}], "register": "中性", "sense_fingerprint": "一起学习的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同学", "is_correct": true, "explanation": "正确。“好同学”指关系好、一起学习的人，语境相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“好”所表示的亲近关系相矛盾，也与一起学习的意思不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“好”修饰的人物不能是“窗户”，窗户不是人。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“他是我的好……”要求指人，“地铁”是交通工具，不能这样说。"}], "explanations": {"同学": "正确。“好同学”指关系好、一起学习的人，语境相符。", "陌生人": "语义：“陌生人”与“好”所表示的亲近关系相矛盾，也与一起学习的意思不符。", "窗户": "搭配：“好”修饰的人物不能是“窗户”，窗户不是人。", "地铁": "搭配：“他是我的好……”要求指人，“地铁”是交通工具，不能这样说。"}, "sentence_index": 0, "correct_answer": "同学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同学每天开公交车送乘客上班。", "explanation": "这里应该用〈司机〉。同学是一起学习的人，每天开公交车送乘客的是司机。"}, {"text": "我们公司的同学都很友好。", "explanation": "这里应该用〈同事〉。同学指同校、同班的人，同一公司工作的要说同事。"}, {"text": "同学每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。同学是学习的人，给病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同学", "is_correct": true, "explanation": "正确。“我同学”指同校、同班的人，与“上三年级”相符。"}, {"text": "爸爸", "is_correct": false, "explanation": "语义：爸爸是成年人，不会和小学生一样上三年级。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：爷爷不会上三年级，与“也上三年级”的语境不符。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“上三年级”要求指人，“小猫”不能上年级。"}], "explanations": {"同学": "正确。“我同学”指同校、同班的人，与“上三年级”相符。", "爸爸": "语义：爸爸是成年人，不会和小学生一样上三年级。", "爷爷": "语义：爷爷不会上三年级，与“也上三年级”的语境不符。", "小猫": "搭配：“上三年级”要求指人，“小猫”不能上年级。"}, "sentence_index": 6, "correct_answer": "同学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学每天给病人检查身体。", "explanation": "这里应该用〈护士〉。同学是学习的人，给病人检查身体的是护士或医生。"}, {"text": "同学在讲台上给我们上课，布置作业。", "explanation": "这里应该用〈老师〉。同学是和我们一起学习的人，在讲台上上课、布置作业的是老师。"}, {"text": "饭店的同学很热情，每次都帮我们点菜。", "explanation": "这里应该用〈服务员〉。同学是一起学习的人，饭店里热情点菜的是服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一条同学住在我家附近。", "corrected_sentence": "我的一位同学住在我家附近。", "error_description": "“同学”指人，量词应用“位”或“个”，不用“条”（“条”多用于细长的东西）。错误形式：一条同学；正确形式：一位同学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台同学很努力。", "corrected_sentence": "这位同学很努力。", "error_description": "“同学”指人，量词应用“位”或“个”，不用“台”（“台”用于机器等）。错误形式：这台同学；正确形式：这位同学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
