INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22822, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度很高，超出一般。", "primary_collocate": null, "pronunciation": "tài", "ipa": "tʰaɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这件衣服太贵。", "target_word": "太", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的菜太咸，我不想吃。", "target_word": "太", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说得太快，我听不懂。", "target_word": "太", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间太小，放不下床。", "target_word": "太", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天太黑，我们回家吧。", "target_word": "太", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太晚了，明天再说吧。", "target_word": "太", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤太烫了，我等一会儿再喝。", "target_word": "太", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走得太慢，我们都等了很久。", "target_word": "太", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题太难，我想了一个晚上。", "target_word": "太", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你来了，我太高兴了。", "target_word": "太", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "太：程度副词，表示程度很高、超出一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22822, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太", "is_correct": true, "explanation": "正确：“太”（tài）表示程度很高，超出一般。"}, {"text": "台", "is_correct": false, "explanation": "tái（第二声）与 tài 声调不同，意思是台子、台湾。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 tài 仅声母不同（d/t），意思是带子、携带。"}, {"text": "胎", "is_correct": false, "explanation": "tāi（第一声）与 tài 声调不同，意思是胎儿、轮胎。"}], "explanations": {"太": "正确：“太”（tài）表示程度很高，超出一般。", "台": "tái（第二声）与 tài 声调不同，意思是台子、台湾。", "带": "dài（第四声）与 tài 仅声母不同（d/t），意思是带子、携带。", "胎": "tāi（第一声）与 tài 声调不同，意思是胎儿、轮胎。"}, "sentence_index": null, "correct_answer": "太"}, "level_3": {"options": [{"text": "太", "is_correct": true, "explanation": "正确：“太”表示程度过高，与“这件衣服……贵”的句意相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数，不能修饰程度。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示时间刚刚，不能表示程度。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多个对象，“一件衣服”不能说“一起”。"}], "explanations": {"太": "正确：“太”表示程度过高，与“这件衣服……贵”的句意相符。", "偶尔": "语义：“偶尔”表示次数，不能修饰程度。", "刚": "语义：“刚”表示时间刚刚，不能表示程度。", "一起": "搭配：“一起”需要多个对象，“一件衣服”不能说“一起”。"}, "sentence_index": 0, "correct_answer": "太"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书比那本太好看。", "explanation": "这里应该用〈更〉。“太”不能用在“比”字比较句里，比较时要用“更”。"}, {"text": "这个菜太非常辣。", "explanation": "这里应该用〈非常〉。“太”和“非常”都是程度副词，不能连用，只用一个。"}, {"text": "长江是中国太长的河。", "explanation": "这里应该用〈最〉。说在一群事物中排第一要用“最”，“太”不表示最高级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22822, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "太", "is_correct": true, "explanation": "正确：“太”（tài）表示程度很高，超出一般。"}, {"text": "耐", "is_correct": false, "explanation": "nài（第四声）与 tài 仅声母不同（n/t），意思是忍受、经得起。"}, {"text": "抬", "is_correct": false, "explanation": "tái（第二声）与 tài 声调不同，意思是抬起。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 tài 仅声母不同（d/t），意思是带子、携带。"}], "explanations": {"太": "正确：“太”（tài）表示程度很高，超出一般。", "耐": "nài（第四声）与 tài 仅声母不同（n/t），意思是忍受、经得起。", "抬": "tái（第二声）与 tài 声调不同，意思是抬起。", "带": "dài（第四声）与 tài 仅声母不同（d/t），意思是带子、携带。"}, "sentence_index": null, "correct_answer": "太"}, "level_3": {"options": [{"text": "太", "is_correct": true, "explanation": "正确：“太”表示程度过高，与“汤……烫了”搭配，符合句意。"}, {"text": "同时", "is_correct": false, "explanation": "搭配：“同时”需要两件事或两个对象一起发生，这里只有“汤”一个主语。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计，不能修饰“烫了”这样的程度变化。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“烫了”表示变化的句意矛盾。"}], "explanations": {"太": "正确：“太”表示程度过高，与“汤……烫了”搭配，符合句意。", "同时": "搭配：“同时”需要两件事或两个对象一起发生，这里只有“汤”一个主语。", "一共": "搭配：“一共”表示总计，不能修饰“烫了”这样的程度变化。", "永远": "语义：“永远”表示持续不变，与“烫了”表示变化的句意矛盾。"}, "sentence_index": 6, "correct_answer": "太"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班太高的学生。", "explanation": "这里应该用〈最〉。在一个班里比较、排第一要用“最”，“太”不表示最高级。"}, {"text": "这个房间特别太小。", "explanation": "这里应该用〈特别〉。“特别”和“太”都是程度副词，不能连用，只用一个。"}, {"text": "她跑得太十分快。", "explanation": "这里应该用〈十分〉。“太”和“十分”都是程度副词，不能叠加使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子很太重，我搬不动。", "corrected_sentence": "这把椅子太重，我搬不动。", "error_description": "双重程度：“太”已经表示程度，前面不能再加“很”，应为“太重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他比我太高，我们一起拍照。", "corrected_sentence": "他比我更高，我们一起拍照。", "error_description": "比较句误用：“太”不能用于比较句，比较时应用“更”，应为“比我更高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
