INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "身体或身体的一部分改变位置。", "primary_collocate": null, "pronunciation": "dòng zuò", "ipa": "tʊŋ˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他的动作很快。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看老师的动作，然后跟着做。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个舞蹈动作很难。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的动作非常轻。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了一个起跳的动作。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步前先做几个热身动作。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的每个动作都很好看。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说老人的动作要慢一点。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学着大人的动作拍手。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个动作时，腿要伸直。", "target_word": "动作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小动作", "label": "复合"}, {"form": "动作片", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "身体或身体一部分的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动作", "is_correct": true, "explanation": "正确：“动作”指身体的动作，“他的动作很快”正合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指口感或气味，不能用“快”来形容，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“快”来形容，“他的颜色很快”句意不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“快”形容动作或速度，不能修饰“房子”。"}], "explanations": {"动作": "正确：“动作”指身体的动作，“他的动作很快”正合句意。", "味道": "语义：“味道”指口感或气味，不能用“快”来形容，句意不通。", "颜色": "语义：“颜色”不能用“快”来形容，“他的颜色很快”句意不通。", "房子": "搭配：“快”形容动作或速度，不能修饰“房子”。"}, "sentence_index": 0, "correct_answer": "动作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里传来一阵动作。", "explanation": "这里应该用〈动静〉。“动静”指声音或活动的迹象，可以说“传来一阵动静”；“动作”指身体或身体部分改变位置，不能说从屋里传来。"}, {"text": "老师给我们讲了一个有趣的动作。", "explanation": "这里应该用〈故事〉。“讲”的对象是故事，“动作”指身体或身体部分改变位置，只能“做”或“看”，不能“讲”。"}, {"text": "这本书的动作很有意思。", "explanation": "这里应该用〈内容〉。书里写的东西叫“内容”，“动作”指身体的活动，不能指书里的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动作", "is_correct": true, "explanation": "正确：“动作”指身体的动作，“她的每个动作都很好看”正合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听的，不能用“好看”来形容，句子不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：“气味”是闻的，不能用“好看”来形容，句子不通。"}, {"text": "语气", "is_correct": false, "explanation": "搭配：“好看”形容外貌或样子，不能修饰“语气”，应说“好听”或“温和”。"}], "explanations": {"动作": "正确：“动作”指身体的动作，“她的每个动作都很好看”正合句意。", "声音": "语义：“声音”是听的，不能用“好看”来形容，句子不通。", "气味": "语义：“气味”是闻的，不能用“好看”来形容，句子不通。", "语气": "搭配：“好看”形容外貌或样子，不能修饰“语气”，应说“好听”或“温和”。"}, "sentence_index": 6, "correct_answer": "动作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天动作半小时。", "explanation": "这里应该用〈运动〉。锻炼身体要说“运动”，“动作”指单个的身体动作，不能说“动作半小时”。"}, {"text": "学校组织了一次动作。", "explanation": "这里应该用〈活动〉。有组织的集体行为要说“活动”，“动作”不能用来指这种行为。"}, {"text": "动物园里有很多动作。", "explanation": "这里应该用〈动物〉。动物园里的是有生命的动物，“动作”不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做了一条慢动作。", "corrected_sentence": "他做了一个慢动作。", "error_description": "“动作”前面的量词应用“个”。“条”用于细长的东西，不能说“一条动作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天练习了这个动作。", "corrected_sentence": "她每天练习这个动作。", "error_description": "“每天”表示习惯性的重复，不能与表示完成的“了”搭配，应为「每天练习这个动作」，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
