INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22834, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "小心注意危险的事情。", "primary_collocate": null, "pronunciation": "jǐng jué", "ipa": "tɕiŋ˨˩˦ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "夜里，他警觉地看了看四周。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鹿很警觉，听到声音就跑了。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她警觉起来，发现门没有关好。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只猫一直很警觉，不让陌生人靠近。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察很警觉，一眼就看出他在说谎。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进黑黑的小路，我变得警觉了。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他警觉地问：“谁在外面？”", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门在外，大家要警觉一点。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟儿警觉地看着我们。", "target_word": "警觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他睡得很浅，一点声音就会警觉起来。", "target_word": "警觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警覺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小心留意危险、反应敏锐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警觉", "is_correct": true, "explanation": "警觉：小心留意、反应敏锐，与“夜里提防”的语境相符，可修饰“看了看四周”。"}, {"text": "慷慨", "is_correct": false, "explanation": "搭配：“慷慨”多用于财物或情感的给予，不能修饰“看了看四周”的动作。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能说“高大地看了看四周”。"}, {"text": "勤劳", "is_correct": false, "explanation": "语义：“勤劳”指做事努力，与夜里悄悄观察的情境不合。"}], "explanations": {"警觉": "警觉：小心留意、反应敏锐，与“夜里提防”的语境相符，可修饰“看了看四周”。", "慷慨": "搭配：“慷慨”多用于财物或情感的给予，不能修饰“看了看四周”的动作。", "高大": "体貌：“高大”形容身材，不能说“高大地看了看四周”。", "勤劳": "语义：“勤劳”指做事努力，与夜里悄悄观察的情境不合。"}, "sentence_index": 0, "correct_answer": "警觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚起床，还很警觉，眼睛都睁不开。", "explanation": "这里应该用〈困〉。刚起床、眼睛睁不开是困倦的状态，“警觉”指留心戒备、反应敏锐，与此矛盾。"}, {"text": "这个孩子很警觉，看见陌生人就主动跑过去拥抱。", "explanation": "这里应该用〈亲热〉。“警觉”指提防戒备，与主动亲近陌生人的描述相矛盾。"}, {"text": "他做事很警觉，常常忘了关灯。", "explanation": "这里应该用〈粗心〉。“警觉”指注意留心，与“常常忘了关灯”的描述相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警觉", "is_correct": true, "explanation": "警觉：指有所提防地留心，修饰“问”合乎语境，表示戒备地发问。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容身体状况，不能用来修饰说话或发问的方式。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指经济状况宽裕，与“问”的动作无关。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水或眼神，不能修饰“问”。"}], "explanations": {"警觉": "警觉：指有所提防地留心，修饰“问”合乎语境，表示戒备地发问。", "瘦弱": "体貌：“瘦弱”形容身体状况，不能用来修饰说话或发问的方式。", "富裕": "语义：“富裕”指经济状况宽裕，与“问”的动作无关。", "清澈": "搭配：“清澈”多形容水或眼神，不能修饰“问”。"}, "sentence_index": 6, "correct_answer": "警觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子很警觉，相信了陌生人的话。", "explanation": "这里应该用〈天真〉。“警觉”表示戒备留心，与轻信陌生人的描述相反。"}, {"text": "他睡得很沉，一直很警觉，连雷声都没听见。", "explanation": "这里不应该用“警觉”。“睡得很沉”“没听见雷声”说明他处在熟睡状态，而“警觉”指留心戒备、容易察觉动静，二者矛盾。"}, {"text": "听到好消息，他很警觉，高兴得跳了起来。", "explanation": "这里应该用〈兴奋〉。“警觉”是留心戒备的状态，不用来形容因喜讯而欢跳的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门外有动静，狗立刻警觉地起来。", "corrected_sentence": "门外有动静，狗立刻警觉起来。", "error_description": "错误：“警觉”与补语“起来”之间多加了“地”。正确：“警觉起来”，“起来”是补语，“地”不能插在谓语和补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫听到脚步声，立刻警觉得竖起耳朵。", "corrected_sentence": "猫听到脚步声，立刻警觉地竖起耳朵。", "error_description": "错误形式：“警觉得竖起耳朵”；正确形式：“警觉地竖起耳朵”。“警觉”作状语修饰后面的动作，要用“地”，“得”用于补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
