INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "凉爽就是天气不热，很舒服。", "primary_collocate": null, "pronunciation": "liáng shuǎng", "ipa": "ljɑŋ³⁵ ʂwɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天天气凉爽，我想出去走走。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "九月的北京很凉爽。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天晚上有风，特别凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的春天不冷也不热，很凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢凉爽的秋天。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下午的天气变得凉爽了。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上比城里凉爽。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空调开了以后，房间里很凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凉爽的早晨，爷爷在公园里打太极。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的空气又新鲜又凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "涼爽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天气不热，让人觉得舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95905260-0eb1-406d-a3a2-f2ede409b014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“今天天气凉爽”说明天气舒适，与“我想出去走走”相呼应。"}, {"text": "酷寒", "is_correct": false, "explanation": "语义：“酷寒”指极度寒冷，与“想出去走走”的愉快心情不协调。"}, {"text": "暴烈", "is_correct": false, "explanation": "语义：“暴烈”形容猛烈、狂暴，与舒适的天气不相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容天气。"}], "explanations": {"凉爽": "正确：“今天天气凉爽”说明天气舒适，与“我想出去走走”相呼应。", "酷寒": "语义：“酷寒”指极度寒冷，与“想出去走走”的愉快心情不协调。", "暴烈": "语义：“暴烈”形容猛烈、狂暴，与舒适的天气不相符。", "清脆": "搭配：“清脆”形容声音，不能用来形容天气。"}, "sentence_index": 0, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩很凉爽。", "explanation": "这里应该用〈优秀〉。凉爽只形容天气、环境让人舒适，成绩的好坏要用“优秀”。"}, {"text": "这块铁很凉爽。", "explanation": "这里应该用〈冰冷〉。凉爽不用于金属等物体的低温，铁块的冷应说“冰冷”。"}, {"text": "这张桌子很凉爽。", "explanation": "这里应该用〈凉〉。凉爽只用于天气、空气等环境，桌子的温度要用“凉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“山上比城里凉爽”是常见说法，指山上气温更低、更舒适。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指街市热闹，与“山上”的比较对象不符，且与气温无关。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”形容制作细巧，不能用来比较地方的气温。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人或物过多、空间紧张，与气温的比较无关。"}], "explanations": {"凉爽": "正确：“山上比城里凉爽”是常见说法，指山上气温更低、更舒适。", "繁华": "语义：“繁华”指街市热闹，与“山上”的比较对象不符，且与气温无关。", "精致": "搭配：“精致”形容制作细巧，不能用来比较地方的气温。", "拥挤": "语义：“拥挤”指人或物过多、空间紧张，与气温的比较无关。"}, "sentence_index": 6, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "沙漠里的正午很凉爽。", "explanation": "这里应该用〈酷热〉。凉爽指舒适的凉意，正午的炎热应说“酷热”。"}, {"text": "冬天的夜里很凉爽。", "explanation": "这里应该用〈寒冷〉。凉爽表示舒适的凉，冬夜的冷应说“寒冷”。"}, {"text": "他的发型很凉爽。", "explanation": "这里应该用〈清爽〉。凉爽只用于天气、环境，发型整洁利落的感觉要用“清爽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气凉爽得，我们去公园吧。", "corrected_sentence": "今天天气凉爽，我们去公园吧。", "error_description": "结构错误。“凉爽得”后须接程度补语（如“凉爽得很”），直接停顿不通，应删去“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在凉爽地傍晚散步。", "corrected_sentence": "我们在凉爽的傍晚散步。", "error_description": "“凉爽”修饰名词“傍晚”时要用“的”，写成“地”后不能修饰名词，句子结构不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8254c205-81d4-4f63-ba62-3b8c2a24156d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
