INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "气温下降，天气变冷。", "primary_collocate": null, "pronunciation": "jiàng wēn", "ipa": "tɕjɑŋ˥˩ wən˥", "syllable_count": 2, "sentences": [{"text": "一场大雪以后，城里突然降温了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一月以后，南方也开始降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷空气一来，北京马上降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，晚上还要降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气突然降温，大家都穿上了厚外套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那边已经降温，早上有霜。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末降温，别忘了带手套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近降温太快，孩子容易感冒。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚降温了，今早窗户上有冰。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一降温，街上的人就少了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降温了", "label": "完成体"}, {"form": "降过温", "label": "经历体"}, {"form": "降了温", "label": "离合式"}], "register": "中性", "sense_fingerprint": "降温|天气变冷|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指气温降低，与“一场大雪以后”带来的寒冷一致。"}, {"text": "升温", "is_correct": false, "explanation": "语义：升温是气温上升，与大雪后的寒冷相矛盾。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：发烧指人的体温升高，城市不能发烧。"}, {"text": "加温", "is_correct": false, "explanation": "语义：加温是使变暖，与大雪后城里变冷相矛盾。"}], "explanations": {"降温": "正确：降温指气温降低，与“一场大雪以后”带来的寒冷一致。", "升温": "语义：升温是气温上升，与大雪后的寒冷相矛盾。", "发烧": "搭配：发烧指人的体温升高，城市不能发烧。", "加温": "语义：加温是使变暖，与大雪后城里变冷相矛盾。"}, "sentence_index": 0, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商场的商品大幅降温了。", "explanation": "这里应该用〈降价〉。降温指温度下降，商品价格下降要用降价，“商品降温”说不通。"}, {"text": "他的脚步降温了。", "explanation": "这里应该用〈减慢〉。降温指温度下降，走路变慢要用减慢。"}, {"text": "这个班的平均分降温了。", "explanation": "这里应该用〈降低〉。降温用于天气和温度，平均分下降要用降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指天气变冷，与“别忘了带手套”的保暖提醒一致。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：降价用于商品价格，不用于天气。"}, {"text": "加热", "is_correct": false, "explanation": "搭配：加热用于物体，不说周末加热。"}, {"text": "发热", "is_correct": false, "explanation": "语义：发热是产生热量，与“带手套”保暖的语境相矛盾。"}], "explanations": {"降温": "正确：降温指天气变冷，与“别忘了带手套”的保暖提醒一致。", "降价": "搭配：降价用于商品价格，不用于天气。", "加热": "搭配：加热用于物体，不说周末加热。", "发热": "语义：发热是产生热量，与“带手套”保暖的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把电视的声音降温一点。", "explanation": "这里应该用〈调小〉。降温指温度下降，声音变小要用调小。"}, {"text": "这家公司的员工降温了。", "explanation": "这里应该用〈减少〉。降温只用于温度，员工人数变少要用减少。"}, {"text": "他的视力降温了，看不清黑板。", "explanation": "这里应该用〈下降〉。降温只用于温度，视力变差要用下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气被降温了。", "corrected_sentence": "天气降温了。", "error_description": "错误形式：“天气被降温了”。正确形式：“天气降温了”。原因：表示天气变冷时，“降温”不带受事，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前天降温着，路上结了冰。", "corrected_sentence": "前天降温了，路上结了冰。", "error_description": "错误形式：“降温着”。正确形式：“降温了”。原因：“降温”表示已经发生的变化，要用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
