INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着别人的样子做。", "primary_collocate": null, "pronunciation": "mó fǎng", "ipa": "mɔ˧˥ fɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他一边看视频，一边模仿跳舞。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想模仿那位歌手的唱法。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟模仿爸爸的样子戴帽子。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在模仿小鸟唱歌。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她模仿得太像了，我差点认不出来。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我模仿着老师的动作做运动。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员模仿过很多有名的人。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只会模仿别人，要有自己的想法。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生模仿老师写了一个字。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥最爱模仿电视里的人说话。", "target_word": "模仿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模仿了", "label": "完成体"}, {"form": "模仿过", "label": "经历体"}, {"form": "模仿着", "label": "持续体"}, {"form": "模仿者", "label": "复合"}], "register": "中性", "sense_fingerprint": "模仿|照着别人的样子做|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模仿", "is_correct": true, "explanation": "模仿 mófǎng：照着别人的样子做，是正确答案。"}, {"text": "魔法", "is_correct": false, "explanation": "魔法 mófǎ 去掉了 fǎng 末尾的 ng，韵母由 ǎng 变为 ǎ，意思是魔力。"}, {"text": "磨房", "is_correct": false, "explanation": "磨房 mófáng 第二字声调改为第二声，意思是磨面的屋子。"}, {"text": "魔方", "is_correct": false, "explanation": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。"}], "explanations": {"模仿": "模仿 mófǎng：照着别人的样子做，是正确答案。", "魔法": "魔法 mófǎ 去掉了 fǎng 末尾的 ng，韵母由 ǎng 变为 ǎ，意思是魔力。", "磨房": "磨房 mófáng 第二字声调改为第二声，意思是磨面的屋子。", "魔方": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。"}, "sentence_index": null, "correct_answer": "模仿"}, "level_3": {"options": [{"text": "模仿", "is_correct": true, "explanation": "正确：模仿指照着别人的动作做，与“一边看视频，一边跳舞”一致。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，不能带“跳舞”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象是物体，不能洗跳舞。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是机器、物品，不能修理跳舞。"}], "explanations": {"模仿": "正确：模仿指照着别人的动作做，与“一边看视频，一边跳舞”一致。", "睡觉": "配价：睡觉是不及物动词，不能带“跳舞”作宾语。", "洗": "搭配：洗的对象是物体，不能洗跳舞。", "修理": "搭配：修理的对象是机器、物品，不能修理跳舞。"}, "sentence_index": 0, "correct_answer": "模仿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家模仿了宇宙的形成。", "explanation": "这里应该用〈模拟〉。模仿是照着别人的样子做，宇宙的形成不是可以照着学的对象；用模型或计算再现过程要用模拟。"}, {"text": "他模仿了这笔开支。", "explanation": "这里应该用〈计算〉。模仿指学别人的样子，算开支要用计算，“模仿开支”说不通。"}, {"text": "这首诗模仿了战争的残酷。", "explanation": "这里应该用〈反映〉。模仿指照着别人的做法学做，描写战争的残酷要用反映。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22840, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "模仿", "is_correct": true, "explanation": "模仿 mófǎng：照着别人的样子做，是正确答案。"}, {"text": "模范", "is_correct": false, "explanation": "模范 mófàn 与 mófǎng 的韵尾不同（fàn 与 fǎng 的 ng），声调也不同，意思是榜样。"}, {"text": "魔方", "is_correct": false, "explanation": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。"}, {"text": "磨坊", "is_correct": false, "explanation": "磨坊 mòfáng 两个字的声调都与 mófǎng 不同，意思是磨面用的作坊。"}], "explanations": {"模仿": "模仿 mófǎng：照着别人的样子做，是正确答案。", "模范": "模范 mófàn 与 mófǎng 的韵尾不同（fàn 与 fǎng 的 ng），声调也不同，意思是榜样。", "魔方": "魔方 mófāng 与 mófǎng 只有第二个字声调不同（第一声与第三声），意思是立方体玩具。", "磨坊": "磨坊 mòfáng 两个字的声调都与 mófǎng 不同，意思是磨面用的作坊。"}, "sentence_index": null, "correct_answer": "模仿"}, "level_3": {"options": [{"text": "模仿", "is_correct": true, "explanation": "正确：模仿指学别人的样子做，与“演员……过很多有名的人”一致。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：咳嗽不带宾语，不能说咳嗽过很多有名的人。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：扔的对象是具体物体，不能扔人。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不能唱人。"}], "explanations": {"模仿": "正确：模仿指学别人的样子做，与“演员……过很多有名的人”一致。", "咳嗽": "配价：咳嗽不带宾语，不能说咳嗽过很多有名的人。", "扔": "搭配：扔的对象是具体物体，不能扔人。", "唱": "搭配：唱的对象是歌曲，不能唱人。"}, "sentence_index": 6, "correct_answer": "模仿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈模仿了房间。", "explanation": "这里应该用〈整理〉。模仿指学别人的样子，收拾房间要用整理，“模仿房间”说不通。"}, {"text": "医生模仿了病人的身体。", "explanation": "这里应该用〈检查〉。模仿指照着别人的样子学做，给病人身体做诊断要用检查。"}, {"text": "他模仿了电费。", "explanation": "这里应该用〈缴纳〉。模仿指学别人的样子，交电费要用缴纳，“模仿电费”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,