INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得不多不少，刚刚好。", "primary_collocate": null, "pronunciation": "tiáo jié", "ipa": "tʰiau˧˥ tɕiɛ˧˥", "syllable_count": 2, "sentences": [{"text": "你可以自己调节空调的温度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把声音调节得小一点儿。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝茶来调节心情。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮可以调节灯的亮度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体会自己调节温度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能帮你调节情绪。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈调节了一下水的冷热。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在调节电视的颜色。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么调节呼吸。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，我们用机器调节屋里的湿度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调节了", "label": "体标（了）"}, {"form": "调节过", "label": "体标（过）"}, {"form": "调节器", "label": "复合"}, {"form": "自我调节", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，把温度、声音、情绪等调整到合适的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c1a906-ea1f-4e51-bb2e-ae63d5c674b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确答案：调节 tiáo jié，使事物的程度适中。"}, {"text": "调解", "is_correct": false, "explanation": "调解 tiáo jiě 与 调节 tiáo jié 第二个音节声调不同（jiě 与 jié），意思是劝说双方和解。"}, {"text": "调教", "is_correct": false, "explanation": "调教 tiáo jiào 与 调节 tiáo jié 第二个音节韵母不同（jiào 与 jié），意思是训练、管教。"}, {"text": "跳接", "is_correct": false, "explanation": "跳接 tiào jiē 与 调节 tiáo jié 两个音节声调都不同，意思是影片剪辑中跳过一段直接连接。"}], "explanations": {"调节": "正确答案：调节 tiáo jié，使事物的程度适中。", "调解": "调解 tiáo jiě 与 调节 tiáo jié 第二个音节声调不同（jiě 与 jié），意思是劝说双方和解。", "调教": "调教 tiáo jiào 与 调节 tiáo jié 第二个音节韵母不同（jiào 与 jié），意思是训练、管教。", "跳接": "跳接 tiào jiē 与 调节 tiáo jié 两个音节声调都不同，意思是影片剪辑中跳过一段直接连接。"}, "sentence_index": null, "correct_answer": "调节"}, "level_3": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确：“调节空调的温度”指调整到合适的程度，符合语境。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火或可燃物，不能用于“温度”。"}, {"text": "背诵", "is_correct": false, "explanation": "语义：“背诵”是念记文字，“背诵空调的温度”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“温度”作宾语。"}], "explanations": {"调节": "正确：“调节空调的温度”指调整到合适的程度，符合语境。", "点燃": "搭配：“点燃”用于火或可燃物，不能用于“温度”。", "背诵": "语义：“背诵”是念记文字，“背诵空调的温度”说不通。", "散步": "配价：“散步”是不及物动词，不能带“温度”作宾语。"}, "sentence_index": 0, "correct_answer": "调节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很难，我们应该调节它。", "explanation": "这里应该用〈解决〉。调节指使事物的程度适中，问题要通过〈解决〉来处理。"}, {"text": "他去调节两个人的身高。", "explanation": "这里应该用〈比较〉。身高是固定的，不能调节；“调节”只用于可以调整程度的事物。"}, {"text": "他正在调节那件破损的古董。", "explanation": "这里应该用〈修复〉。调节指调整程度使其刚刚好，破损的古董要用〈修复〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确：“调节水的冷热”指把水温调到合适的程度，符合语境。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割是把物体切开，不能用来调节水的冷热。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：朗读是念出文字，不能用于水的冷热。"}, {"text": "跳跃", "is_correct": false, "explanation": "配价：“跳跃”是不及物动词，不能带“水的冷热”作宾语。"}], "explanations": {"调节": "正确：“调节水的冷热”指把水温调到合适的程度，符合语境。", "切割": "语义：切割是把物体切开，不能用来调节水的冷热。", "朗读": "语义：朗读是念出文字，不能用于水的冷热。", "跳跃": "配价：“跳跃”是不及物动词，不能带“水的冷热”作宾语。"}, "sentence_index": 6, "correct_answer": "调节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天，我们用湿度计调节屋里的湿度。", "explanation": "这里应该用〈测量〉。湿度计用于测量湿度，不能调节湿度，调节湿度要用加湿器等设备。"}, {"text": "冬天，我们用机器调节屋里的歌曲。", "explanation": "这里应该用〈播放〉。调节用于调整温度、音量等程度，歌曲要说“播放”。"}, {"text": "他被调节到了另一个部门。", "explanation": "这里应该用〈调〉。“调到”指人员调动，调节只用于调整程度，不能用来指调动人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个开关可以调节了风扇的速度。", "corrected_sentence": "这个开关可以调节风扇的速度。", "error_description": "“可以”后面的动词不能再加“了”，“调节了”是错误的，应为“可以调节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在调节了电视的音量。", "corrected_sentence": "我正在调节电视的音量。", "error_description": "“正在”表示动作进行中，不能与“了”同用；“调节”后多余的“了”应去掉，应说“我正在调节电视的音量”，不能说“我正在调节了电视的音量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停用", "is_correct": true, "explanation": "停用：与“激活”意思相反，指让账号、功能停止使用。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步：同为动词，但与“激活”没有反义或近义关系。"}, {"text": "画画", "is_correct": false, "explanation": "画画：同为动词，但与“激活”没有反义或近义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡：同为动词，但与“激活”没有反义或近义关系。"}], "correct_answer": "停用", "explanations": {"停用": "停用：与“激活”意思相反，指让账号、功能停止使用。", "跑步": "跑步：同为动词，但与“激活”没有反义或近义关系。", "画画": "画画：同为动词，但与“激活”没有反义或近义关系。", "洗澡": "洗澡：同为动词，但与“激活”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "关闭：与“激活”意思相反，指让设备、账号停止运作。"}, {"text": "读书", "is_correct": false, "explanation": "读书：同为动词，但与“激活”没有反义或近义关系。"}, {"text": "切菜", "is_correct": false, "explanation": "切菜：同为动词，但与“激活”没有反义或近义关系。"}, {"text": "穿衣", "is_correct": false, "explanation": "穿衣：同为动词，但与“激活”没有反义或近义关系。"}], "correct_answer": "关闭", "explanations": {"关闭": "关闭：与“激活”意思相反，指让设备、账号停止运作。", "读书": "读书：同为动词，但与“激活”没有反义或近义关系。", "切菜": "切菜：同为动词，但与“激活”没有反义或近义关系。", "穿衣": "穿衣：同为动词，但与“激活”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西开始工作或动起来。", "primary_collocate": null, "pronunciation": "jī huó", "ipa": "tɕi˥ xwo˨˦", "syllable_count": 2, "sentences": [{"text": "新手机买回来后，要先激活。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请输入激活码，激活这个软件。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打电话激活了新银行卡。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏账号还没激活，你不能用。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新电脑要先联网激活，才能使用。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点一下这个按钮，就能激活系统。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张会员卡要在手机上激活才能用。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机激活成功后，你会收到短信。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了激活账号，所以登不进去。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把新电话卡放进手机，然后激活。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激活了", "label": "完成体"}, {"form": "激活过", "label": "经验体"}], "register": "中性", "sense_fingerprint": "使设备、账号、系统等开始工作或进入可用状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激活", "is_correct": true, "explanation": "激活：使手机开始可用，与“要先”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”针对食物，不能用来说手机。"}, {"text": "摔坏", "is_correct": false, "explanation": "语义：摔坏的手机不能用，与“要先”的步骤不符，句意不通。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：买回来的新手机刚开始使用就丢掉，与常理相反。"}], "explanations": {"激活": "激活：使手机开始可用，与“要先”搭配，符合句意。", "煮": "搭配：“煮”针对食物，不能用来说手机。", "摔坏": "语义：摔坏的手机不能用，与“要先”的步骤不符，句意不通。", "丢弃": "语义：买回来的新手机刚开始使用就丢掉，与常理相反。"}, "sentence_index": 0, "correct_answer": "激活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机一上车就激活了这一天。", "explanation": "这里应该用〈开始〉。激活用于设备、账号、系统等，“这一天”不是这类对象。"}, {"text": "早上的闹钟激活了我。", "explanation": "这里应该用〈唤醒〉。激活指使设备、账号等开始可用，叫醒人要用唤醒。"}, {"text": "夏天到了，他激活了窗户。", "explanation": "这里应该用〈打开〉。激活只用于设备、账号、系统等，开窗户要用打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激活", "is_correct": true, "explanation": "激活：让会员卡开始可用，与“才能用”呼应。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”要用复印机处理纸质材料，不能在手机上复印会员卡。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除卡片后就无法使用，与“才能用”的意思相反。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：撕掉会员卡就不能再使用，与“才能用”相矛盾。"}], "explanations": {"激活": "激活：让会员卡开始可用，与“才能用”呼应。", "复印": "搭配：“复印”要用复印机处理纸质材料，不能在手机上复印会员卡。", "删除": "语义：删除卡片后就无法使用，与“才能用”的意思相反。", "撕掉": "语义：撕掉会员卡就不能再使用，与“才能用”相矛盾。"}, "sentence_index": 6, "correct_answer": "激活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都激活衣服。", "explanation": "这里应该用〈洗〉。激活用于设备、账号、系统，使其开始可用，洗衣服要用洗。"}, {"text": "他用火柴激活了蜡烛。", "explanation": "这里应该用〈点燃〉。激活指使设备、账号等开始可用，点蜡烛要用点燃。"}, {"text": "他用热水激活了冻肉。", "explanation": "这里应该用〈解冻〉。激活指使设备、账号等开始可用，让冻肉恢复常温要用解冻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚买的平板电脑还没激活了。", "corrected_sentence": "我刚买的平板电脑还没激活。", "error_description": "错误：“还没激活了”，“还没”与动词后的“了”不能同时使用。正确：“还没激活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天激活着新手机。", "corrected_sentence": "我昨天激活了新手机。", "error_description": "错误：“昨天激活着”，激活是一下子完成的动作，说过去完成的事要用“了”，不用“着”。正确：“昨天激活了新手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
