INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22858, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示除了这个，还有别的。", "primary_collocate": null, "pronunciation": "hái yǒu", "ipa": "xaɪ˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我买了苹果，还有香蕉。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有书，还有一杯茶。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说英语，还有法语。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天要买菜，还有水果。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢猫，还有小狗。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一个哥哥，还有两个妹妹。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包里有书和本子，还有一把伞。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过北京，还有上海。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有十个男生，还有八个女生。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带护照，还有钱。", "target_word": "还有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接并列项，表示除前面所说的以外再补充别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还有", "is_correct": true, "explanation": "连词，表示在前面所说的以外再补充别的东西，与“苹果”并列，句意通顺。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，“买了”已经发生，不能再说“或者香蕉”。"}, {"text": "而是", "is_correct": false, "explanation": "语义：“而是”表示更正前面的说法，与“买了苹果”的事实相矛盾。"}, {"text": "还是", "is_correct": false, "explanation": "搭配：“还是”用于在几种情况中选择，不能与“买了”后的补充搭配。"}], "explanations": {"还有": "连词，表示在前面所说的以外再补充别的东西，与“苹果”并列，句意通顺。", "或者": "语义：“或者”表示选择，“买了”已经发生，不能再说“或者香蕉”。", "而是": "语义：“而是”表示更正前面的说法，与“买了苹果”的事实相矛盾。", "还是": "搭配：“还是”用于在几种情况中选择，不能与“买了”后的补充搭配。"}, "sentence_index": 0, "correct_answer": "还有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很大，还有很亮。", "explanation": "这里应该用〈而且〉。“还有”后面要接名词，不能接形容词“很亮”，应该用“而且”。"}, {"text": "我们吃了饭，还有看了电影。", "explanation": "这里应该用〈还〉。“还有”后面要接名词，补充动作要用“还”，不用“还有”。"}, {"text": "他会说英语，还有会说法语。", "explanation": "这里应该用〈还会〉。“还有”后面要接名词，表示又会做某事要用“还会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还有", "is_correct": true, "explanation": "连词，表示除了前面的书和本子，还要补充一把伞，句意通顺。"}, {"text": "或", "is_correct": false, "explanation": "语域：“或”是书面语，“或一把伞”表示选择，与前面的并列补充不相符。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与前面的并列补充相反，句子不通。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，前后并没有因果关系，句子不通。"}], "explanations": {"还有": "连词，表示除了前面的书和本子，还要补充一把伞，句意通顺。", "或": "语域：“或”是书面语，“或一把伞”表示选择，与前面的并列补充不相符。", "但是": "语义：“但是”表示转折，与前面的并列补充相反，句子不通。", "因为": "语义：“因为”表示原因，前后并没有因果关系，句子不通。"}, "sentence_index": 6, "correct_answer": "还有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他还有回家。", "explanation": "这里应该用〈还没〉。“还有”表示增加或剩余，不表示“尚未”；说事情还没完成要用“还没回家”。"}, {"text": "这件衣服还有漂亮。", "explanation": "这里应该用〈更〉。“还有”不能直接接形容词，比较程度要用“更”，应说“更漂亮”。"}, {"text": "我还有喜欢中国菜。", "explanation": "这里应该用〈也〉。表示同样的喜爱要用“也”，“还有”后面要接名词，不能接“喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了面包，还有没牛奶。", "corrected_sentence": "我们买了面包，还有牛奶。", "error_description": "“还有”表示再补充，前面不能加“没”；表示尚未发生应说“还没有”，此处应说“还有牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上有电脑，还有了手机。", "corrected_sentence": "桌子上有电脑，还有手机。", "error_description": "表示补充的“还有”后面不带“了”，应说“还有手机”；多出的“了”使句子不符合用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
