INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很累的感觉。", "primary_collocate": null, "pronunciation": "pí bèi", "ipa": "pʰi˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "一杯热茶让我忘了一天的疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗个热水澡，能洗去一身疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脸上露出了深深的疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感到一阵疲惫，想马上睡觉。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的疲惫让她没有力气做饭。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的旅行消除了他的疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想让家人看出自己的疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐让人暂时忘记生活的疲惫。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眼里满是疲惫，却还在笑。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到孩子的笑声，所有的疲惫都没了。", "target_word": "疲惫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一身疲惫", "label": "搭配形式"}, {"form": "疲憊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作为名词的一种很累的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疲惫", "is_correct": true, "explanation": "“疲惫”指很累的感觉，与“忘了一天的……”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以忘掉的感受，句子说不通。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是嗅觉对象，不是一天的累感，句子说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“忘了”接感受或事情，“价格”是标价，不能说忘了一天的价格。"}], "explanations": {"疲惫": "“疲惫”指很累的感觉，与“忘了一天的……”相符。", "天气": "语义：天气不是可以忘掉的感受，句子说不通。", "香味": "语义：香味是嗅觉对象，不是一天的累感，句子说不通。", "价格": "搭配：“忘了”接感受或事情，“价格”是标价，不能说忘了一天的价格。"}, "sentence_index": 0, "correct_answer": "疲惫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了安全，司机要避免疲惫驾驶。", "explanation": "这里应该用〈疲劳〉。“疲劳驾驶”是固定说法，“疲惫”不用于驾驶。"}, {"text": "我今天的疲惫很充沛，想出去跑步。", "explanation": "这里应该用〈精力〉。“充沛”形容精力、体力，“疲惫”不能用“充沛”修饰。"}, {"text": "他在会上发表了疲惫，大家都看着他。", "explanation": "这里应该用〈意见〉。“发表”搭配意见、看法等，“疲惫”是劳累的感觉，不能被发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疲惫", "is_correct": true, "explanation": "“疲惫”指累的感觉，与“不想让家人看出”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是心里的感受，“看出自己的颜色”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是情绪，不能被“看出”。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“看出”接心思、情绪，“礼貌”是行为规范，不能说看出自己的礼貌。"}], "explanations": {"疲惫": "“疲惫”指累的感觉，与“不想让家人看出”的语境相符。", "颜色": "语义：颜色不是心里的感受，“看出自己的颜色”说不通。", "名字": "语义：名字不是情绪，不能被“看出”。", "礼貌": "搭配：“看出”接心思、情绪，“礼貌”是行为规范，不能说看出自己的礼貌。"}, "sentence_index": 6, "correct_answer": "疲惫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的伤口一阵阵疲惫，疼得睡不着。", "explanation": "这里应该用〈疼痛〉。“疲惫”是劳累的感觉，不能用来形容伤口的痛。"}, {"text": "这次旅行的路费很疲惫，我们只好省着花。", "explanation": "这里应该用〈贵〉。“疲惫”指人的劳累感，不用来形容钱的多少。"}, {"text": "这块蛋糕的味道很疲惫，大家都没吃完。", "explanation": "这里应该用〈难吃〉。“疲惫”指人的劳累，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我突然感到一阵疲惫着，想坐下来。", "corrected_sentence": "我突然感到一阵疲惫，想坐下来。", "error_description": "体态错误：“疲惫”表示一种感觉，不能用“着”表示持续，“疲惫着”应去掉“着”，改为“一阵疲惫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他脸上露出了一个疲惫。", "corrected_sentence": "他脸上露出了一丝疲惫。", "error_description": "量词错误：“疲惫”作为感觉的名词，量词常用“丝”“阵”，“一个疲惫”应改为“一丝疲惫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是一定、不会变的意思。", "primary_collocate": null, "pronunciation": "kěn dìng", "ipa": "kʰən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他肯定会来参加明天的会。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天这么黑，现在肯定很晚了。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样做，他肯定不高兴。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，这件事我肯定帮你。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看这云，下午肯定要下雨。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么难的题，他肯定不会做。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯还亮着，他肯定在家。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他肯定是忘了，所以没有回电话。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你放心，我肯定准时到。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学了十年，肯定说得很好。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示推断或决心上的一定、必然", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定会来”表示推断或决心上一定会，符合语境。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”须与否定词连用，如“从来不来”，不能直接用在“会来”前。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与句中的“明天”冲突。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与将来的“明天”不能搭配。"}], "explanations": {"肯定": "正确：“肯定会来”表示推断或决心上一定会，符合语境。", "从来": "搭配：“从来”须与否定词连用，如“从来不来”，不能直接用在“会来”前。", "曾经": "语义：“曾经”指过去，与句中的“明天”冲突。", "刚": "语义：“刚”表示刚刚发生，与将来的“明天”不能搭配。"}, "sentence_index": 0, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他肯定会来参加明天的会，但概率很低。", "explanation": "这里应该用〈可能〉。“肯定”表示一定，与“概率很低”的不确定语义矛盾；表示不确定时用“可能”。"}, {"text": "他肯定会来，也许不会。", "explanation": "这里应该用〈可能〉。“肯定”表示一定，与后面的“也许不会”自相矛盾；表示不确定时用“可能”。"}, {"text": "他肯定会来参加明天的会，但我不确定。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“不确定”的语义相矛盾；表示不确定时用“也许”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定在家”表示推断一定，与“灯还亮着”的线索相符。"}, {"text": "拿", "is_correct": false, "explanation": "配价：「拿」需带宾语（拿东西），「他拿在家」不成句。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：「哭」不能直接接「在家」，「他哭在家」不成句。"}, {"text": "再", "is_correct": false, "explanation": "搭配：“再”表示重复或继续，不能直接修饰“在家”来表示推断。"}], "explanations": {"肯定": "正确：“肯定在家”表示推断一定，与“灯还亮着”的线索相符。", "拿": "配价：「拿」需带宾语（拿东西），「他拿在家」不成句。", "哭": "搭配：「哭」不能直接接「在家」，「他哭在家」不成句。", "再": "搭配：“再”表示重复或继续，不能直接修饰“在家”来表示推断。"}, "sentence_index": 6, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她学了十年，肯定可能说得很好。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“可能”的不确定语义矛盾，不能并用。"}, {"text": "她学了十年，肯定说得很好，但我不太确定。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“不太确定”的语义相矛盾，表示不确定时用“也许”。"}, {"text": "她学了十年，肯定或许说得很好。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“或许”的不确定语义相矛盾，不能并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她肯定的会同意这个计划。", "corrected_sentence": "她肯定会同意这个计划。", "error_description": "副词“肯定”后不能加“的”，“肯定”直接修饰“会”，应说“肯定会”，不说“肯定的会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗户开着，他肯定的在房间里。", "corrected_sentence": "窗户开着，他肯定在房间里。", "error_description": "副词“肯定”直接修饰后面的动词，中间不能加“的”，应说“肯定在”，不说“肯定的在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
