INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机制是让事情按照一定规律运行的办法或系统。", "primary_collocate": null, "pronunciation": "jī zhì", "ipa": "tɕi˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司建立了新的奖励机制。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机制让工作更有效率。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场机制能让价格自然变化。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想建立一个公平的竞争机制。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的监督机制可以减少错误。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体有自己的保护机制。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机制每个月自动检查一次。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先了解机制，再解决问题。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机制让申请手续简单多了。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的工作机制需要改进。", "target_word": "机制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运行机制", "label": "复合"}, {"form": "市场机制", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指使事物或组织按一定规律运行的办法、系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机制", "is_correct": true, "explanation": "机制：指使事情按一定规律运行的办法或系统，是本词。"}, {"text": "鸡汁", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“鸡汁”指鸡肉熬成的汤汁。"}, {"text": "鸡翅", "is_correct": false, "explanation": "chì 与 zhì 声母不同（ch 与 zh），韵母和声调相同，“鸡翅”指鸡的翅膀。"}, {"text": "资质", "is_correct": false, "explanation": "zī 与 jī 声母不同（z 与 j），声调相同，“资质”指资格和素质。"}, {"text": "机试", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“机试”指上机考试。"}], "explanations": {"机制": "机制：指使事情按一定规律运行的办法或系统，是本词。", "鸡汁": "zhī（第一声）与 zhì（第四声）声调不同，“鸡汁”指鸡肉熬成的汤汁。", "鸡翅": "chì 与 zhì 声母不同（ch 与 zh），韵母和声调相同，“鸡翅”指鸡的翅膀。", "资质": "zī 与 jī 声母不同（z 与 j），声调相同，“资质”指资格和素质。", "机试": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“机试”指上机考试。"}, "sentence_index": null, "correct_answer": "机制"}, "level_3": {"options": [{"text": "机制", "is_correct": true, "explanation": "机制：本句的答案，指使事情按规律运行的系统，可以“建立”。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：“奖杯”是实物，不是可以“建立”的办法或系统。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“建立”不与“颜色”搭配，“颜色”也不指奖励的办法。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“建立”不与“蛋糕”搭配，蛋糕不是奖励的办法或系统。"}], "explanations": {"机制": "机制：本句的答案，指使事情按规律运行的系统，可以“建立”。", "奖杯": "语义：“奖杯”是实物，不是可以“建立”的办法或系统。", "颜色": "搭配：“建立”不与“颜色”搭配，“颜色”也不指奖励的办法。", "蛋糕": "搭配：“建立”不与“蛋糕”搭配，蛋糕不是奖励的办法或系统。"}, "sentence_index": 0, "correct_answer": "机制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的机制很好，我们出去玩吧。", "explanation": "这里应该用〈天气〉。机制指系统或办法，不能用来说晴天、下雨。"}, {"text": "昨天我吃了一个很好的机制。", "explanation": "这里应该用〈饭菜〉。机制指系统或办法，不是可以吃的东西。"}, {"text": "这座山的机制很高，我们爬了一上午。", "explanation": "这里应该用〈高度〉。机制指系统或办法，不能用来说山的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22864, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机制", "is_correct": true, "explanation": "机制：本词，指使事情按一定规律运行的办法或系统。"}, {"text": "极致", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，“极致”指达到的最高程度。"}, {"text": "极值", "is_correct": false, "explanation": "jí zhí 两个音节的声调都与 jī zhì 不同，“极值”指数学中的最大或最小值。"}, {"text": "机器", "is_correct": false, "explanation": "qì 与 zhì 声母不同（q 与 zh），声调相同，“机器”指利用动力工作的装置。"}], "explanations": {"机制": "机制：本词，指使事情按一定规律运行的办法或系统。", "极致": "jí（第二声）与 jī（第一声）声调不同，“极致”指达到的最高程度。", "极值": "jí zhí 两个音节的声调都与 jī zhì 不同，“极值”指数学中的最大或最小值。", "机器": "qì 与 zhì 声母不同（q 与 zh），声调相同，“机器”指利用动力工作的装置。"}, "sentence_index": null, "correct_answer": "机制"}, "level_3": {"options": [{"text": "机制", "is_correct": true, "explanation": "机制：本句的答案，指能自动运行、可以定期检查的系统。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是吃的东西，不能被“自动检查”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“自动检查”多用于系统或设备，不说“歌曲”被自动检查。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”是说话的声音特点，不能被“自动检查”。"}], "explanations": {"机制": "机制：本句的答案，指能自动运行、可以定期检查的系统。", "午饭": "语义：“午饭”是吃的东西，不能被“自动检查”。", "歌曲": "搭配：“自动检查”多用于系统或设备，不说“歌曲”被自动检查。", "口音": "语义：“口音”是说话的声音特点，不能被“自动检查”。"}, "sentence_index": 6, "correct_answer": "机制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都穿一件很好的机制。", "explanation": "这里应该用〈衣服〉。机制指系统或办法，不是可以穿的东西。"}, {"text": "这次考试，他考了一个好机制。", "explanation": "这里应该用〈成绩〉。考试的结果是成绩，机制不能说成“考了”的结果。"}, {"text": "他的机制很白，笑起来很好看。", "explanation": "这里应该用〈牙齿〉。机制指系统或办法，不能用来形容人的牙齿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司正在完善一只内部的沟通机制。", "corrected_sentence": "公司正在完善一套内部的沟通机制。", "error_description": "量词错误：“机制”应与量词“套”搭配，说“一套……机制”；“只”用于动物或小件物品，不能修饰“机制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一套公平地奖励机制。", "corrected_sentence": "我们需要一套公平的奖励机制。", "error_description": "结构助词错误：“公平”修饰名词“奖励机制”，应用“的”，写作“公平的奖励机制”；“地”用于修饰动词，这里修饰的是名词，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。"}, {"text": "答案", "is_correct": false, "explanation": "「答案」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "故事", "is_correct": false, "explanation": "「故事」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "礼物", "is_correct": false, "explanation": "「礼物」与「秘密」没有反义关系，二者不构成对立。"}], "correct_answer": "公开", "explanations": {"公开": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。", "答案": "「答案」与「秘密」没有反义关系，二者不构成对立。", "故事": "「故事」与「秘密」没有反义关系，二者不构成对立。", "礼物": "「礼物」与「秘密」没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。"}, {"text": "日记", "is_correct": false, "explanation": "「日记」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "消息", "is_correct": false, "explanation": "「消息」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "窗户", "is_correct": false, "explanation": "「窗户」与「秘密」没有反义关系，二者不构成对立。"}], "correct_answer": "公开", "explanations": {"公开": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。", "日记": "「日记」与「秘密」没有反义关系，二者不构成对立。", "消息": "「消息」与「秘密」没有反义关系，二者不构成对立。", "窗户": "「窗户」与「秘密」没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当事人不想让别人知道的事。", "primary_collocate": null, "pronunciation": "mì mì", "ipa": "mi˥˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "我知道他的一个大秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友把秘密告诉了我，我不能说。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子也有自己的小秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个秘密只有妈妈知道。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怕同事知道这个秘密，一直很小心。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有守住秘密，第二天大家都知道了。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么秘密不想让人知道吗？", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的秘密不能随便说出去。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好，永远不说这个秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在信里写下了心里的秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "当事人不愿让别人知道的私事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "「一个大秘密」指他不愿让别人知道的事，符合题干语境。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：「苹果」是看得见的东西，不是「知道」的对象，「知道他的一个大苹果」不通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：「杯子」是物品，不能被「知道」，句子不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是家具，不是可以「知道」的事情，句子不通。"}], "explanations": {"秘密": "「一个大秘密」指他不愿让别人知道的事，符合题干语境。", "苹果": "语义：「苹果」是看得见的东西，不是「知道」的对象，「知道他的一个大苹果」不通。", "杯子": "语义：「杯子」是物品，不能被「知道」，句子不通。", "椅子": "语义：「椅子」是家具，不是可以「知道」的事情，句子不通。"}, "sentence_index": 0, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请输入你的登录秘密。", "explanation": "这里应该用〈密码〉。登录时输入的是“密码”，“秘密”指别人不想让人知道的事。"}, {"text": "这座老房子的气氛很秘密。", "explanation": "这里应该用〈神秘〉。形容气氛的隐秘感要用“神秘”；“秘密”作形容词多指不公开的事，搭配“气氛”不自然。"}, {"text": "他藏起了一根秘密，谁也不知道。", "explanation": "这里应该用〈个〉。“根”用于线、绳、刺等细长的东西，“秘密”不能用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "「什么秘密」指别人不知道的事，「不想让人知道」与之相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以隐藏的事情，「你有什么天气不想让人知道」不成立。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是家具，不是需要隐瞒的事，「你有什么椅子不想让人知道」不成立。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：「脸色」是外露的神情，无法像秘密那样刻意隐藏，与「不想让人知道」不搭。"}], "explanations": {"秘密": "「什么秘密」指别人不知道的事，「不想让人知道」与之相合。", "天气": "语义：「天气」不是可以隐藏的事情，「你有什么天气不想让人知道」不成立。", "椅子": "语义：「椅子」是家具，不是需要隐瞒的事，「你有什么椅子不想让人知道」不成立。", "脸色": "体貌：「脸色」是外露的神情，无法像秘密那样刻意隐藏，与「不想让人知道」不搭。"}, "sentence_index": 6, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她心里藏着一张秘密。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，“秘密”用“个”计量。"}, {"text": "他心里揣着一只秘密。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，不用于“秘密”。"}, {"text": "他把一封秘密交给了我。", "explanation": "这里应该用〈个〉。“封”用于信件，“秘密”不能用“封”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很会保护秘密。", "corrected_sentence": "他很会保守秘密。", "error_description": "“秘密”的固定搭配是“保守秘密”，不说“保护秘密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没有告诉任何人这本秘密。", "corrected_sentence": "她没有告诉任何人这个秘密。", "error_description": "“秘密”用“个”计量，“本”用于书籍等，不说“这本秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "正确。紧张指心里或身体处于绷紧状态，与放松是反义词。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾指整理东西，与放松没有反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存指把东西保存起来，与放松没有反义关系。"}, {"text": "沟通", "is_correct": false, "explanation": "沟通指互相交流，与放松没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "正确。紧张指心里或身体处于绷紧状态，与放松是反义词。", "收拾": "收拾指整理东西，与放松没有反义关系。", "储存": "储存指把东西保存起来，与放松没有反义关系。", "沟通": "沟通指互相交流，与放松没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "正确。紧张指心里或身体处于绷紧状态，与放松是反义词。"}, {"text": "出发", "is_correct": false, "explanation": "出发指离开某地前往别处，与放松没有反义关系。"}, {"text": "修改", "is_correct": false, "explanation": "修改指改正或更改文字、计划，与放松没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用头脑分析问题，与放松没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "正确。紧张指心里或身体处于绷紧状态，与放松是反义词。", "出发": "出发指离开某地前往别处，与放松没有反义关系。", "修改": "修改指改正或更改文字、计划，与放松没有反义关系。", "思考": "思考指用头脑分析问题，与放松没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让身体或心里不紧张，变得舒服。", "primary_collocate": null, "pronunciation": "fàng sōng", "ipa": "faŋ˥˩ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "周末我想在家放松放松。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着轻音乐，她慢慢放松下来。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泡个热水澡，让身体放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里我们去海边放松。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累了，他想出去放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她躺在沙发上，完全放松了。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了朋友家，我一下子放松了。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常玩游戏来放松自己。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝杯热茶，放松一下心情。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常常散步，放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放松了", "label": "体标"}, {"form": "放松过", "label": "体标"}, {"form": "放松放松", "label": "重叠"}, {"form": "放鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "休息、玩乐，让自己不紧张而舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“周末我想在家放松放松”中的“放松”指让身体或心里不紧张、变得舒服。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，不能说“在家毕业毕业”，句意不通。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“在家”与“出差”不搭，出差要离开家。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是紧张的竞技活动，与“在家放松”的意思相反。"}], "explanations": {"放松": "正确。“周末我想在家放松放松”中的“放松”指让身体或心里不紧张、变得舒服。", "毕业": "语义：“毕业”指完成学业，不能说“在家毕业毕业”，句意不通。", "出差": "搭配：“在家”与“出差”不搭，出差要离开家。", "比赛": "语义：比赛是紧张的竞技活动，与“在家放松”的意思相反。"}, "sentence_index": 0, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的记性很放松，常常忘事。", "explanation": "这里应该用〈减退〉。记性变差要用“减退”，“放松”指不紧张而舒服，不能用于记性。"}, {"text": "这项运动能放松身体里的能量。", "explanation": "这里应该用〈释放〉。能量要用“释放”，“放松”不能和能量搭配。"}, {"text": "这台电脑很放松，运行起来很慢。", "explanation": "这里应该用〈缓慢〉。机器运行的快慢要用“缓慢”，“放松”不能用于形容机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“我一下子放松了”指到了朋友家后心里不再紧张，变得舒服。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指到得太晚，与“到了朋友家”后心情放松的描述不相符，句意不通。"}, {"text": "出门", "is_correct": false, "explanation": "语义：已经“到了朋友家”，就不能再说“出门”，二者矛盾。"}, {"text": "启程", "is_correct": false, "explanation": "搭配：“启程”指开始出发，常接“去”“前往”，不能用于已经到达之后。"}], "explanations": {"放松": "正确。“我一下子放松了”指到了朋友家后心里不再紧张，变得舒服。", "迟到": "语义：“迟到”指到得太晚，与“到了朋友家”后心情放松的描述不相符，句意不通。", "出门": "语义：已经“到了朋友家”，就不能再说“出门”，二者矛盾。", "启程": "搭配：“启程”指开始出发，常接“去”“前往”，不能用于已经到达之后。"}, "sentence_index": 6, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把走路的速度放松了一些。", "explanation": "这里应该用〈放慢〉。速度要用“放慢”，“放松”表示身体或心里不紧张。"}, {"text": "他放松了这次难得的机会。", "explanation": "这里应该用〈放弃〉。机会要用“放弃”，“放松”不能用于机会。"}, {"text": "吃了药以后，他的头痛放松了。", "explanation": "这里应该用〈缓解〉。疼痛的减轻要用“缓解”，“放松”不用于形容疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他玩很放松。", "corrected_sentence": "他玩得很放松。", "error_description": "错误：“玩很放松”。动词后接描述状态的补语，中间要用“得”连接。正确为“玩得很放松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她放松的坐在沙发上。", "corrected_sentence": "她放松地坐在沙发上。", "error_description": "错误：“放松的坐”。修饰动词的状语要用“地”，“的”用于名词前。正确为“放松地坐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糊涂", "is_correct": true, "explanation": "正确。糊涂指头脑不明白，与“遇事心里明白、不糊涂”相对，是反义词。"}, {"text": "热情", "is_correct": false, "explanation": "热情指待人友好、积极主动，与清醒没有反义关系。"}, {"text": "慌张", "is_correct": false, "explanation": "慌张指心里着急、乱了主张，它不是清醒的反义词，与清醒没有对立关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌或事物好看，与清醒的心里明白无关。"}], "correct_answer": "糊涂", "explanations": {"糊涂": "正确。糊涂指头脑不明白，与“遇事心里明白、不糊涂”相对，是反义词。", "热情": "热情指待人友好、积极主动，与清醒没有反义关系。", "慌张": "慌张指心里着急、乱了主张，它不是清醒的反义词，与清醒没有对立关系。", "漂亮": "漂亮指外貌或事物好看，与清醒的心里明白无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糊涂", "is_correct": true, "explanation": "正确。糊涂指头脑不明白，与“心里清楚、不糊涂”相对，是反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事物头绪多、不简单，与清醒没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松指不费力、没有负担，与清醒没有反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "陈旧指时间久、不新鲜，与清醒没有反义关系。"}], "correct_answer": "糊涂", "explanations": {"糊涂": "正确。糊涂指头脑不明白，与“心里清楚、不糊涂”相对，是反义词。", "复杂": "复杂指事物头绪多、不简单，与清醒没有反义关系。", "轻松": "轻松指不费力、没有负担，与清醒没有反义关系。", "陈旧": "陈旧指时间久、不新鲜，与清醒没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里清楚，不糊涂。", "primary_collocate": null, "pronunciation": "qīng xǐng", "ipa": "tɕʰiŋ˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家都很激动，只有他一个人很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到大事，我们要保持清醒的头脑。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很清醒，知道这个人不能相信。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赢了比赛以后，教练仍然很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的问题看得很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生气的时候，人很难清醒地想事情。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话让我清醒了，我不该再等了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头脑清醒，不会相信这些好话。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时要清醒，不要乱花钱。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他清醒地知道，自己做错了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清醒了", "label": "体标"}, {"form": "清醒地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "遇事心里明白、不糊涂、不冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631ef3ed-ddad-4c43-9d8e-a459e421b3a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。"}, {"text": "轻信", "is_correct": false, "explanation": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。"}, {"text": "轻型", "is_correct": false, "explanation": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。"}, {"text": "惊醒", "is_correct": false, "explanation": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。", "轻信": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。", "轻型": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。", "惊醒": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“只有他一个人很清醒”指在众人激动时他仍然冷静明白，“只有”引出对比。"}, {"text": "激动", "is_correct": false, "explanation": "语义：前句已说“大家都很激动”，“只有”要求他与众人不同，再说“很激动”前后矛盾。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”与“大家都很激动”的状态相同，与“只有他一个人”的对比不符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多形容场面，不能说一个人“很热闹”。"}], "explanations": {"清醒": "正确。“只有他一个人很清醒”指在众人激动时他仍然冷静明白，“只有”引出对比。", "激动": "语义：前句已说“大家都很激动”，“只有”要求他与众人不同，再说“很激动”前后矛盾。", "兴奋": "语义：“兴奋”与“大家都很激动”的状态相同，与“只有他一个人”的对比不符。", "热闹": "搭配：“热闹”多形容场面，不能说一个人“很热闹”。"}, "sentence_index": 0, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把这道题讲得很清醒。", "explanation": "这里应该用〈清楚〉。清醒说人遇事心里明白，讲解是否清楚要用“清楚”。"}, {"text": "这盏台灯很清醒，屋里照得很亮。", "explanation": "这里应该用〈明亮〉。灯光的亮度要用“明亮”，“清醒”只用于形容人心里清楚、不糊涂，不能用于灯。"}, {"text": "这句话的意思很清醒。", "explanation": "这里应该用〈明白〉。“意思”是否明白要用“明白”，清醒不能形容话的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。"}, {"text": "清新", "is_correct": false, "explanation": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。"}, {"text": "情形", "is_correct": false, "explanation": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。"}, {"text": "庆幸", "is_correct": false, "explanation": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。", "清新": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。", "情形": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。", "庆幸": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。", "清洗": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“朋友的话让我清醒了”指听了朋友的话后头脑转过来、看清了情况，与后句“我不该再等了”的醒悟相符。"}, {"text": "麻木", "is_correct": false, "explanation": "语义：“麻木”指失去感觉，与“让我……了”的触动以及“我不该再等了”的醒悟相反。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容身材或建筑，不能说“朋友的话让我高大了”。"}, {"text": "木讷", "is_correct": false, "explanation": "语义：“木讷”形容人反应迟钝、不善言辞，不能说明听了话后的改变和醒悟。"}], "explanations": {"清醒": "正确。“朋友的话让我清醒了”指听了朋友的话后头脑转过来、看清了情况，与后句“我不该再等了”的醒悟相符。", "麻木": "语义：“麻木”指失去感觉，与“让我……了”的触动以及“我不该再等了”的醒悟相反。", "高大": "语义：“高大”形容身材或建筑，不能说“朋友的话让我高大了”。", "木讷": "语义：“木讷”形容人反应迟钝、不善言辞，不能说明听了话后的改变和醒悟。"}, "sentence_index": 6, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的歌声很清醒，听得大家都入迷了。", "explanation": "这里应该用〈清亮〉。清亮形容声音明亮、透彻，清醒只用于人的头脑。"}, {"text": "她长得很清醒，皮肤白白的。", "explanation": "这里应该用〈清秀〉。清秀形容相貌清爽秀丽，清醒不能形容长相。"}, {"text": "晚风很清醒，吹在脸上很舒服。", "explanation": "这里应该用〈清凉〉。风的凉爽要用“清凉”，清醒不用于形容风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她清醒的看出了这件事的问题。", "corrected_sentence": "她清醒地看出了这件事的问题。", "error_description": "错误：“清醒的看出”。修饰动词的状语要用“地”，“的”用于名词前。正确为“清醒地看出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听了朋友的话，他清醒的很快。", "corrected_sentence": "听了朋友的话，他清醒得很快。", "error_description": "错误：“清醒的很快”。表示程度或结果的补语，要用“得”连接，“的”用于名词前。正确为“清醒得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf7a2c3-4aa6-4201-810b-22b39b6ad6b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
