INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "看起来好像", "primary_collocate": null, "pronunciation": "kàn sì", "ipa": "kʰan⁵¹ sɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "天空看似要下雨，路上的人都走得很快。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看似很累，一回家就睡了。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只狗看似很凶，其实很怕人。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座山看似很近，走了两个小时才到。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看似三十岁，其实已经五十岁了。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子看似很轻，搬起来却很重。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这碗汤看似清淡，喝起来味道很浓。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看似在听课，其实正在想别的事。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服看似很旧，穿着却很舒服。", "target_word": "看似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里看似没有人，其实有一个学生在睡觉。", "target_word": "看似", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "外表给人的印象，看起来好像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示从外表做出推断，符合天空阴沉、人们走得快的情境。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”要求有意志的主语，天空不能“打算”下雨。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”需要有意愿的主语，句子描述的是天空的样子。"}, {"text": "据说", "is_correct": false, "explanation": "语义：“据说”表示转述听来的传闻，句中说的是说话人对天空的观察，不能用它。"}], "explanations": {"看似": "“看似”表示从外表做出推断，符合天空阴沉、人们走得快的情境。", "打算": "语义：“打算”要求有意志的主语，天空不能“打算”下雨。", "希望": "语义：“希望”需要有意愿的主语，句子描述的是天空的样子。", "据说": "语义：“据说”表示转述听来的传闻，句中说的是说话人对天空的观察，不能用它。"}, "sentence_index": 0, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌看似很好听，我听了一遍就喜欢上了。", "explanation": "这里应该用〈听起来〉。看似表示依据外在迹象的推断，而说话人已亲自听过，应直接用〈听起来〉，不能用“看似”。"}, {"text": "老师看似说明天放假，同学们都欢呼起来了。", "explanation": "这里应该用〈据说〉。看似只表示看到的外表印象，别人口头告知的消息不能用它来表示。"}, {"text": "他看似是我的哥哥，我们从小一起长大。", "explanation": "这里应该用〈确实〉。看似只表示外表给人的印象，兄弟关系是确定的事实，用它会显得含糊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示外表印象，与“喝起来味道很浓”形成转折，符合句意。"}, {"text": "是", "is_correct": false, "explanation": "语义：“是”断定汤清淡，与“喝起来味道很浓”直接矛盾。"}, {"text": "觉得", "is_correct": false, "explanation": "配价：“觉得”需要有感知能力的主语，“汤”不能“觉得”清淡。"}, {"text": "变得", "is_correct": false, "explanation": "语义：“变得”表示变化过程，句子描述的是当下的口感，不符。"}], "explanations": {"看似": "“看似”表示外表印象，与“喝起来味道很浓”形成转折，符合句意。", "是": "语义：“是”断定汤清淡，与“喝起来味道很浓”直接矛盾。", "觉得": "配价：“觉得”需要有感知能力的主语，“汤”不能“觉得”清淡。", "变得": "语义：“变得”表示变化过程，句子描述的是当下的口感，不符。"}, "sentence_index": 6, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看似进了房间，我亲眼看见他走进去的。", "explanation": "这里应该用〈确实〉。看似只表示外表给人的印象，亲眼看见的事实不能用它来表示推测。"}, {"text": "我看似在哪儿见过他，却想不起来了。", "explanation": "这里应该用〈好像〉。看似描述从外部看到的样子，说话人对自己记忆的感觉不能用它。"}, {"text": "明天的会议看似在三点举行，通知上写得清清楚楚。", "explanation": "这里应该用〈确定〉。会议时间已写在通知上，是确定的安排，看似只表示外表印象，会让安排显得不确定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片看似了很旧，其实是新拍的。", "corrected_sentence": "这张照片看似很旧，其实是新拍的。", "error_description": "错误形式：“看似了很旧”。正确形式：“看似很旧”。原因：“看似”表示外表印象，后面不能加动态助词“了”，应直接接副词“很”和形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路看似的很近，其实要走一个小时。", "corrected_sentence": "这条路看似很近，其实要走一个小时。", "error_description": "错误形式：“看似的”。正确形式：“看似”。原因：“看似”后不接结构助词“的”，它直接接形容词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
