INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22880, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你说出你的想法。", "primary_collocate": null, "pronunciation": "tí chū", "ipa": "tʰi˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他在会上提出了一个问题。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家提出自己的想法。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明向老师提出一个办法。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提出一点意见。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提出要换一个房间。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户提出了新的要求。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题可以随时提出来。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的计划，大家都同意。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理提出把会议改到明天。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家提出了很多好建议。", "target_word": "提出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提出了", "label": "体标"}, {"form": "提出过", "label": "体标"}, {"form": "提出来", "label": "方向补语"}, {"form": "提出", "label": "原形"}], "register": "中性", "sense_fingerprint": "把问题、意见、要求等说出来让别人考虑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提出", "is_correct": true, "explanation": "“提出”表示把问题说出来供别人考虑，这里指他在会上说出了一个问题。"}, {"text": "做", "is_correct": false, "explanation": "搭配：会上的“问题”是用来提出的，“做了一个问题”在会议语境中不自然，应说“提出”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与会议上的发言无关，句子荒谬。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，不能用来指会上的问题，句意说不通。"}], "explanations": {"提出": "“提出”表示把问题说出来供别人考虑，这里指他在会上说出了一个问题。", "做": "搭配：会上的“问题”是用来提出的，“做了一个问题”在会议语境中不自然，应说“提出”。", "吃": "语义：“吃”指进食，与会议上的发言无关，句子荒谬。", "洗": "语义：“洗”指清洁，不能用来指会上的问题，句意说不通。"}, "sentence_index": 0, "correct_answer": "提出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房提出了晚饭。", "explanation": "这里应该用〈做〉。“提出”用于问题、意见、要求，做饭要说〈做〉。"}, {"text": "这个月我们的效率提出了不少。", "explanation": "这里应该用〈提高〉。“提出”用于意见、要求，效率、水平的上升要说〈提高〉。"}, {"text": "孩子们在台上提出了一首歌。", "explanation": "这里应该用〈唱〉。“提出”用于意见、要求，唱歌要说〈唱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提出", "is_correct": true, "explanation": "“提出”表示把问题说出来，与“有问题可以随时提出来”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热做饭，与问题无关，“煮出来”说不通。"}, {"text": "掏", "is_correct": false, "explanation": "语义：“掏”指从口袋或容器里取出实物，问题不是可以掏出的东西。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象应是具体的东西，不能说“搬出来”一个问题。"}], "explanations": {"提出": "“提出”表示把问题说出来，与“有问题可以随时提出来”的语境相符。", "煮": "语义：“煮”是加热做饭，与问题无关，“煮出来”说不通。", "掏": "语义：“掏”指从口袋或容器里取出实物，问题不是可以掏出的东西。", "搬": "搭配：“搬”的对象应是具体的东西，不能说“搬出来”一个问题。"}, "sentence_index": 6, "correct_answer": "提出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航班提出了两个小时。", "explanation": "这里应该用〈提前〉。“提出”指说出想法或要求，表示时间向前移要说〈提前〉。"}, {"text": "火车提出了三十公里。", "explanation": "这里应该用〈提速〉。“提出”指说出想法或要求，表示速度加快要说〈提速〉。"}, {"text": "他用力把门提出了。", "explanation": "这里应该用〈关上〉。“提出”指说出想法或要求，关门要说〈关上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事你要尽早提出去。", "corrected_sentence": "这件事你要尽早提出来。", "error_description": "“提出”后面表示“说出来”的方向应接“来”，不能接“去”，应改为“提出来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天向经理提出着加班的要求。", "corrected_sentence": "她昨天向经理提出了加班的要求。", "error_description": "错误：“提出”是一次完成的动作，过去发生的事不能用“着”，应改为“提出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
