INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氧气是呼吸要用的气。", "primary_collocate": null, "pronunciation": "yǎng qì", "ipa": "jɑŋ˨˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "病人呼吸很难受，医生给他用上了氧气。", "target_word": "氧气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的氧气比山下少，我有点喘。", "target_word": "氧气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物白天会放出氧气。", "target_word": "氧气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人没有氧气就不能呼吸。", "target_word": "氧气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "潜水的人背着一瓶氧气下海。", "target_word": "氧气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里没有窗户，氧气越来越少。", "target_word": "氧气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些树林能给城市带来很多新鲜的氧气。", "target_word": "氧气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬到五千米高的地方，氧气很少，大家都走得很慢。", "target_word": "氧气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里也要呼吸，水里的氧气不够，鱼会死。", "target_word": "氧气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这里的氧气太少了，快开窗吧。", "target_word": "氧气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶氧气", "label": "量词"}, {"form": "氧氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人和动物呼吸所需的空气成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拐杖", "is_correct": false, "explanation": "语义：拐杖是行走时用的器具，给病人用上拐杖无法解决呼吸困难。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能用在病人身上。"}, {"text": "氧气", "is_correct": true, "explanation": "正确：氧气是给病人吸入的气体，“医生给他用上了氧气”语义通顺。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不是医疗时“用上”的器具或气体。"}], "explanations": {"拐杖": "语义：拐杖是行走时用的器具，给病人用上拐杖无法解决呼吸困难。", "作业": "语义：作业是学习任务，不能用在病人身上。", "氧气": "正确：氧气是给病人吸入的气体，“医生给他用上了氧气”语义通顺。", "饮料": "语义：饮料是喝的东西，不是医疗时“用上”的器具或气体。"}, "sentence_index": 0, "correct_answer": "氧气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间里的氧气很潮湿，我们开开窗吧。", "explanation": "这里应该用〈空气〉。潮湿指空气中水分多，氧气是无色气体，不能说它潮湿。"}, {"text": "这条河的氧气很清。", "explanation": "这里应该用〈水〉。清澈用来形容水，氧气看不见，不能说它清。"}, {"text": "这碗汤里的氧气太咸了，我喝不下去。", "explanation": "这里应该用〈盐〉。咸是盐的味道，氧气是呼吸用的气体，不能说它咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘是脏的颗粒，不能说“新鲜的灰尘”，树林不会带来灰尘。"}, {"text": "氧气", "is_correct": true, "explanation": "正确：氧气是树林释放的气体，“新鲜的氧气”搭配自然。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“新鲜”不能修饰温度，“新鲜的温度”不成搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：树林带来的不会是桌子，句子不合逻辑。"}], "explanations": {"灰尘": "语义：灰尘是脏的颗粒，不能说“新鲜的灰尘”，树林不会带来灰尘。", "氧气": "正确：氧气是树林释放的气体，“新鲜的氧气”搭配自然。", "温度": "搭配：“新鲜”不能修饰温度，“新鲜的温度”不成搭配。", "桌子": "语义：树林带来的不会是桌子，句子不合逻辑。"}, "sentence_index": 6, "correct_answer": "氧气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个喇叭的氧气很大，全校都听得见。", "explanation": "这里应该用〈声音〉。声音的响度要用“大”来形容，氧气不是声音，不能说它很大。"}, {"text": "这朵花的氧气很鲜艳，大家都夸它漂亮。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，氧气是无色的，不能说它鲜艳。"}, {"text": "这个箱子的氧气很重，两个人才抬得动。", "explanation": "这里应该用〈重量〉。物体有多重要用重量来说，氧气不能用来形容物体的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给病人换上了一只氧气。", "corrected_sentence": "医生给病人换上了一瓶氧气。", "error_description": "量词错误：“一只氧气”应为“一瓶氧气”。氧气常装在钢瓶里，应用量词“瓶”；“只”用于动物或成对的器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天都要喝氧气。", "corrected_sentence": "我们每天都要吸氧气。", "error_description": "动词搭配错误：「喝氧气」应为「吸氧气」。氧气是气体，要用「吸」，「喝」用于水、饮料等液体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃下去或喝进去。", "primary_collocate": null, "pronunciation": "shè rù", "ipa": "ʂɤ˥˩ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "他今天只摄入了一杯牛奶。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人刚做完手术，不能摄入油腻的东西。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上他摄入了一些粥。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝每天要摄入足够的奶。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员比赛前不能摄入太多食物。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她减肥时每天摄入的食物很少。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热，要多摄入一些水。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷牙不好，只能摄入软的食物。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者术后三天只能摄入流质食物。", "target_word": "摄入", "complexity_tier": "T3", "furigana": "huànzhě shù hòu sān tiān zhǐ néng shèrù liúzhí shíwù", "sentence_source": "generated"}, {"text": "晚上不要摄入太多食物，会睡不好。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摄入了", "label": "完成体"}, {"form": "摄入过", "label": "经历体"}, {"form": "摄入量", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "把食物或饮品吃下去、喝进去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：“摄入”表示把牛奶喝进体内，与“只……了一杯牛奶”相符。"}, {"text": "投资", "is_correct": false, "explanation": "语义：“投资”指投入资金，与喝牛奶无关。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指同意或许可，不能指饮用一杯牛奶。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语多为问题、话题，不说“讨论了一杯牛奶”。"}], "explanations": {"摄入": "正确：“摄入”表示把牛奶喝进体内，与“只……了一杯牛奶”相符。", "投资": "语义：“投资”指投入资金，与喝牛奶无关。", "批准": "语义：“批准”指同意或许可，不能指饮用一杯牛奶。", "讨论": "搭配：“讨论”的宾语多为问题、话题，不说“讨论了一杯牛奶”。"}, "sentence_index": 0, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摄入了一本小说。", "explanation": "这里应该用〈读〉。“摄入”指把食物或饮品吃下去、喝进去，不能用于读书。"}, {"text": "他摄入了一场比赛。", "explanation": "这里应该用〈参加〉。“摄入”只用于物质的吸收，不能用于比赛。"}, {"text": "我们摄入了整个博物馆。", "explanation": "这里应该用〈参观〉。“摄入”不能用于地点，参观博物馆要说“参观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：“摄入”表示喝进水，与“天气热，要多……一些水”的语境相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，水不能被书写，与补水无关。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指拍打，不能用来表示补充水分。"}, {"text": "排放", "is_correct": false, "explanation": "搭配：“排放”多接废水、废气，与“多……一些水”的补水语境不搭。"}], "explanations": {"摄入": "正确：“摄入”表示喝进水，与“天气热，要多……一些水”的语境相符。", "写": "语义：“写”指书写文字，水不能被书写，与补水无关。", "拍": "语义：“拍”指拍打，不能用来表示补充水分。", "排放": "搭配：“排放”多接废水、废气，与“多……一些水”的补水语境不搭。"}, "sentence_index": 6, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真摄入了老师的建议。", "explanation": "这里应该用〈听取〉。“摄入”只用于吃喝等物质，不能用于建议。"}, {"text": "我们摄入了这幅画。", "explanation": "这里应该用〈欣赏〉。“摄入”只表示把物质吃进或喝进去，不能用于画。"}, {"text": "她摄入了很大的压力。", "explanation": "这里应该用〈承受〉。“摄入”不能用于压力，承受压力要说“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天只摄入了了一些蔬菜。", "corrected_sentence": "他今天只摄入了一些蔬菜。", "error_description": "错误在于“了”重复。“摄入”后只需一个“了”，多写的一个“了”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天只摄入了少量的盐。", "corrected_sentence": "他明天只摄入少量的盐。", "error_description": "错误在于“了”。“明天”指将来，不能与表示完成的“了”同用，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
