INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示在某个地方或某个时候。", "primary_collocate": null, "pronunciation": "chǔ yú", "ipa": "ʈʂʰu˨˩˦ y˧˥", "syllable_count": 2, "sentences": [{"text": "这个小镇处于大山和大海之间。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校处于城市的中心。", "target_word": "处于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个村子处于大河的南边。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国处于亚洲的东部。", "target_word": "处于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个公园处于市中心，交通很方便。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场处于城市的西边，离这儿很远。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在正处于考试期间，请大家安静。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的房间处于二楼最里面。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家医院处于两条大路的中间。", "target_word": "处于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山处于两国的边界上。", "target_word": "处于", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "處於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处于|位于某个地方或某个时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：chǔ yú，表示在某个地方或某个时候。"}, {"text": "出于", "is_correct": false, "explanation": "chū（第一声）与 chǔ（第三声）声调不同，意思是产生于、出自。"}, {"text": "厨余", "is_correct": false, "explanation": "chú（第二声）与 chǔ（第三声）声调不同，意思是厨房里剩下的食物。"}, {"text": "出狱", "is_correct": false, "explanation": "chū yù（第一声、第四声）与 chǔ yú（第三声、第二声）声调不同，意思是从监狱里放出来。"}], "explanations": {"处于": "正确：chǔ yú，表示在某个地方或某个时候。", "出于": "chū（第一声）与 chǔ（第三声）声调不同，意思是产生于、出自。", "厨余": "chú（第二声）与 chǔ（第三声）声调不同，意思是厨房里剩下的食物。", "出狱": "chū yù（第一声、第四声）与 chǔ yú（第三声、第二声）声调不同，意思是从监狱里放出来。"}, "sentence_index": null, "correct_answer": "处于"}, "level_3": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：“处于大山和大海之间”表示位于两者中间，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于表示地点，句意不通。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”的对象是产品，不能说“生产……之间”。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”要接动作性成分，不能接表示地点的“大山和大海之间”。"}], "explanations": {"处于": "正确：“处于大山和大海之间”表示位于两者中间，符合句意。", "吃": "语义：“吃”不能用于表示地点，句意不通。", "生产": "语义：“生产”的对象是产品，不能说“生产……之间”。", "进行": "配价：“进行”要接动作性成分，不能接表示地点的“大山和大海之间”。"}, "sentence_index": 0, "correct_answer": "处于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快处于这个问题。", "explanation": "这里应该用〈解决〉。“处于”表示位置或状态，不能用来指解决问题。"}, {"text": "老师向学生处于新课本。", "explanation": "这里应该用〈介绍〉。“处于”表示位置或状态，不能用来指向学生介绍课本。"}, {"text": "工人们正在处于公路。", "explanation": "这里应该用〈修建〉。“处于”表示位置或状态，不能表示修建道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处于", "is_correct": true, "explanation": "正确：“处于考试期间”表示正处在考试这段时间，符合句意。"}, {"text": "位于", "is_correct": false, "explanation": "语义：“位于”指空间方位，不能用于时间。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事情出现，不能接“考试期间”这个时段。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”要接具体的考试、审核或路线，不能接“考试期间”这个时段。"}], "explanations": {"处于": "正确：“处于考试期间”表示正处在考试这段时间，符合句意。", "位于": "语义：“位于”指空间方位，不能用于时间。", "发生": "语义：“发生”指事情出现，不能接“考试期间”这个时段。", "通过": "配价：“通过”要接具体的考试、审核或路线，不能接“考试期间”这个时段。"}, "sentence_index": 6, "correct_answer": "处于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂处于汽车。", "explanation": "这里应该用〈生产〉。“处于”表示所在的位置或状态，不能用来指生产产品。"}, {"text": "老师处于他。", "explanation": "这里应该用〈批评〉。“处于”不能表示对人的批评。"}, {"text": "大家处于她的勇敢。", "explanation": "这里应该用〈赞美〉。“处于”不能表示对勇敢的赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小岛处于两条航线。", "corrected_sentence": "这座小岛处于两条航线之间。", "error_description": "错误：“处于”后面要有“之间”这样的方位词，只说“处于两条航线”意思不完整。正确：“处于两条航线之间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖在处于两座高山之间。", "corrected_sentence": "这个湖处于两座高山之间。", "error_description": "错误：“处于”前面多加了“在”。“处于”本身已表示位置，不能再与“在”连用。正确：“这个湖处于两座高山之间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
