INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体把没用的东西排出去，同时把有用的东西变出来。", "primary_collocate": null, "pronunciation": "dài xiè", "ipa": "taɪ̯⁵¹ ɕjɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "年轻人的代谢比老人快。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子长身体，代谢特别快。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多出汗也是身体代谢的一部分。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡不好觉，代谢就会变差。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天跑步，代谢一直很好。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最近代谢变慢了，吃得不多也会胖。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的代谢一般比较慢。", "target_word": "代谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早睡早起对身体的代谢很有好处。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈说，年纪大了代谢就慢了。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "身体的代谢出了问题，人就容易生病。", "target_word": "代谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新陈代谢", "label": "复合"}, {"form": "代谢率", "label": "复合"}, {"form": "代謝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体排出废物并生成有用物质，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代谢", "is_correct": true, "explanation": "正确答案。代谢（dài xiè）：身体排出废物、生成有用物质的过程。"}, {"text": "代写", "is_correct": false, "explanation": "dàixiě（第三声）与 dàixiè（第四声）只差第二个音节的声调，意思是替别人写文章或作业。"}, {"text": "带血", "is_correct": false, "explanation": "xuè 与 xiè 的韵母不同（ue 与 ie），意思是带有血迹。"}, {"text": "带些", "is_correct": false, "explanation": "dàixiē（第一声）与 dàixiè（第四声）只差第二个音节的声调，意思是携带一些（东西）。"}], "explanations": {"代谢": "正确答案。代谢（dài xiè）：身体排出废物、生成有用物质的过程。", "代写": "dàixiě（第三声）与 dàixiè（第四声）只差第二个音节的声调，意思是替别人写文章或作业。", "带血": "xuè 与 xiè 的韵母不同（ue 与 ie），意思是带有血迹。", "带些": "dàixiē（第一声）与 dàixiè（第四声）只差第二个音节的声调，意思是携带一些（东西）。"}, "sentence_index": null, "correct_answer": "代谢"}, "level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "正确。“年轻人的代谢比老人快”指新陈代谢的速度快，代谢是这里唯一能与“快”搭配并符合句意的词。"}, {"text": "视力", "is_correct": false, "explanation": "语义：“快”描述速度，视力不能说快慢，句子表达的意思不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：寿命说长短，不说快慢，“寿命比老人快”不成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温说高低，句中说的是速度，“体温比老人快”与句意不符。"}], "explanations": {"代谢": "正确。“年轻人的代谢比老人快”指新陈代谢的速度快，代谢是这里唯一能与“快”搭配并符合句意的词。", "视力": "语义：“快”描述速度，视力不能说快慢，句子表达的意思不通。", "寿命": "搭配：寿命说长短，不说快慢，“寿命比老人快”不成立。", "体温": "语义：体温说高低，句中说的是速度，“体温比老人快”与句意不符。"}, "sentence_index": 0, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑步一小时能让身体代谢大量的精力。", "explanation": "这里应该用〈消耗〉。代谢指身体内物质的转化与排出，精力不是物质，应说“消耗大量精力”。"}, {"text": "运动能代谢心情。", "explanation": "这里应该用〈调节〉。代谢只用于身体内物质的转化与排出，不能用来说心情，应说“调节心情”。"}, {"text": "他一边看书，一边代谢着空气。", "explanation": "这里应该用〈呼吸〉。呼吸指吸入空气、排出废气，代谢指身体内物质的转化与排出，不表示吸入空气，应说“呼吸空气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢", "is_correct": true, "explanation": "正确。“老人的代谢一般比较慢”指老人身体的新陈代谢速度慢，代谢能与“慢”搭配，符合句意。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：视力说好坏，不说快慢，“视力比较慢”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重说轻重，不说快慢，“体重比较慢”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高说高矮，不说快慢，“身高比较慢”不成立。"}], "explanations": {"代谢": "正确。“老人的代谢一般比较慢”指老人身体的新陈代谢速度慢，代谢能与“慢”搭配，符合句意。", "视力": "搭配：视力说好坏，不说快慢，“视力比较慢”不成立。", "体重": "搭配：体重说轻重，不说快慢，“体重比较慢”不成立。", "身高": "搭配：身高说高矮，不说快慢，“身高比较慢”不成立。"}, "sentence_index": 6, "correct_answer": "代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多读书能让代谢变得更聪明。", "explanation": "这里应该用〈大脑〉。代谢指身体排出废物、生成有用物质的过程，不能说“聪明”，应说“让大脑变得更聪明”。"}, {"text": "免疫系统能代谢病毒。", "explanation": "这里应该用〈消灭〉。代谢是身体把物质转化、排出的过程，不能用来说消灭病毒，应说“消灭病毒”。"}, {"text": "医生用药代谢肺炎。", "explanation": "这里应该用〈治疗〉。代谢指身体内的物质转化与排出，不能用来说治疗疾病，应说“治疗肺炎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动后，代谢会快下来。", "corrected_sentence": "运动后，代谢会快起来。", "error_description": "错误：“快下来”；正确：“快起来”。“快起来”表示变快，“下来”表示由快变慢、由多变少，与“代谢变快”的意思相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多运动可以加宽代谢。", "corrected_sentence": "多运动可以加快代谢。", "error_description": "错误：“加宽代谢”；正确：“加快代谢”。代谢说快慢，不说宽窄，应与“加快”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "严重", "is_correct": true, "explanation": "严重指程度重，与“不严重”的轻度构成反义。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭形容地势倾斜度大，与病情轻重无关，不是反义词。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速指速度快，与“不严重”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，与“轻度”的程度义无关。"}], "correct_answer": "严重", "explanations": {"严重": "严重指程度重，与“不严重”的轻度构成反义。", "陡峭": "陡峭形容地势倾斜度大，与病情轻重无关，不是反义词。", "迅速": "迅速指速度快，与“不严重”没有反义关系。", "清楚": "清楚指明白、分明，与“轻度”的程度义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "严重", "is_correct": true, "explanation": "严重指程度重，与“不严重”的轻度构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事物构成繁多、难以理清，与病情轻重无关，不是反义词。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性情、态度柔和，与程度深浅无关。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与“轻度”的程度义无关。"}], "correct_answer": "严重", "explanations": {"严重": "严重指程度重，与“不严重”的轻度构成反义。", "复杂": "复杂指事物构成繁多、难以理清，与病情轻重无关，不是反义词。", "温柔": "温柔形容性情、态度柔和，与程度深浅无关。", "干净": "干净指没有污物，与“轻度”的程度义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示不严重，比如生病不厉害。", "primary_collocate": null, "pronunciation": "qīng dù", "ipa": "tɕʰiŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "我只是轻度发烧，休息一下就好。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我轻度近视，不戴眼镜也能看书。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子轻度咳嗽，不用吃药。", "target_word": "轻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她轻度过敏，吃药后好多了。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的腿轻度受伤，还能走路。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他只是轻度胃炎。", "target_word": "轻度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷有轻度耳聋，说话要大声点。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我轻度头疼，今天好了。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种轻度的病，不用太担心。", "target_word": "轻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开车时受了轻度外伤。", "target_word": "轻度", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "輕度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "轻度|不严重，如生病不厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻度", "is_correct": true, "explanation": "轻度：程度浅，与“只是”和“休息一下就好”相合，说明发烧不重。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“只是”说明病情轻，“严重发烧”与之矛盾，休息一下就好也说不通。"}, {"text": "长期", "is_correct": false, "explanation": "语义：“长期发烧”不能靠休息一下就好，与句意矛盾。"}, {"text": "危险", "is_correct": false, "explanation": "搭配：“危险”修饰情况或行为，不能用来修饰“发烧”。"}], "explanations": {"轻度": "轻度：程度浅，与“只是”和“休息一下就好”相合，说明发烧不重。", "严重": "语义：“只是”说明病情轻，“严重发烧”与之矛盾，休息一下就好也说不通。", "长期": "语义：“长期发烧”不能靠休息一下就好，与句意矛盾。", "危险": "搭配：“危险”修饰情况或行为，不能用来修饰“发烧”。"}, "sentence_index": 0, "correct_answer": "轻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我背着一个轻度的背包，走了一天也不累。", "explanation": "这里应该用〈轻〉。轻度只表示病情、伤势不重，不用来形容重量；东西分量小要用轻。"}, {"text": "她过着轻度的生活，没有什么压力。", "explanation": "这里应该用〈轻松〉。轻度只表示病情、伤势不重，不用来形容生活状态；生活没有压力要用轻松。"}, {"text": "他只是轻度地点了点头。", "explanation": "这里应该用〈轻轻〉。轻度用于疾病、损伤的程度，形容点头的动作要用轻轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻度", "is_correct": true, "explanation": "轻度：程度浅，修饰“耳聋”，说明听力受损不重，与“说话要大声点”相合。"}, {"text": "灵敏", "is_correct": false, "explanation": "语义：“灵敏”形容听觉好，与“耳聋”矛盾，“灵敏耳聋”说不通。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”指声音或图像分明，与耳聋的状态相反，不能用来描述这一病症。"}, {"text": "完好", "is_correct": false, "explanation": "搭配：“完好”指东西完整无损，不用来修饰病症。"}], "explanations": {"轻度": "轻度：程度浅，修饰“耳聋”，说明听力受损不重，与“说话要大声点”相合。", "灵敏": "语义：“灵敏”形容听觉好，与“耳聋”矛盾，“灵敏耳聋”说不通。", "清晰": "语义：“清晰”指声音或图像分明，与耳聋的状态相反，不能用来描述这一病症。", "完好": "搭配：“完好”指东西完整无损，不用来修饰病症。"}, "sentence_index": 6, "correct_answer": "轻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带了一把轻度的雨伞，出门很方便。", "explanation": "这里应该用〈轻便〉。轻度只表示病情、伤势程度浅，不用来形容物品的分量；东西轻巧好带要用轻便。"}, {"text": "她轻度地走进了房间。", "explanation": "这里应该用〈悄悄〉。轻度只表示病情、伤势程度浅，不用来形容走进的动作；无声无息地进门要用悄悄。"}, {"text": "她穿着一件轻度的外套，走在街上。", "explanation": "这里应该用〈轻薄〉。轻度只表示病情、伤势程度浅，不用来形容衣物的厚薄；衣服薄而轻要用轻薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次只是一轻度头疼，吃片药就好。", "corrected_sentence": "这次只是轻度头疼，吃片药就好。", "error_description": "错误：“轻度”前多出数词“一”，“一轻度头疼”结构不通，应删去“一”。正确：“这次只是轻度头疼，吃片药就好。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的膝盖只是轻度很扭伤，休息几天就好。", "corrected_sentence": "他的膝盖只是轻度扭伤，休息几天就好。", "error_description": "错误：“很”通常修饰形容词，不直接修饰动词“扭伤”。正确：去掉“很”，“轻度扭伤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
