INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水从一处流向另一处。", "primary_collocate": null, "pronunciation": "liú jīng", "ipa": "ljoʊ˧˥ tɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "澜沧江流经云南，再流向东南亚。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小溪流经山谷，发出好听的声音。", "target_word": "流经", "complexity_tier": "T3", "furigana": "xiǎo xī liú jīng shān gǔ, fā chū hǎo tīng de shēng yīn", "sentence_source": "generated"}, {"text": "河水流经小镇，慢慢流远了。", "target_word": "流经", "complexity_tier": "T3", "furigana": "hé shuǐ liú jīng xiǎo zhèn, màn màn liú yuǎn le", "sentence_source": "generated"}, {"text": "这条运河流经三个城市。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，山上的水流经小路，流到河里。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清水流经田地，让庄稼长得更好。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "莱茵河流经好几个国家。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水流经这里，所以河水很脏。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泉水流经竹林，最后流进小湖。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泉水流经草地，草长得又绿又密。", "target_word": "流经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流经了", "label": "体标"}, {"form": "流經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "水从一处流到另一处，途中经过某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf62e1-d33e-46df-96e9-4a4484bc7d82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流经", "is_correct": true, "explanation": "“流经云南”指江水从云南境内流过，与“再流向东南亚”连贯。"}, {"text": "汇入", "is_correct": false, "explanation": "搭配：“汇入”的宾语须是江河湖海，不能说汇入某个省份。"}, {"text": "淹没", "is_correct": false, "explanation": "语义：“淹没”指水漫过、覆盖某处，与河水“再流向东南亚”的走向不符。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”指离开很远，不表示河流从某地流过。"}], "explanations": {"流经": "“流经云南”指江水从云南境内流过，与“再流向东南亚”连贯。", "汇入": "搭配：“汇入”的宾语须是江河湖海，不能说汇入某个省份。", "淹没": "语义：“淹没”指水漫过、覆盖某处，与河水“再流向东南亚”的走向不符。", "远离": "语义：“远离”指离开很远，不表示河流从某地流过。"}, "sentence_index": 0, "correct_answer": "流经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她流经了三次考试。", "explanation": "这里应该用〈通过〉。流经只用于液体，考试要用“通过”。"}, {"text": "我们流经三个城市，一路很开心。", "explanation": "这里应该用〈穿过〉。流经指液体流过某地，人或车经过城市要用“穿过”。"}, {"text": "他在三个城市流经了童年。", "explanation": "这里应该用〈度过〉。流经只用于液体的流动，时间的过去要用“度过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流经", "is_correct": true, "explanation": "“流经好几个国家”指河流穿过多个国家，符合句意。"}, {"text": "访问", "is_correct": false, "explanation": "搭配：“访问”的主语多为人，不说河流访问国家。"}, {"text": "占领", "is_correct": false, "explanation": "语义：“占领”指军事行动，与河流的流动无关。"}, {"text": "统治", "is_correct": false, "explanation": "语义：“统治”指掌握权力，河流不会统治国家。"}], "explanations": {"流经": "“流经好几个国家”指河流穿过多个国家，符合句意。", "访问": "搭配：“访问”的主语多为人，不说河流访问国家。", "占领": "语义：“占领”指军事行动，与河流的流动无关。", "统治": "语义：“统治”指掌握权力，河流不会统治国家。"}, "sentence_index": 6, "correct_answer": "流经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他流经公园，去了图书馆。", "explanation": "这里应该用〈穿过〉。流经只用于水等液体，人走过公园要用“穿过”。"}, {"text": "鸟流经草地，真舒服。", "explanation": "这里应该用〈飞过〉。流经用于液体，鸟在天上飞过草地要用“飞过”。"}, {"text": "石头流经了草地。", "explanation": "这里应该用〈铺满〉。流经指液体从某处流过，石头铺在草地上要用“铺满”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河被流经山脚，一直流到村边。", "corrected_sentence": "这条河流经山脚，一直流到村边。", "error_description": "被字句错误：“流经”前不能加“被”，应说“这条河流经山脚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "溪水流经着石桥，慢慢流进村子。", "corrected_sentence": "溪水流经石桥，慢慢流进村子。", "error_description": "体标错误：“流经”后不能接“着”。直接说“流经石桥”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccd5d667-5798-4d63-99e1-2259594b78fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "严重", "is_correct": true, "explanation": "严重指程度重，与“不严重”的轻微构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事物构成繁多、难以理清，与伤势轻重无关，不是反义词。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速指速度快，与“不严重”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污物，与程度深浅无关。"}], "correct_answer": "严重", "explanations": {"严重": "严重指程度重，与“不严重”的轻微构成反义。", "复杂": "复杂指事物构成繁多、难以理清，与伤势轻重无关，不是反义词。", "迅速": "迅速指速度快，与“不严重”没有反义关系。", "干净": "干净指没有污物，与程度深浅无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "严重", "is_correct": true, "explanation": "严重指程度重，与“不严重”的轻微构成反义。"}, {"text": "优美", "is_correct": false, "explanation": "优美形容美好动人，与伤势轻重无关，不是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地松软、不坚硬，与程度深浅无关。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔指面积大，与“轻微”的程度义无关。"}], "correct_answer": "严重", "explanations": {"严重": "严重指程度重，与“不严重”的轻微构成反义。", "优美": "优美形容美好动人，与伤势轻重无关，不是反义词。", "柔软": "柔软指质地松软、不坚硬，与程度深浅无关。", "宽阔": "宽阔指面积大，与“轻微”的程度义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很小的，不严重。", "primary_collocate": null, "pronunciation": "qīng wēi", "ipa": "tɕʰiŋ˥ weɪ˥", "syllable_count": 2, "sentences": [{"text": "他的伤很轻微，不用住院。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震造成的损失很轻微。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的感冒症状很轻微。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两辆车相撞，司机只受了轻微的伤。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的病情轻微，吃点药就好。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾的影响比较轻微。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错误很轻微，老师没有批评他。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震很轻微，大家都没有感觉。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点轻微的疼痛，很快就会过去。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果显示，他的问题比较轻微。", "target_word": "轻微", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作谓语或定语，指伤病、损失、影响等不严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻微", "is_correct": true, "explanation": "轻微：形容伤势不严重，作谓语前加“很”，与“不用住院”相合。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”说伤势重，与“不用住院”矛盾，“伤很严重，不用住院”不通。"}, {"text": "猛烈", "is_correct": false, "explanation": "搭配：“猛烈”多修饰力量、攻势，不能用来形容伤。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”多形容声音、图像等，不能说“伤很清晰”。"}], "explanations": {"轻微": "轻微：形容伤势不严重，作谓语前加“很”，与“不用住院”相合。", "严重": "语义：“严重”说伤势重，与“不用住院”矛盾，“伤很严重，不用住院”不通。", "猛烈": "搭配：“猛烈”多修饰力量、攻势，不能用来形容伤。", "清晰": "搭配：“清晰”多形容声音、图像等，不能说“伤很清晰”。"}, "sentence_index": 0, "correct_answer": "轻微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来参加会议的人很轻微，只有三个。", "explanation": "这里应该用〈少〉。轻微说程度不深，不能用来形容人数多少；人数不多要用少。"}, {"text": "他的口袋里只有轻微的钱。", "explanation": "这里应该用〈一点〉。轻微说程度不深，不能用来形容钱的数量；口袋里钱不多要说“一点”。"}, {"text": "这箱苹果的重量很轻微，一个人就能搬动。", "explanation": "这里应该用〈轻〉。轻微说伤病、损失等程度不严重，不能用来形容物体的重量；重量小要说“轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻微", "is_correct": true, "explanation": "轻微：形容错误不严重，作谓语前加“很”，与“老师没有批评他”相合。"}, {"text": "严厉", "is_correct": false, "explanation": "搭配：“严厉”形容人的态度，不能用来形容错误。"}, {"text": "惨重", "is_correct": false, "explanation": "语义：“惨重”表示损失严重，与“老师没有批评他”的语境矛盾。"}, {"text": "凶狠", "is_correct": false, "explanation": "搭配：“凶狠”形容人或动物的样子，不能用来形容错误。"}], "explanations": {"轻微": "轻微：形容错误不严重，作谓语前加“很”，与“老师没有批评他”相合。", "严厉": "搭配：“严厉”形容人的态度，不能用来形容错误。", "惨重": "语义：“惨重”表示损失严重，与“老师没有批评他”的语境矛盾。", "凶狠": "搭配：“凶狠”形容人或动物的样子，不能用来形容错误。"}, "sentence_index": 6, "correct_answer": "轻微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事故造成了轻微的人员死亡，大家都很难过。", "explanation": "这里应该用〈重大〉。轻微表示程度不深，不能用来形容人员伤亡；伤亡程度大要用重大。"}, {"text": "这次事故他受了轻微的重伤，需要马上住院。", "explanation": "这里应该用〈严重〉。轻微表示程度不深，与“重伤”“马上住院”矛盾；描述伤势重要用严重。"}, {"text": "他和朋友吃了一顿轻微的晚餐，大家都很开心。", "explanation": "这里应该用〈丰盛〉。轻微表示程度不深，不能用来形容晚餐的分量；饭菜很多要用丰盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脚踝只是轻微的扭伤了，休息两天就好。", "corrected_sentence": "他的脚踝只是轻微地扭伤了，休息两天就好。", "error_description": "错误形式：“轻微的扭伤了”。正确形式：“轻微地扭伤了”。“轻微”修饰动词“扭伤”时作状语，要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手腕的伤是轻微，贴个膏药就行。", "corrected_sentence": "他手腕的伤很轻微，贴个膏药就行。", "error_description": "错误形式：“是轻微”。正确形式：“很轻微”。“轻微”作谓语时前面要加程度副词“很”，不能直接用“是”接它。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
