INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嘴巴里面的地方，有牙齿和舌头。", "primary_collocate": null, "pronunciation": "kǒu qiāng", "ipa": "kʰoʊ̯˨˩ t͡ɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "口腔里有牙齿和舌头。", "target_word": "口腔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的口腔很干，想喝水。", "target_word": "口腔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喝了热茶，口腔有点儿烫。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请张开嘴，我看看你的口腔。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的口腔里有一颗小牙。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了辣菜，我的口腔很热。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口腔里的舌头可以帮我们说话。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药要含在口腔里慢慢化开。", "target_word": "口腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙以后，我的口腔很清爽。", "target_word": "口腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的口腔很健康。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "口腔溃疡", "label": "复合"}, {"form": "口腔科", "label": "复合"}], "register": "中性", "sense_fingerprint": "口腔：嘴巴里面有牙齿和舌头的地方（日常浅显义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。口腔指嘴里有牙齿和舌头的地方，与句意一致。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃不在嘴里，不长牙齿和舌头，与句意不符。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：耳朵里没有牙齿，“耳朵里有牙齿和舌头”说不通。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子里不长牙齿，舌头也不在鼻子里，与句意冲突。"}], "explanations": {"口腔": "正确。口腔指嘴里有牙齿和舌头的地方，与句意一致。", "胃": "语义：胃不在嘴里，不长牙齿和舌头，与句意不符。", "耳朵": "搭配：耳朵里没有牙齿，“耳朵里有牙齿和舌头”说不通。", "鼻子": "语义：鼻子里不长牙齿，舌头也不在鼻子里，与句意冲突。"}, "sentence_index": 0, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他伸出口腔，让医生检查。", "explanation": "这里应该用〈舌头〉。伸出的是舌头，口腔是空腔，不能伸出。"}, {"text": "他的口腔掉了，很疼。", "explanation": "这里应该用〈牙齿〉。牙齿会脱落，口腔是整个空腔，不会掉。"}, {"text": "他把钥匙放进口腔里。", "explanation": "这里应该用〈口袋〉。钥匙要放进口袋，口腔是嘴里的空腔，放不下钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。舌头位于口腔内，“口腔里的舌头”指向的正是口腔。"}, {"text": "手", "is_correct": false, "explanation": "语义：舌头不在手里，“手里的舌头”与句意不符。"}, {"text": "脚", "is_correct": false, "explanation": "语义：舌头不长在脚上，“脚里的舌头”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：舌头不在眼睛里，也不能帮我们说话，与句意冲突。"}], "explanations": {"口腔": "正确。舌头位于口腔内，“口腔里的舌头”指向的正是口腔。", "手": "语义：舌头不在手里，“手里的舌头”与句意不符。", "脚": "语义：舌头不长在脚上，“脚里的舌头”说不通。", "眼睛": "语义：舌头不在眼睛里，也不能帮我们说话，与句意冲突。"}, "sentence_index": 6, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抿紧口腔，不说话。", "explanation": "这里应该用〈嘴唇〉。“抿”是嘴唇的动作，口腔在里面，看不见也抿不了。"}, {"text": "吃完饭，我的口腔很饱。", "explanation": "这里应该用〈胃〉。“饱”指胃吃足的感觉，口腔不会饱。"}, {"text": "他戴上口腔，出门了。", "explanation": "这里应该用〈耳机〉。“戴”用于可以戴在身上的物品，口腔是身体器官，不能戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗糖要放在口腔上慢慢化开。", "corrected_sentence": "这颗糖要放在口腔里慢慢化开。", "error_description": "错误形式“口腔上”，正确形式“口腔里”。口腔是一个空腔，糖要放在它的里面，所以用“里”，不用“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漱口以后，我的一颗口腔很清爽。", "corrected_sentence": "漱口以后，我的口腔很清爽。", "error_description": "错误：“我的一颗口腔”。正确：应说“我的口腔”，去掉量词“一颗”。“颗”用于圆小的东西，口腔不用“颗”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "正确：整体与局部相对，指全部、完整的事物，是“局部”的反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋指大片的水域，与局部没有反义关系。"}, {"text": "历史", "is_correct": false, "explanation": "历史指过去发生的事情，与局部没有反义关系。"}, {"text": "文化", "is_correct": false, "explanation": "文化指人类的精神和生活方式，与局部没有反义关系。"}], "correct_answer": "整体", "explanations": {"整体": "正确：整体与局部相对，指全部、完整的事物，是“局部”的反义词。", "海洋": "海洋指大片的水域，与局部没有反义关系。", "历史": "历史指过去发生的事情，与局部没有反义关系。", "文化": "文化指人类的精神和生活方式，与局部没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "正确：整体与局部相对，指全部、完整的事物，是“局部”的反义词。"}, {"text": "森林", "is_correct": false, "explanation": "森林指大片的树木，与局部没有反义关系。"}, {"text": "语言", "is_correct": false, "explanation": "语言指人们交流用的工具，与局部没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "音乐指由声音组成的艺术，与局部没有反义关系。"}], "correct_answer": "整体", "explanations": {"整体": "正确：整体与局部相对，指全部、完整的事物，是“局部”的反义词。", "森林": "森林指大片的树木，与局部没有反义关系。", "语言": "语言指人们交流用的工具，与局部没有反义关系。", "音乐": "音乐指由声音组成的艺术，与局部没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的一部分。", "primary_collocate": null, "pronunciation": "jú bù", "ipa": "tɕy˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这张照片只拍到了房子的局部。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只有手臂的局部受伤了。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个局部放大看看。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说，局部地区会下雨。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看画时，不要只看局部。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只了解事情的局部。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的局部有一点脏。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局部的问题不会影响整个计划。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只拍下了这座桥的局部。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先看整体，再看局部。", "target_word": "局部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "局部地区", "label": "复合"}, {"form": "局部麻醉", "label": "复合"}], "register": "中性", "sense_fingerprint": "局部：整体中的一部分，与整体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局部", "is_correct": true, "explanation": "正确：局部指整体中的一部分，可以说“房子的局部”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：照片只能记录外形，拍不到声音。"}, {"text": "味道", "is_correct": false, "explanation": "语义：照片无法呈现气味，“味道”拍不到。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说人或动物的重量，不能用于房子。"}], "explanations": {"局部": "正确：局部指整体中的一部分，可以说“房子的局部”。", "声音": "语义：照片只能记录外形，拍不到声音。", "味道": "语义：照片无法呈现气味，“味道”拍不到。", "体重": "搭配：“体重”说人或动物的重量，不能用于房子。"}, "sentence_index": 0, "correct_answer": "局部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把局部的钱都捐给了灾区。", "explanation": "这里应该用〈全部〉。局部指整体中的一部分，“都捐出”要表示全部的钱，应用全部。"}, {"text": "他的局部有一米八。", "explanation": "这里应该用〈身高〉。局部指事物的一部分，不能用来说人的身高。"}, {"text": "我们班的局部同学都到齐了。", "explanation": "这里应该用〈全体〉。局部指整体中的一部分，“都到齐”要表示全班同学，应用全体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局部", "is_correct": true, "explanation": "正确：局部指整体中的一部分，可以说“布的局部有点脏”。"}, {"text": "感情", "is_correct": false, "explanation": "语义：布没有感情，不会有“脏”的感情。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”说人的个性，不能用于布。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是人的愿望，布没有梦想。"}], "explanations": {"局部": "正确：局部指整体中的一部分，可以说“布的局部有点脏”。", "感情": "语义：布没有感情，不会有“脏”的感情。", "性格": "搭配：“性格”说人的个性，不能用于布。", "梦想": "语义：梦想是人的愿望，布没有梦想。"}, "sentence_index": 6, "correct_answer": "局部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的局部很聪明。", "explanation": "这里应该用〈头脑〉。局部指事物的一部分，不能用来形容人的智力。"}, {"text": "他的局部都湿透了。", "explanation": "这里应该用〈全身〉。局部指一部分，“都湿透了”要表示整个身体，应用全身。"}, {"text": "我的局部很好。", "explanation": "这里应该用〈心情〉。局部指事物的一部分，不能用来说一个人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画的局部们画得很细。", "corrected_sentence": "这幅画的局部画得很细。", "error_description": "“们”只用于指人的名词，“局部”不能加“们”，应说“这幅画的局部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我只看清了这张地图的局部们。", "corrected_sentence": "我只看清了这张地图的局部。", "error_description": "“们”只用于指人的名词，“局部”不能加“们”，应说“地图的局部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
