INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22906, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示有本事做某事。", "primary_collocate": null, "pronunciation": "néng gòu", "ipa": "nɤŋ˧˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "他每天跑步，所以能够跑很远。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力，你一定能够学好汉语。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很大，能够坐五十个人。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下雨，我们没能够去公园。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望大家都能够按时交作业。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，现在还不能够走路。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书能够帮你了解中国历史。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能够告诉我去地铁站怎么走吗？", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水能够让身体更健康。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会三种语言，能够当我们的翻译。", "target_word": "能够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不能够", "label": "否定式"}, {"form": "没能够", "label": "否定式"}], "register": "中性", "sense_fingerprint": "表示有能力或条件做某事的情态动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能够", "is_correct": true, "explanation": "「能够」表示有能力跑很远，「所以」引出的结果与前面的跑步相符。"}, {"text": "不能", "is_correct": false, "explanation": "语义：「不能」与「所以」的因果相反，每天跑步的人却跑不远，句意矛盾。"}, {"text": "不会", "is_correct": false, "explanation": "语义：「不会」否定了能力，与「所以」引出的结果相悖。"}, {"text": "不肯", "is_correct": false, "explanation": "语义：「不肯」表示不愿意，与前面「每天跑步」的因果不合。"}], "explanations": {"能够": "「能够」表示有能力跑很远，「所以」引出的结果与前面的跑步相符。", "不能": "语义：「不能」与「所以」的因果相反，每天跑步的人却跑不远，句意矛盾。", "不会": "语义：「不会」否定了能力，与「所以」引出的结果相悖。", "不肯": "语义：「不肯」表示不愿意，与前面「每天跑步」的因果不合。"}, "sentence_index": 0, "correct_answer": "能够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你能够早点睡，明天还要上班。", "explanation": "这里应该用〈应该〉。「能够」只表示能力，不表示劝告，这句要表达的是建议，应用〈应该〉。"}, {"text": "明天可能能够下雨。", "explanation": "这里应该用〈会〉。「能够」表示有能力或条件，不表示可能性的推测，下雨应说〈会下雨〉。"}, {"text": "这件事能够不做。", "explanation": "这里应该用〈可以〉。「能够」表示能力，不表示允许或选择，这里应用〈可以〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能够", "is_correct": true, "explanation": "「能够」表示这本书有能力帮你了解中国历史，符合句意。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：「愿意」要求有意愿的主语，「这本书」是物品，不能愿意帮忙。"}, {"text": "敢", "is_correct": false, "explanation": "配价：「敢」要求有胆量的施事，「这本书」无法敢于做事。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：「乐意」表示乐于去做，物品不能乐意帮忙。"}], "explanations": {"能够": "「能够」表示这本书有能力帮你了解中国历史，符合句意。", "愿意": "语义：「愿意」要求有意愿的主语，「这本书」是物品，不能愿意帮忙。", "敢": "配价：「敢」要求有胆量的施事，「这本书」无法敢于做事。", "乐意": "语义：「乐意」表示乐于去做，物品不能乐意帮忙。"}, "sentence_index": 6, "correct_answer": "能够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看样子，今天晚上能够下雪。", "explanation": "这里应该用〈会〉。「能够」表示能力或条件，不用于对天气的推测，应说〈会下雪〉。"}, {"text": "上课的时候不能够吃东西，这是学校的规定。", "explanation": "这里应该用〈可以〉。表示规定上不允许，一般说〈不可以〉，「能够」侧重能力。"}, {"text": "他明天大概能够迟到。", "explanation": "这里应该用〈会〉。「能够」表示能力，迟到不是能力，推测要用〈会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天练习，所以能够的说流利的汉语。", "corrected_sentence": "他每天练习，所以能够说流利的汉语。", "error_description": "错误：「能够」后面不能直接加「的」，「的」应去掉。正确：「能够说流利的汉语」，表示有能力说流利的汉语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把伞能够能挡住大部分雨。", "corrected_sentence": "这把伞能够挡住大部分雨。", "error_description": "错误：「能够」与「能」是两个情态动词，不能叠用，应去掉多余的「能」。正确：「能够挡住大部分雨」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
