INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变凉了。", "primary_collocate": null, "pronunciation": "lěng què", "ipa": "ləŋ˨˩ t͡ɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "汤冷却了，不太好喝。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭菜冷却以后，味道不好。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热水冷却得很慢。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "咖啡放了很久，已经冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁块从炉子里拿出来，慢慢冷却。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等牛奶冷却以后，再给宝宝喝。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，沙地很快就冷却下来。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山停止喷发后，岩浆慢慢冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热茶放在桌上，一会儿就冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷却着的铁块不能马上摸。", "target_word": "冷却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷却了", "label": "体标"}, {"form": "冷却着", "label": "体标"}, {"form": "冷却下来", "label": "复合"}, {"form": "冷卻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "冷却：（不及物）热的东西自己变凉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。汤变凉了，与“不太好喝”的语境一致。"}, {"text": "研究", "is_correct": false, "explanation": "语义：汤不能被研究，“汤研究了，不太好喝”与句意冲突。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指移动物体，与汤的温度变化无关，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：汤不能被翻译，“汤翻译了”说不通。"}], "explanations": {"冷却": "正确。汤变凉了，与“不太好喝”的语境一致。", "研究": "语义：汤不能被研究，“汤研究了，不太好喝”与句意冲突。", "搬运": "语义：搬运指移动物体，与汤的温度变化无关，句意不通。", "翻译": "语义：汤不能被翻译，“汤翻译了”说不通。"}, "sentence_index": 0, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的名字慢慢冷却了。", "explanation": "这里应该用〈淡出〉。“冷却”指温度下降；名字逐渐被人遗忘应说“淡出”。"}, {"text": "这首歌的音量慢慢冷却了。", "explanation": "这里应该用〈减小〉。“冷却”指温度下降；音量的降低应说“减小”。"}, {"text": "这个学生的成绩慢慢冷却了。", "explanation": "这里应该用〈下降〉。“冷却”指温度下降，成绩的下降要用“下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。天黑后沙地温度下降，与“天黑以后”的语境一致。"}, {"text": "发光", "is_correct": false, "explanation": "语义：沙地在天黑后不会发光，与“冷”的语境冲突。"}, {"text": "生长", "is_correct": false, "explanation": "语义：沙地不会生长，与句意不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：沙地不能游泳，“沙地游泳下来”说不通。"}], "explanations": {"冷却": "正确。天黑后沙地温度下降，与“天黑以后”的语境一致。", "发光": "语义：沙地在天黑后不会发光，与“冷”的语境冲突。", "生长": "语义：沙地不会生长，与句意不符。", "游泳": "语义：沙地不能游泳，“沙地游泳下来”说不通。"}, "sentence_index": 6, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的工资冷却了。", "explanation": "这里应该用〈减少〉。“冷却”指温度下降；工资的减少应说“减少”，不能说“冷却”。"}, {"text": "他的字迹慢慢冷却了。", "explanation": "这里应该用〈模糊〉。“冷却”指温度下降；字迹变淡应说“模糊”。"}, {"text": "疼痛冷却了。", "explanation": "这里应该用〈消退〉。“冷却”指温度下降，疼痛减轻要用“消退”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤已经冷却了着。", "corrected_sentence": "汤已经冷却了。", "error_description": "错误：“冷却了着”。正确：应说“冷却了”，“了”和“着”不能同时用在同一个动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "粥煮好后放在桌上，慢慢冷却下了。", "corrected_sentence": "粥煮好后放在桌上，慢慢冷却下来了。", "error_description": "错误：“冷却下了”。正确：应说“冷却下来了”。“冷却下来”是固定说法，表示由热变凉、由高降到低；“冷却下”不是通用说法，应使用“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无效", "is_correct": true, "explanation": "「无效」表示没有效果，与「有效」意思相反。"}, {"text": "复杂", "is_correct": false, "explanation": "「复杂」形容事物繁多或难以理解，与「有效」没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "「高兴」表示愉快的心情，与「有效」没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "「干净」形容没有污垢，与「有效」没有反义关系。"}], "correct_answer": "无效", "explanations": {"无效": "「无效」表示没有效果，与「有效」意思相反。", "复杂": "「复杂」形容事物繁多或难以理解，与「有效」没有反义关系。", "高兴": "「高兴」表示愉快的心情，与「有效」没有反义关系。", "干净": "「干净」形容没有污垢，与「有效」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无效", "is_correct": true, "explanation": "「无效」表示没有效果，与「有效」意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "「安静」形容没有声音或不吵闹，与「有效」没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "「聪明」形容人反应快、有智慧，与「有效」没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "「辛苦」表示费力或劳累，与「有效」没有反义关系。"}], "correct_answer": "无效", "explanations": {"无效": "「无效」表示没有效果，与「有效」意思相反。", "安静": "「安静」形容没有声音或不吵闹，与「有效」没有反义关系。", "聪明": "「聪明」形容人反应快、有智慧，与「有效」没有反义关系。", "辛苦": "「辛苦」表示费力或劳累，与「有效」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有效就是做一件事，得到了想要的结果。", "primary_collocate": null, "pronunciation": "yǒu xiào", "ipa": "jou˨˩˦ ɕjau˥˩", "syllable_count": 2, "sentences": [{"text": "这种药对感冒很有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的办法很有效，我们进步得很快。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个复习方法很有效，他的成绩提高了不少。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了很多方法，只有这个有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动是有效的减肥方法。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议开得很有效，大家都满意。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种办法对你的失眠真的有效吗？", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听力练习对学语言特别有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得哪种方法最有效？", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药很有效，他吃了一次就不疼了。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "方法、药物等能得到想要的结果，有作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有效", "is_correct": true, "explanation": "「有效」表示这种药对感冒有作用，符合句意。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」形容人不勤快，不能用来说药对病的作用。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」形容场面喧哗，与药的作用无关。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」说的是高度，不能用来说药的效果。"}], "explanations": {"有效": "「有效」表示这种药对感冒有作用，符合句意。", "懒": "语义：「懒」形容人不勤快，不能用来说药对病的作用。", "热闹": "语义：「热闹」形容场面喧哗，与药的作用无关。", "高": "搭配：「高」说的是高度，不能用来说药的效果。"}, "sentence_index": 0, "correct_answer": "有效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有效，工作又快又好。", "explanation": "这里应该用〈能干〉。「有效」用于方法、药物等，不用于形容人。"}, {"text": "这把椅子很有效。", "explanation": "这里应该用〈舒服〉。「有效」指达到预期结果，不用于形容椅子是否舒适。"}, {"text": "这条裙子很有效。", "explanation": "这里应该用〈好看〉。「有效」用于方法、药物等，不用于形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有效", "is_correct": true, "explanation": "「有效」问的是这种办法治失眠的效果，符合句意。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场面不热闹，不能用来问办法的效果。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」描述味道，与治疗失眠的效果无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」描述体形，不能用于失眠的治疗效果。"}], "explanations": {"有效": "「有效」问的是这种办法治失眠的效果，符合句意。", "冷清": "语义：「冷清」形容场面不热闹，不能用来问办法的效果。", "甜": "语义：「甜」描述味道，与治疗失眠的效果无关。", "胖": "体貌：「胖」描述体形，不能用于失眠的治疗效果。"}, "sentence_index": 6, "correct_answer": "有效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很有效。", "explanation": "这里应该用〈敏锐〉。「有效」不用于形容身体器官。"}, {"text": "这首歌很有效。", "explanation": "这里应该用〈好听〉。「有效」指达到想要的结果，不用于评价歌曲。"}, {"text": "这个城市很有效。", "explanation": "这里应该用〈繁华〉。「有效」不用于形容地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法把感冒有效。", "corrected_sentence": "这个方法对感冒有效。", "error_description": "错误：「有效」后面的对象要用「对」引出，不能用「把」。「把」字句需要动词，「有效」是形容词，不能用于「把」字句。错误形式是「把感冒有效」，正确形式是「对感冒有效」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药对头疼有效很。", "corrected_sentence": "这种药对头疼很有效。", "error_description": "错误：程度副词「很」要放在形容词「有效」前面，不能放在后面。错误形式是「有效很」，正确形式是「很有效」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
