INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思很深，耐人寻味。", "primary_collocate": null, "pronunciation": "shēn cháng", "ipa": "ʂən˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这首诗寓意深长，很多人喜欢读。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的这句话含意深长，我没有看懂。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的含意深长，孩子还不太懂。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的讲话寓意深长，大家听得很认真。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的寓意深长，让人看了又看。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢地说：“你会明白的。”这话含意深长。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的书名很短，但寓意深长。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的话简单，却含意深长。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她留下了一句含意深长的话。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影的名字寓意深长。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容话语、故事、寓意含义深刻耐人寻味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '949a9561-3731-44c1-9701-0782248bfe49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确答案。深长指含意深远、耐人寻味。"}, {"text": "伸张", "is_correct": false, "explanation": "伸张 shēnzhāng：zhāng（zh-，第一声）与 cháng（ch-，第二声）不同，意思是扩大、发扬（如“伸张正义”）。"}, {"text": "深藏", "is_correct": false, "explanation": "深藏 shēncáng：cáng（平舌 c-）与 cháng（翘舌 ch-）不同，意思是藏得很深。"}, {"text": "深沉", "is_correct": false, "explanation": "chén（-en）与 cháng（-ang）韵母不同，意思是深沉（感情、心思不外露）。"}], "explanations": {"深长": "正确答案。深长指含意深远、耐人寻味。", "伸张": "伸张 shēnzhāng：zhāng（zh-，第一声）与 cháng（ch-，第二声）不同，意思是扩大、发扬（如“伸张正义”）。", "深藏": "深藏 shēncáng：cáng（平舌 c-）与 cháng（翘舌 ch-）不同，意思是藏得很深。", "深沉": "chén（-en）与 cháng（-ang）韵母不同，意思是深沉（感情、心思不外露）。"}, "sentence_index": null, "correct_answer": "深长"}, "level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。寓意深长指含义深远、耐人寻味，与“很多人喜欢读”相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”描写人或物的体型，不用来修饰“寓意”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，“寓意”不能清脆。"}, {"text": "瘦长", "is_correct": false, "explanation": "体貌：“瘦长”描写外形，“寓意”是抽象内容，不能瘦长。"}], "explanations": {"深长": "正确。寓意深长指含义深远、耐人寻味，与“很多人喜欢读”相符。", "高大": "搭配：“高大”描写人或物的体型，不用来修饰“寓意”。", "清脆": "搭配：“清脆”形容声音，“寓意”不能清脆。", "瘦长": "体貌：“瘦长”描写外形，“寓意”是抽象内容，不能瘦长。"}, "sentence_index": 0, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的节奏十分深长，观众看得很累。", "explanation": "这里应该用〈缓慢〉。“深长”指含意深远，不用来形容节奏的快慢。"}, {"text": "这道数学题非常深长，我花了很久才弄懂。", "explanation": "这里应该用〈深奥〉。深长指含意深远，不用来形容学问或题目难懂。"}, {"text": "这场地震给当地带来了深长的灾难。", "explanation": "这里应该用〈深重〉。深重指灾难、损失的程度很重，深长不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。句中“但”转折，前半句说书名短，后半句说寓意深长。"}, {"text": "短小", "is_correct": false, "explanation": "搭配：“短小”说篇幅，不说“寓意短小”。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不修饰“寓意”。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描写外形，“寓意”不能瘦小。"}], "explanations": {"深长": "正确。句中“但”转折，前半句说书名短，后半句说寓意深长。", "短小": "搭配：“短小”说篇幅，不说“寓意短小”。", "响亮": "搭配：“响亮”形容声音，不修饰“寓意”。", "瘦小": "体貌：“瘦小”描写外形，“寓意”不能瘦小。"}, "sentence_index": 6, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对家乡的感情十分深长，每年都要回去看看。", "explanation": "这里应该用〈深厚〉。“深长”多修饰含意、寓意，不修饰感情，“感情”应说“深厚”。"}, {"text": "这场大火给工厂带来了深长的损失。", "explanation": "这里应该用〈惨重〉。“损失”的程度应说“惨重”，“深长”不用来修饰损失。"}, {"text": "她对孩子的疼爱非常深长。", "explanation": "这里应该用〈深切〉。“疼爱”的程度应说“深切”，“深长”不用来修饰情感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇散文的寓意深长得，读后让人久久回味。", "corrected_sentence": "这篇散文的寓意深长，读后让人久久回味。", "error_description": "错误形式：“深长得”，“得”后缺少程度补语，句子不完整。正确形式：去掉“得”，写作“寓意深长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封信的字里行间含意得深长，让人回味无穷。", "corrected_sentence": "这封信的字里行间含意深长，让人回味无穷。", "error_description": "错误：“含意得深长”，多加了“得”。正确：“含意深长”。“得”只接在动词后引出补语，“含意”后直接接形容词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9b6232-2baf-4e9c-bd39-ed60992b4111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
