INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脑部是头里面管想事情和感觉的地方。", "primary_collocate": null, "pronunciation": "nǎo bù", "ipa": "nɑʊ̯˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "脑部在头里面。", "target_word": "脑部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑部是管想事情的地方。", "target_word": "脑部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的脑部受过伤，现在好多了。", "target_word": "脑部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头很疼的时候，要去检查脑部。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑部让我们能看，能听，也能想。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗的脑部比人的小很多。", "target_word": "脑部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "戴着头盔可以保护脑部。", "target_word": "脑部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的脑部很健康。", "target_word": "脑部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多睡觉对脑部有好处。", "target_word": "脑部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一张脑部的照片。", "target_word": "脑部", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "脑部手术", "label": "复合"}, {"form": "脑部检查", "label": "复合"}, {"form": "腦部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "脑部：头里面管思考和感觉的地方（日常浅显义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手指", "is_correct": false, "explanation": "语义：手指长在手上，不可能在头里面。"}, {"text": "脑部", "is_correct": true, "explanation": "正确：脑部是头里面管想事情和感觉的地方，与“在头里面”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会在人的头里面。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“头发”长在头上，不说在头里面。"}], "explanations": {"手指": "语义：手指长在手上，不可能在头里面。", "脑部": "正确：脑部是头里面管想事情和感觉的地方，与“在头里面”相合。", "冰箱": "语义：冰箱是家用电器，不会在人的头里面。", "头发": "搭配：“头发”长在头上，不说在头里面。"}, "sentence_index": 0, "correct_answer": "脑部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑部很灵，老师讲一遍就会。", "explanation": "这里应该用〈脑子〉。“脑部”指器官本身，不用来形容人聪明灵活；口语里形容思维灵活要说“脑子”。"}, {"text": "妈妈用脑部炒了一盘菜。", "explanation": "语义：炒菜要用锅和火，脑部不能充当烹饪的工具。"}, {"text": "桌上放着两只脑部。", "explanation": "量词：〈只〉用于动物，或成对器官中的一个（如一只手）；脑部是单一器官，不能说“两只脑部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：戴头盔保护的是头部，书包不属于需要保护的身体部位，句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指身体的外形，头盔不能用来保护身材。"}, {"text": "脑部", "is_correct": true, "explanation": "正确：头盔保护的是头部，脑部是最需要保护的部位，与句意相合。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，头盔不能保护早餐。"}], "explanations": {"书包": "语义：戴头盔保护的是头部，书包不属于需要保护的身体部位，句意不通。", "身材": "体貌：身材指身体的外形，头盔不能用来保护身材。", "脑部": "正确：头盔保护的是头部，脑部是最需要保护的部位，与句意相合。", "早餐": "语义：早餐是食物，头盔不能保护早餐。"}, "sentence_index": 6, "correct_answer": "脑部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脑部很清楚，老师问什么都能答上。", "explanation": "这里应该用〈头脑〉。脑部指头里神经中枢所在的区域，形容人思维清楚，要说“头脑”。"}, {"text": "晚饭他吃了一份脑部。", "explanation": "语义：脑部是人体器官，不是食物名称，这里不能说“吃了一份”。"}, {"text": "他把脑部存进了银行。", "explanation": "语义：银行存放的是钱或贵重物品，脑部不能存进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "头疼的时候，应该去医院检查脑部们。", "corrected_sentence": "头疼的时候，应该去医院检查脑部。", "error_description": "错误形式“脑部们”，正确形式“脑部”。“们”只附在指人的名词或代词后面表示复数，脑部是器官名称，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "睡得太晚向脑部不好。", "corrected_sentence": "睡得太晚对脑部不好。", "error_description": "错误形式“向脑部不好”，正确形式“对脑部不好”。表示影响、作用的对象用介词“对”，“向”表示动作的方向，不能用于此句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
