INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风扇是一种转起来能吹风的机器，让人感觉凉快。", "primary_collocate": null, "pronunciation": "fēng shàn", "ipa": "fɤŋ˥ ʂan˥˩", "syllable_count": 2, "sentences": [{"text": "天气太热，我打开了风扇。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇对着我吹，真凉快。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台风扇有三个速度。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天晚上，我开着风扇睡觉。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把风扇关小一点。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇转起来，屋里不热了。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给客厅买了一台新风扇。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的风扇声音很小。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐在风扇前吃冰淇淋。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇没有电，不转了。", "target_word": "风扇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "电风扇", "label": "复合"}, {"form": "風扇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家里夏天用来吹风乘凉的电器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风扇", "is_correct": true, "explanation": "“风扇”能在天气太热时打开，与句意相符。"}, {"text": "暖气", "is_correct": false, "explanation": "语义：天气太热时打开暖气只会更热，与句中的原因矛盾。"}, {"text": "电暖器", "is_correct": false, "explanation": "语义：电暖器用来取暖，在天气太热时打开与句意矛盾。"}, {"text": "暖手宝", "is_correct": false, "explanation": "搭配：“打开”多用于开关类设备，暖手宝一般说“使用”，且它是取暖用品，与“天气太热”不合。"}], "explanations": {"风扇": "“风扇”能在天气太热时打开，与句意相符。", "暖气": "语义：天气太热时打开暖气只会更热，与句中的原因矛盾。", "电暖器": "语义：电暖器用来取暖，在天气太热时打开与句意矛盾。", "暖手宝": "搭配：“打开”多用于开关类设备，暖手宝一般说“使用”，且它是取暖用品，与“天气太热”不合。"}, "sentence_index": 0, "correct_answer": "风扇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风扇把脏衣服洗得很干净。", "explanation": "这里应该用〈洗衣机〉。风扇只能吹风，不能洗衣服；洗衣服要用洗衣机。"}, {"text": "冬天的风扇让屋子很暖和，大家都很舒服。", "explanation": "这里应该用〈暖气〉。风扇只能吹风，不能让屋子变暖；取暖要用暖气。"}, {"text": "西瓜放进风扇里，能保持凉爽。", "explanation": "这里应该用〈冰箱〉。风扇不能保存食物，保持食物凉爽要放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风扇", "is_correct": true, "explanation": "“风扇”是家用电器，给客厅买一台很自然，与句意相符。"}, {"text": "马桶", "is_correct": false, "explanation": "语义：马桶装在卫生间，不会给客厅买，与句意矛盾。"}, {"text": "浴缸", "is_correct": false, "explanation": "语义：浴缸用于洗澡，装在卫生间，不会给客厅买。"}, {"text": "水龙头", "is_correct": false, "explanation": "搭配：水龙头用量词“个”，说“一台”不搭配，且它装在厨房或卫生间。"}], "explanations": {"风扇": "“风扇”是家用电器，给客厅买一台很自然，与句意相符。", "马桶": "语义：马桶装在卫生间，不会给客厅买，与句意矛盾。", "浴缸": "语义：浴缸用于洗澡，装在卫生间，不会给客厅买。", "水龙头": "搭配：水龙头用量词“个”，说“一台”不搭配，且它装在厨房或卫生间。"}, "sentence_index": 6, "correct_answer": "风扇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "风扇能把地上的灰尘吸进去，很方便。", "explanation": "这里应该用〈吸尘器〉。风扇只能吹风，不能吸尘；吸灰尘要用吸尘器。"}, {"text": "这台风扇能调到二十六度，很舒服。", "explanation": "这里应该用〈空调〉。风扇没有温度设定，调到几度要用空调。"}, {"text": "风扇能把牛奶加热，很快就热好了。", "explanation": "这里应该用〈微波炉〉。风扇只能吹风，不能加热食物；加热食物要用微波炉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风扇吹我得很凉快。", "corrected_sentence": "风扇吹得我很凉快。", "error_description": "补语的“得”应紧跟动词，说“吹得我很凉快”。错误形式“吹我得很凉快”把“得”放错了位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把风扇打了开，屋里凉快了。", "corrected_sentence": "我把风扇打开了，屋里凉快了。", "error_description": "结果补语“开”应紧跟动词，说“打开了”，错误形式“打了开”把“了”插在动词和补语中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
