INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以走的路。", "primary_collocate": null, "pronunciation": "tōng lù", "ipa": "tʰʊŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这座山只有一条通路可以上去。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪盖住了通路，车开不过去。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员需要一条畅通的通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口放满了箱子，连通路都没有了。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人清理了仓库里的通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要把东西堆在通路上。", "target_word": "通路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个村子之间有一条通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水上涨，村民找不到回家的通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上标出了进山的通路。", "target_word": "通路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们沿着这条通路走到了湖边。", "target_word": "通路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "实际可以通行的道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72cbc8a3-f65d-4a49-8ed5-26d393ab6de6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22932, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路（tōng lù）：可以通行的路，此处指实际能走的路。"}, {"text": "同路", "is_correct": false, "explanation": "同路（tóng lù）与通路（tōng lù）第一音节声调不同（第二声），意思是同行、同道。"}, {"text": "中路", "is_correct": false, "explanation": "中路（zhōng lù）与通路（tōng lù）声母不同（zh 与 t），意思是中间的路线。"}, {"text": "东路", "is_correct": false, "explanation": "东路（dōng lù）与通路（tōng lù）声母不同（d 与 t），意思是东边的道路。"}, {"text": "铜炉", "is_correct": false, "explanation": "铜炉（tóng lú）与通路（tōng lù）两个音节的声调都不同，意思是铜制的炉子。"}], "explanations": {"通路": "通路（tōng lù）：可以通行的路，此处指实际能走的路。", "同路": "同路（tóng lù）与通路（tōng lù）第一音节声调不同（第二声），意思是同行、同道。", "中路": "中路（zhōng lù）与通路（tōng lù）声母不同（zh 与 t），意思是中间的路线。", "东路": "东路（dōng lù）与通路（tōng lù）声母不同（d 与 t），意思是东边的道路。", "铜炉": "铜炉（tóng lú）与通路（tōng lù）两个音节的声调都不同，意思是铜制的炉子。"}, "sentence_index": null, "correct_answer": "通路"}, "level_3": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路：可以上山的路，与“只有一条”“上去”搭配，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水道，不能作为可以上去的路线。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链是饰品，不是可以走的路。"}, {"text": "鱼", "is_correct": false, "explanation": "配价：“上去”需要可以攀登的路径作对象，“鱼”不能作为上去的对象。"}], "explanations": {"通路": "通路：可以上山的路，与“只有一条”“上去”搭配，符合句意。", "河流": "语义：河流是水道，不能作为可以上去的路线。", "项链": "语义：项链是饰品，不是可以走的路。", "鱼": "配价：“上去”需要可以攀登的路径作对象，“鱼”不能作为上去的对象。"}, "sentence_index": 0, "correct_answer": "通路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一张通路，进去看展了。", "explanation": "这里应该用〈门票〉。“通路”指可以走的路，不是票；买票进场要说“门票”。"}, {"text": "他刷了这张通路进了大楼。", "explanation": "这里应该用〈门禁卡〉。“通路”指可以走的路，不是卡；刷卡进门要说“门禁卡”。"}, {"text": "妈妈用通路炒了一盘青菜。", "explanation": "这里应该用〈锅〉。通路是可以走的路，不能用来炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通路", "is_correct": true, "explanation": "通路：两村之间可以通行的路，符合句意。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是穿戴物，不能连接两个村子。"}, {"text": "毛毯", "is_correct": false, "explanation": "语义：毛毯是床上用品，与两村之间的连接无关。"}, {"text": "手帕", "is_correct": false, "explanation": "搭配：“之间”表示两地间的连接，“手帕”不能作为两村之间的连通路线。"}], "explanations": {"通路": "通路：两村之间可以通行的路，符合句意。", "围巾": "语义：围巾是穿戴物，不能连接两个村子。", "毛毯": "语义：毛毯是床上用品，与两村之间的连接无关。", "手帕": "搭配：“之间”表示两地间的连接，“手帕”不能作为两村之间的连通路线。"}, "sentence_index": 6, "correct_answer": "通路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们乘通路到了十楼。", "explanation": "这里应该用〈电梯〉。乘坐升降设备上楼要说电梯，通路是可以走的路。"}, {"text": "他翻开通路，认真读了起来。", "explanation": "这里应该用〈书〉。通路是可以走的路，翻开的应是书本。"}, {"text": "他穿上通路，出门去了。", "explanation": "这里应该用〈衣服〉。通路不能穿，穿上的应是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山脚下有一只通往村子的通路。", "corrected_sentence": "山脚下有一条通往村子的通路。", "error_description": "量词错误：“通路”是条状的路，应说“一条”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震后，这些通路们都堵住了，村民只能绕远路。", "corrected_sentence": "地震后，这些通路都堵住了，村民只能绕远路。", "error_description": "词缀错误：“们”只用于指人或有生命的事物，不能加在“通路”后，应说“这些通路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
