INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事物或状态保持原样，不改变。", "primary_collocate": null, "pronunciation": "wéi chí", "ipa": "weɪ˧˥ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他每天跑步，想维持现在的体重。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店靠老客人才能维持下去。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要维持教室里的安静。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里要用火炉维持温度。", "target_word": "维持", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个国家多年来一直维持着和平。", "target_word": "维持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资只够维持一家人的生活。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察到了路口，帮忙维持交通秩序。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班的成绩一直维持在第一名。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的朋友关系维持了十年。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病以后，只能靠药物维持生命。", "target_word": "维持", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "维持了", "label": "体标"}, {"form": "维持着", "label": "体标"}, {"form": "维持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "让事物或状态保持原样不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维持", "is_correct": true, "explanation": "正确：“维持”表示使现状不变，与“想……现在的体重”相符。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多用于纪录、习惯、僵局，不能和“体重”搭配。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，不能用来表示让体重保持现状。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”是把东西洗干净，与“体重”无关，整句不通。"}], "explanations": {"维持": "正确：“维持”表示使现状不变，与“想……现在的体重”相符。", "打破": "搭配：“打破”多用于纪录、习惯、僵局，不能和“体重”搭配。", "赞美": "语义：“赞美”是称赞，不能用来表示让体重保持现状。", "清洗": "语义：“清洗”是把东西洗干净，与“体重”无关，整句不通。"}, "sentence_index": 0, "correct_answer": "维持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要维持国家的合法权益。", "explanation": "这里应该用〈维护〉。权益需要保护，维护用于权益、利益；维持指使现状不变，不用于保护权益。"}, {"text": "他把这些照片维持在硬盘里。", "explanation": "这里应该用〈保存〉。保存指把东西存放起来，维持指使事物保持原样，不表示存放在某处。"}, {"text": "士兵维持祖国。", "explanation": "这里应该用〈保卫〉。维持用于状态、秩序，保卫国家才说〈保卫〉，不能说“维持祖国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维持", "is_correct": true, "explanation": "正确：“维持”表示保持秩序不乱，与“帮忙……交通秩序”相符。"}, {"text": "打乱", "is_correct": false, "explanation": "语义：“打乱”是使混乱，与“帮忙”的意思相反。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“帮忙”矛盾，整句意思变成在添乱。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再坚持，与“帮忙……秩序”的意思相反，句意不通。"}], "explanations": {"维持": "正确：“维持”表示保持秩序不乱，与“帮忙……交通秩序”相符。", "打乱": "语义：“打乱”是使混乱，与“帮忙”的意思相反。", "破坏": "语义：“破坏”与“帮忙”矛盾，整句意思变成在添乱。", "放弃": "语义：“放弃”是不再坚持，与“帮忙……秩序”的意思相反，句意不通。"}, "sentence_index": 6, "correct_answer": "维持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司维持了他的损失。", "explanation": "这里应该用〈赔偿〉。赔偿指补偿对方的损失，维持指使状态不变，不能用来表示补偿损失。"}, {"text": "他每天维持年迈的母亲。", "explanation": "这里应该用〈照料〉。照料指照顾生活起居，维持指使状态不变，不能用来指照顾人。"}, {"text": "志愿者维持流浪的小猫。", "explanation": "这里应该用〈救助〉。救助指帮助陷入困境的生命，维持不能表示对小猫的帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把体重维持很好。", "corrected_sentence": "他把体重维持得很好。", "error_description": "补语标记错误：“维持”后面带程度补语时要用“得”，应说“维持得很好”，不能漏掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要政府支持，这个项目就能维持起去。", "corrected_sentence": "只要政府支持，这个项目就能维持下去。", "error_description": "补语错误：“维持”后面的趋向补语应为“下去”，“起去”不是正确搭配，应说“维持下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
