INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孤束核是脑干里帮助尝味道和吞咽的部分。", "primary_collocate": null, "pronunciation": "gū shù hé", "ipa": "ku⁵⁵ ʂu⁵¹ xɤ³⁵", "syllable_count": 3, "sentences": [{"text": "孤束核是脑干里帮助尝味道的部分。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃东西时，孤束核会收到舌头的信号。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核也帮助我们吞咽食物。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在图上指出了孤束核的位置。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核很小，在脑子的下面。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤束核受伤后，病人可能尝不出味道。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们能分辨酸甜，是因为孤束核在工作。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，孤束核和吞咽有关系。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我们看了孤束核的图片。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在研究孤束核怎样帮助人尝味道。", "target_word": "孤束核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "脑干里帮助尝味道和吞咽的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72cbc8a3-f65d-4a49-8ed5-26d393ab6de6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤束核", "is_correct": true, "explanation": "正确：孤束核是脑干里帮助尝味道的部分，句意成立。"}, {"text": "味蕾", "is_correct": false, "explanation": "语义：味蕾长在舌头上，不在脑干里，不能是脑干里帮助尝味道的部分。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感受，不是脑干里的部分，句中“帮助尝味道”的主体不能是它。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”口语化，与这句说明文字的语体不协调。"}], "explanations": {"孤束核": "正确：孤束核是脑干里帮助尝味道的部分，句意成立。", "味蕾": "语义：味蕾长在舌头上，不在脑干里，不能是脑干里帮助尝味道的部分。", "味道": "语义：味道是感受，不是脑干里的部分，句中“帮助尝味道”的主体不能是它。", "家伙": "语域：“家伙”口语化，与这句说明文字的语体不协调。"}, "sentence_index": 0, "correct_answer": "孤束核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把孤束核放进书包，带去了学校。", "explanation": "这里应该用〈课本〉。孤束核在脑干里，不能放进书包。"}, {"text": "她拿起孤束核梳头发。", "explanation": "这里应该用〈梳子〉。孤束核是脑干里的部分，不能用来梳头。"}, {"text": "孤束核在肚子里消化食物。", "explanation": "这里应该用〈胃〉。孤束核在脑干里，不消化食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孤束核", "is_correct": true, "explanation": "正确：孤束核负责味觉信号的处理，是分辨酸甜时在工作的结构。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与分辨酸甜的味觉无关，不能是“在工作”的部分。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指与分辨味道无关，不能负责味觉的分辨。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语化，与这句平实的说明语体不协调。"}], "explanations": {"孤束核": "正确：孤束核负责味觉信号的处理，是分辨酸甜时在工作的结构。", "颜色": "语义：颜色与分辨酸甜的味觉无关，不能是“在工作”的部分。", "手指": "语义：手指与分辨味道无关，不能负责味觉的分辨。", "玩意儿": "语域：“玩意儿”口语化，与这句平实的说明语体不协调。"}, "sentence_index": 6, "correct_answer": "孤束核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孤束核长在舌头上，能直接碰到食物。", "explanation": "这里应该用〈味蕾〉。孤束核在脑干里，不长在舌头上。"}, {"text": "他用孤束核看清了远处的字。", "explanation": "这里应该用〈眼睛〉。孤束核和尝味道、吞咽有关，不管看东西。"}, {"text": "孤束核帮助我们听见音乐。", "explanation": "这里应该用〈耳朵〉。孤束核和尝味道、吞咽有关，不管听声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孤束核们能帮助我们尝出味道。", "corrected_sentence": "孤束核能帮助我们尝出味道。", "error_description": "“们”只用于指人或拟人的群体，孤束核是大脑里的结构，不能加“们”。错误在“孤束核们”，正确为“孤束核”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只孤束核位于脑干深处，很小。", "corrected_sentence": "这个孤束核位于脑干深处，很小。", "error_description": "量词错误：“孤束核”是脑内结构，不能用“只”（多用于动物）计量，应说“这个孤束核”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
