INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像小豆子一样的一堆细胞。", "primary_collocate": null, "pronunciation": "hé tuán", "ipa": "xɤ˧˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "核团像一小堆豆子。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "身体里有很多核团。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "核团是一堆小小的细胞。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑袋里有核团，也有神经。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用机器看到了这个核团。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个核团在脑袋的深处。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书上画着一个红色的核团。", "target_word": "核团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个核团的大小都不一样。", "target_word": "核团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说核团很小，眼睛看不见。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个核团看起来像一颗豆子。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "核團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里像小豆子的一堆细胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72cbc8a3-f65d-4a49-8ed5-26d393ab6de6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确答案：核团 hé tuán，指身体里像小豆子一样的一堆细胞。"}, {"text": "和谈", "is_correct": false, "explanation": "tán（第二声）与 tuán（第二声）只差韵母中的 u，意思是和谈。"}, {"text": "河豚", "is_correct": false, "explanation": "tún（第二声）与 tuán（第二声）只差韵母中的 a，意思是河豚，一种鱼。"}, {"text": "河源", "is_correct": false, "explanation": "yuán（第二声）与 tuán（第二声）声母不同，意思是河流的源头。"}], "explanations": {"核团": "正确答案：核团 hé tuán，指身体里像小豆子一样的一堆细胞。", "和谈": "tán（第二声）与 tuán（第二声）只差韵母中的 u，意思是和谈。", "河豚": "tún（第二声）与 tuán（第二声）只差韵母中的 a，意思是河豚，一种鱼。", "河源": "yuán（第二声）与 tuán（第二声）声母不同，意思是河流的源头。"}, "sentence_index": null, "correct_answer": "核团"}, "level_3": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确：核团是一小堆细胞，与“像一小堆豆子”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是大型建筑，不可能像一小堆豆子。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有形状，不能像一小堆豆子那样有可见的形态。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，与一小堆豆子的小而圆的形态不符。"}], "explanations": {"核团": "正确：核团是一小堆细胞，与“像一小堆豆子”相符。", "房子": "语义：房子是大型建筑，不可能像一小堆豆子。", "声音": "语义：声音没有形状，不能像一小堆豆子那样有可见的形态。", "汽车": "语义：汽车是交通工具，与一小堆豆子的小而圆的形态不符。"}, "sentence_index": 0, "correct_answer": "核团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脑袋里有一只核团，也有神经。", "explanation": "这里应该用〈个〉。核团是一小堆细胞，量词用“个”；“只”多指动物或成对器官中的一个。"}, {"text": "脑袋里有一条核团，也有神经。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，核团不能用“条”来数。"}, {"text": "脑袋里有一张核团，也有神经。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，核团不能用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确：画中的红色团状物可以是一个核团，句意成立。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期没有颜色，无法被画成红色的东西。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以被画出红色的具体物体。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有形状和颜色，无法被画成一个红色的物体。"}], "explanations": {"核团": "正确：画中的红色团状物可以是一个核团，句意成立。", "星期": "语义：星期没有颜色，无法被画成红色的东西。", "数学": "语义：数学是学科，不是可以被画出红色的具体物体。", "声音": "语义：声音没有形状和颜色，无法被画成一个红色的物体。"}, "sentence_index": 6, "correct_answer": "核团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个核团是我们班的篮球队。", "explanation": "这里的“核团”指由人组成的篮球队，但核团只指身体里像小豆子一样的一堆细胞，不指人群。"}, {"text": "这个核团是老师分给我们的研究小组。", "explanation": "这里的“核团”指一个研究小组，但核团是细胞的聚集，不能用来指人组成的小组。"}, {"text": "这个核团在学校的合唱比赛中得了奖。", "explanation": "这里的“核团”指一支参赛的合唱团，但核团是细胞的聚集，不能用来指人组成的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个核团们圆圆的，很小。", "corrected_sentence": "这个核团圆圆的，很小。", "error_description": "“们”只用于指人或拟人的群体，核团是一小堆细胞，不能加“们”。错误在“核团们”，正确为“这个核团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个核团大不，像一颗豆子。", "corrected_sentence": "这个核团不大，像一颗豆子。", "error_description": "语序错误：形容词的否定应说“不大”，“大不”不能单独成立。错误在“大不”，正确为“不大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff81273-0f77-4e03-b0ab-f06cc87ac961') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆分", "is_correct": true, "explanation": "反义：“拆分”指把合在一起的东西分开，与“整合”把分散的部分合成整体相对。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指留存、收藏，与“整合”的合并、组织没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "无关：“出发”指动身前往，与“整合”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意走走，与“整合”没有反义关系。"}], "correct_answer": "拆分", "explanations": {"拆分": "反义：“拆分”指把合在一起的东西分开，与“整合”把分散的部分合成整体相对。", "保存": "无关：“保存”指留存、收藏，与“整合”的合并、组织没有反义关系。", "出发": "无关：“出发”指动身前往，与“整合”没有反义关系。", "散步": "无关：“散步”指随意走走，与“整合”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "反义：“分解”指把整体拆成各个部分，与“整合”把分散的部分合成整体相对。"}, {"text": "参加", "is_correct": false, "explanation": "无关：“参加”指加入某项活动，与“整合”没有反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "无关：“保护”指照看、防止受损，与“整合”没有反义关系。"}, {"text": "停止", "is_correct": false, "explanation": "无关：“停止”指结束正在进行的事，与“整合”没有反义关系。"}], "correct_answer": "分解", "explanations": {"分解": "反义：“分解”指把整体拆成各个部分，与“整合”把分散的部分合成整体相对。", "参加": "无关：“参加”指加入某项活动，与“整合”没有反义关系。", "保护": "无关：“保护”指照看、防止受损，与“整合”没有反义关系。", "停止": "无关：“停止”指结束正在进行的事，与“整合”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分开的东西合在一起。", "primary_collocate": null, "pronunciation": "zhěng hé", "ipa": "ʈʂɤŋ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "公司想把两个小部门整合成一个大部门。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们整合了所有人的意见。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要整合各种资料，写一份报告。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两份报告可以整合成一份完整的材料。", "target_word": "整合", "complexity_tier": "T3", "furigana": "zhěnghé", "sentence_source": "generated"}, {"text": "这两家小店整合以后，生意好多了。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议想把各部门的计划整合在一起。", "target_word": "整合", "complexity_tier": "T3", "furigana": "zhěnghé", "sentence_source": "generated"}, {"text": "工人们整合了几个小仓库，地方大了。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把两个相册里的照片整合到一起。", "target_word": "整合", "complexity_tier": "T3", "furigana": "zhěnghé", "sentence_source": "generated"}, {"text": "学校整合了三个班的老师和教室。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先整合资料，再做最后的计划。", "target_word": "整合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整合了", "label": "完成体"}, {"form": "整合过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把分散的东西合成一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分开", "is_correct": false, "explanation": "语义：“分开”与后面的“成一个大部门”方向相反，句子说的是合并。"}, {"text": "整合", "is_correct": true, "explanation": "正确：“整合”指把两个小部门合成一个大部门，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”不能带“把…成…”的结果补语，部门也不能被讨论成一个部门。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说“增加成一个大部门”来表示合并。"}], "explanations": {"分开": "语义：“分开”与后面的“成一个大部门”方向相反，句子说的是合并。", "整合": "正确：“整合”指把两个小部门合成一个大部门，符合句意。", "讨论": "配价：“讨论”不能带“把…成…”的结果补语，部门也不能被讨论成一个部门。", "增加": "搭配：“增加”说的是数量，不能说“增加成一个大部门”来表示合并。"}, "sentence_index": 0, "correct_answer": "整合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种颜色整合成了一种新的颜色。", "explanation": "这里应该用〈融合〉。融合指颜色、文化等互相渗透成一体，整合强调把分散的部分组织成一个系统，不用于颜色。"}, {"text": "这种饮料是把果汁和牛奶整合起来做成的。", "explanation": "这里应该用〈混合〉。混合指把果汁、牛奶等搅在一起，整合强调把各个部分组织成整体，不用于液体的搅拌。"}, {"text": "我们用一根电线把两个灯泡整合起来。", "explanation": "这里应该用〈连接〉。连接指用线、管等把具体的物体接在一起，整合不用于器物之间的接驳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装满", "is_correct": false, "explanation": "语义：“装满”表示放满东西，地方会变得不够，与“地方大了”矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看某个地方，不能让仓库本身变得空间更大，句子说不通。"}, {"text": "整合", "is_correct": true, "explanation": "正确：工人们把几个小仓库合在一起，地方就大了，句意吻合。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”只用于动物，不能和“仓库”搭配。"}], "explanations": {"装满": "语义：“装满”表示放满东西，地方会变得不够，与“地方大了”矛盾。", "参观": "语义：“参观”是去看某个地方，不能让仓库本身变得空间更大，句子说不通。", "整合": "正确：工人们把几个小仓库合在一起，地方就大了，句意吻合。", "饲养": "搭配：“饲养”只用于动物，不能和“仓库”搭配。"}, "sentence_index": 6, "correct_answer": "整合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板把任务整合给每个人。", "explanation": "这里应该用〈分配〉。分配指按份额派给各人，整合指把分散的部分合成一个整体，不表示派发。"}, {"text": "他把这篇文章整合成了英文。", "explanation": "这里应该用〈翻译〉。翻译指把一种语言转换成另一种语言，整合指把分散的部分合成整体，两者无关。"}, {"text": "妈妈用彩纸整合了房间。", "explanation": "这里应该用〈装饰〉。装饰指给房间加上美化的东西，整合不表示美化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动把各校的资源整合很好。", "corrected_sentence": "这次活动把各校的资源整合得很好。", "error_description": "“整合”后面作状态补语的“很好”前漏了结构助词“得”，应说“整合得很好”；“整合很好”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把两个小仓库整合一个大仓库。", "corrected_sentence": "他们把两个小仓库整合成一个大仓库。", "error_description": "“整合”后漏了结果补语“成”，应说“整合成一个大仓库”，表示合并后变成的结果；“整合一个大仓库”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
