INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种机器，能算数、存东西、玩游戏。", "primary_collocate": null, "pronunciation": "jì suàn jī", "ipa": "tɕi˥˩ swan˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "计算机能帮我们算数。", "target_word": "计算机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥每天晚上用计算机玩游戏。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的计算机里存着很多照片。", "target_word": "计算机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台计算机太旧了，开机要很久。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把计算机打开。", "target_word": "计算机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一台新计算机。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计算机坏了，我不能写作业了。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹的计算机放在书桌上。", "target_word": "计算机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题太难，我用计算机算出了答案。", "target_word": "计算机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉前请关掉计算机。", "target_word": "计算机", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台计算机", "label": "量词"}, {"form": "計算機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "计算机|能算数、存东西、玩游戏的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c91e02e-2f48-4be3-84f2-455e61d61713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能帮人算数，与“能帮我们算数”的语境不符。"}, {"text": "计算机", "is_correct": true, "explanation": "正确：计算机能算数，与句子描述的功能相合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能算数，“小猫能帮我们算数”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体型特征，不能帮人算数。"}], "explanations": {"冰箱": "语义：冰箱不能帮人算数，与“能帮我们算数”的语境不符。", "计算机": "正确：计算机能算数，与句子描述的功能相合。", "小猫": "语义：小猫不能算数，“小猫能帮我们算数”说不通。", "身高": "体貌：“身高”是人的体型特征，不能帮人算数。"}, "sentence_index": 0, "correct_answer": "计算机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只计算机太旧了，开机要很久。", "explanation": "这里应该用〈台〉。计算机是器械，量词用“台”；“只”多用于动物。"}, {"text": "这块计算机太旧了，开机要很久。", "explanation": "这里应该用〈台〉。“块”用于块状的东西，计算机是器械，应用“台”。"}, {"text": "这根计算机太旧了，开机要很久。", "explanation": "这里应该用〈台〉。“根”用于细长的东西，计算机不属于这类，应用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是写作业要用的设备，“音乐坏了，我不能写作业了”说不通。"}, {"text": "计算机", "is_correct": true, "explanation": "正确：计算机坏了，就不能用来写作业，前后语义相连。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”不会“坏了”，不能与“坏了”搭配。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说不是写作业要用的设备，“小说坏了”说不通。"}], "explanations": {"音乐": "语义：音乐不是写作业要用的设备，“音乐坏了，我不能写作业了”说不通。", "计算机": "正确：计算机坏了，就不能用来写作业，前后语义相连。", "石头": "搭配：“石头”不会“坏了”，不能与“坏了”搭配。", "小说": "语义：小说不是写作业要用的设备，“小说坏了”说不通。"}, "sentence_index": 6, "correct_answer": "计算机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "计算机只能算数，不能玩游戏。", "explanation": "这里应该用〈计算器〉。只能算数、不能玩游戏是计算器的范围；计算机还能存东西、玩游戏。"}, {"text": "计算机靠拨动算珠来算账。", "explanation": "这里应该用〈算盘〉。靠拨动算珠来算账是算盘的工作方式；计算机是电子设备，没有算珠。"}, {"text": "计算机能玩游戏，但不能算数。", "explanation": "这里应该用〈游戏机〉。玩游戏是游戏机的功能，游戏机不负责算数；计算机能算数，这句与它的定义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家买了两只计算机。", "corrected_sentence": "我家买了两台计算机。", "error_description": "错误形式“两只计算机”，正确形式“两台计算机”。计算机是器械，量词用“台”，“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "麻烦计算机打开一下。", "corrected_sentence": "麻烦把计算机打开一下。", "error_description": "错误形式“麻烦计算机打开一下”，正确形式“麻烦把计算机打开一下”。这里要用“把”字句提前宾语“计算机”，在动词“打开”前加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9680528-bca4-46f9-8fb4-3fc5b530a07e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
