INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大脑里有一条像带子的地方。", "primary_collocate": null, "pronunciation": "kòu dài huí", "ipa": "kʰou˥˩ tai˥˩ xuei˧˥", "syllable_count": 3, "sentences": [{"text": "扣带回像一条带子，在大脑里面。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上这条弯弯的带子就是扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着大脑图，说这里是扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回在大脑中间，形状像带子。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能在大脑模型里找到扣带回吗？", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回是大脑里的一个小地方。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了大脑中间那条像带子的结构，叫扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回很长，绕着大脑中间走。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学习大脑里的扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑里这个地方叫扣带回，像一条带子。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前扣带回", "label": "复合"}, {"form": "扣帶回", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大脑里形状像带子的一个部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1e58b4-b32d-462a-a4f9-a33161b902c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：扣带回位于大脑里面，形状像带子，与句中描述一致。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓位于脊柱内，不在大脑里面，与“在大脑里面”矛盾。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不在大脑里，也不是带状结构，与句中两个条件都不符。"}, {"text": "肺", "is_correct": false, "explanation": "语义：肺在胸腔里，不在大脑里面，也不像带子，与句中描述不符。"}], "explanations": {"扣带回": "正确：扣带回位于大脑里面，形状像带子，与句中描述一致。", "脊髓": "语义：脊髓位于脊柱内，不在大脑里面，与“在大脑里面”矛盾。", "心脏": "语义：心脏不在大脑里，也不是带状结构，与句中两个条件都不符。", "肺": "语义：肺在胸腔里，不在大脑里面，也不像带子，与句中描述不符。"}, "sentence_index": 0, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生切开了一本扣带回，看它的形状。", "explanation": "这里量词用错。“本”用于书籍，扣带回是大脑里的脑区，应数“个”。"}, {"text": "医生切开了一颗扣带回，看它的形状。", "explanation": "这里量词用错。“颗”用于小而圆的东西，扣带回是带状的脑区，应数“个”。"}, {"text": "医生切开了一把扣带回，看它的形状。", "explanation": "这里量词用错。“把”用于有柄或可握的物件，扣带回是脑区，应数“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：题干描述的是大脑中间、形状像带子的结构，正是扣带回。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃在腹部，不在大脑中间，与题干的位置描述矛盾。"}, {"text": "神经元", "is_correct": false, "explanation": "语义：神经元是单个细胞，不是像带子的结构，与“形状像带子”矛盾。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不在大脑中间，也不是带状结构，与题干描述矛盾。"}], "explanations": {"扣带回": "正确：题干描述的是大脑中间、形状像带子的结构，正是扣带回。", "胃": "语义：胃在腹部，不在大脑中间，与题干的位置描述矛盾。", "神经元": "语义：神经元是单个细胞，不是像带子的结构，与“形状像带子”矛盾。", "眼睛": "语义：眼睛不在大脑中间，也不是带状结构，与题干描述矛盾。"}, "sentence_index": 6, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在模型上指出了一把扣带回的位置。", "explanation": "这里量词用错。“把”用于有柄或可握的物件，扣带回是脑区，应数“个”。"}, {"text": "老师在模型上指出了一粒扣带回的位置。", "explanation": "这里量词用错。“粒”用于很小的颗粒，扣带回是较大的脑区，应数“个”。"}, {"text": "他系紧了腰上的扣带回。", "explanation": "这里应该用〈皮带〉。扣带回指大脑里像带子的脑区，不是系在腰上的带子，系腰带应说皮带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在实验室里看见了一本扣带回。", "corrected_sentence": "我们在实验室里看见了一个扣带回。", "error_description": "量词错误：应为“一个扣带回”。“本”用于书籍，不用于脑区，扣带回应数“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在纸上画出了一片扣带回的样子。", "corrected_sentence": "他在纸上画出了一个扣带回的样子。", "error_description": "量词错误：应为“一个扣带回”。“片”用于平而薄的东西，扣带回是脑区，应数“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
