INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大脑最外面的一层。", "primary_collocate": null, "pronunciation": "pí céng", "ipa": "pʰi˧˥ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "皮层是大脑最外面的一层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑外面包着的那部分叫皮层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师拆开模型，我们看到了皮层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑的皮层是灰色的，里面是白色的。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑最外面的皮层上有很多弯弯的线。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你摸一下大脑模型，外面那层就是皮层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑的皮层很薄，但是很重要。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用大脑思考，主要靠大脑的皮层。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片中大脑最外面的皮层是粉色的。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮层在大脑的外面，不在里面。", "target_word": "皮层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大脑皮层", "label": "复合"}, {"form": "皮層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大脑最外面的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1e58b4-b32d-462a-a4f9-a33161b902c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮层", "is_correct": true, "explanation": "正确：皮层是大脑最外面的一层，与句中的定义一致。"}, {"text": "海马", "is_correct": false, "explanation": "语义：海马位于大脑深部，不在最外面，与“最外面的一层”矛盾。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓位于脊柱内，不在大脑里，与句中的位置不符。"}, {"text": "白质", "is_correct": false, "explanation": "语义：白质在大脑内部，不在最外面，与“最外面的一层”矛盾。"}], "explanations": {"皮层": "正确：皮层是大脑最外面的一层，与句中的定义一致。", "海马": "语义：海马位于大脑深部，不在最外面，与“最外面的一层”矛盾。", "脊髓": "语义：脊髓位于脊柱内，不在大脑里，与句中的位置不符。", "白质": "语义：白质在大脑内部，不在最外面，与“最外面的一层”矛盾。"}, "sentence_index": 0, "correct_answer": "皮层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "土壤的皮层很肥沃。", "explanation": "〈表层〉。皮层指大脑等器官表面的灰质层，土壤的表面应说“表层”。"}, {"text": "医生打开了一只皮层，检查里面。", "explanation": "这里量词用错。“只”多用于动物或成对的器官，皮层是一层灰质，应数“层”。"}, {"text": "鸡蛋的皮层很薄。", "explanation": "〈外壳〉。鸡蛋外面的硬壳叫蛋壳，皮层只指器官内的灰质层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮层", "is_correct": true, "explanation": "正确：“大脑的皮层很薄，但是很重要”指大脑最外面的灰质层，这里应填“皮层”。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：“大脑的心脏”不成立，心脏不属于大脑。"}, {"text": "肝脏", "is_correct": false, "explanation": "语义：“大脑的肝脏”不成立，肝脏不属于大脑。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓位于脊柱内，不属于大脑，与“大脑……很薄”的描述不符。"}], "explanations": {"皮层": "正确：“大脑的皮层很薄，但是很重要”指大脑最外面的灰质层，这里应填“皮层”。", "心脏": "语义：“大脑的心脏”不成立，心脏不属于大脑。", "肝脏": "语义：“大脑的肝脏”不成立，肝脏不属于大脑。", "脊髓": "语义：脊髓位于脊柱内，不属于大脑，与“大脑……很薄”的描述不符。"}, "sentence_index": 6, "correct_answer": "皮层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球的皮层很厚。", "explanation": "〈地壳〉。地球表面的岩石层叫地壳，皮层只用于大脑等器官。"}, {"text": "他的皮层被晒伤了。", "explanation": "〈表皮〉。人身上被晒伤的是皮肤的表皮，皮层只指大脑等器官的灰质层。"}, {"text": "这台电脑的皮层很光滑。", "explanation": "〈外壳〉。电脑表面那层硬壳叫外壳，皮层只指大脑等器官的灰质层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个模型的外面有一颗皮层。", "corrected_sentence": "这个模型的外面有一层皮层。", "error_description": "量词错误：应为“一层皮层”。皮层是一层灰质，应数“层”，“颗”不能用于此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大脑外面包着一颗皮层。", "corrected_sentence": "大脑外面包着一层皮层。", "error_description": "量词错误：应为“一层皮层”。皮层是一层灰质，应数“层”，“颗”用于小而圆的东西，不能用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
