INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己决定自己的事情。", "primary_collocate": null, "pronunciation": "zì zhǔ", "ipa": "tsɿ˥˩ tʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子长大了，要让他自主选择学校。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了我们自主安排时间的权利。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你自主决定就行，不用问我。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生能自主学习，不要总靠别人。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年人应该自主做决定。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想自主创业，不想给别人打工。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自主选择工作的权利。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的时间由你自主安排。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的价格由老板自主决定。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校让学生自主管理班级。", "target_word": "自主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自主", "label": "原形"}, {"form": "自主权", "label": "复合"}, {"form": "自主性", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己决定自己的事，不受别人控制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22964, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自主", "is_correct": true, "explanation": "自主：自己决定自己的事情。这是正确答案。"}, {"text": "自助", "is_correct": false, "explanation": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己服务自己。"}, {"text": "自注", "is_correct": false, "explanation": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己给文章加注释。"}, {"text": "自住", "is_correct": false, "explanation": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己居住。"}], "explanations": {"自主": "自主：自己决定自己的事情。这是正确答案。", "自助": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己服务自己。", "自注": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己给文章加注释。", "自住": "zìzhù（第四声）与 zìzhǔ（第三声）第二个音节声调不同，意思是自己居住。"}, "sentence_index": null, "correct_answer": "自主"}, "level_3": {"options": [{"text": "自主", "is_correct": true, "explanation": "正确：自主指自己做主，符合“让他……选择学校”的语境。"}, {"text": "被动", "is_correct": false, "explanation": "语义：被动指不自己行动、听别人安排，与孩子自己选学校相反。"}, {"text": "擅自", "is_correct": false, "explanation": "语义：擅自指未经允许就行动，与“让他”所表示的许可意思矛盾。"}, {"text": "代劳", "is_correct": false, "explanation": "搭配：代劳指替别人做事，不能用于要孩子自己选择学校的情况。"}], "explanations": {"自主": "正确：自主指自己做主，符合“让他……选择学校”的语境。", "被动": "语义：被动指不自己行动、听别人安排，与孩子自己选学校相反。", "擅自": "语义：擅自指未经允许就行动，与“让他”所表示的许可意思矛盾。", "代劳": "搭配：代劳指替别人做事，不能用于要孩子自己选择学校的情况。"}, "sentence_index": 0, "correct_answer": "自主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在家长的压力下自主离开了学校。", "explanation": "这里表达的是被迫的意思，应该用〈被迫〉。自主指自己做主、出于自愿的选择，与“在压力下”的意思相反。"}, {"text": "我的手机自主关机了。", "explanation": "这里应该用〈自动〉。自主指人经过自己有意作出的决定，手机没有做主的能力，不能用自主。"}, {"text": "我昨天自主摔倒了。", "explanation": "这里表达的是无意发生，应该用〈不小心〉。自主指经过自己有意作出的决定，不能用来修饰无意的摔倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自主", "is_correct": true, "explanation": "正确：自主指自己做主，符合“每个人都有……选择工作的权利”。"}, {"text": "被迫", "is_correct": false, "explanation": "语义：被迫指在外力下不得不做，与“权利”所说的自己选择相反。"}, {"text": "强制", "is_correct": false, "explanation": "语义：强制指用压力迫使别人去做，与“权利”所说的自己选择相反。"}, {"text": "委托", "is_correct": false, "explanation": "配价：委托需要说明委托给谁，这句话里没有这个对象，“委托选择工作”也不通。"}], "explanations": {"自主": "正确：自主指自己做主，符合“每个人都有……选择工作的权利”。", "被迫": "语义：被迫指在外力下不得不做，与“权利”所说的自己选择相反。", "强制": "语义：强制指用压力迫使别人去做，与“权利”所说的自己选择相反。", "委托": "配价：委托需要说明委托给谁，这句话里没有这个对象，“委托选择工作”也不通。"}, "sentence_index": 6, "correct_answer": "自主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很自主，连作业都要让老师替他写。", "explanation": "自主指自己决定、不依赖别人，而后半句说他事事依赖老师替他做，前后矛盾，不能用自主来形容他。"}, {"text": "他很自主地喜欢吃香蕉。", "explanation": "这里误用了〈自发〉的意思。自主指经过自己有意作出的决定，不能修饰“喜欢”这种感受。"}, {"text": "今天的雨下得很自主。", "explanation": "这里的意思是“自然发生、不由人控制”，但自主指人自己决定事情，不能用来描述天气等自然现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经被自主决定去北京了。", "corrected_sentence": "他已经自主决定去北京了。", "error_description": "错误：“被”字句表示被动，而“自主”指自己做主，二者矛盾，“被自主决定”不成立。正确：“他已经自主决定去北京了”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社团自主得管理，效果很好。", "corrected_sentence": "这个社团自主地管理，效果很好。", "error_description": "错误：“自主得管理”，修饰动词的状语要用“地”，不用“得”。正确：“自主地管理”，“自主”作状语修饰“管理”，后面用“地”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
