INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "虫子是小小的动物，比如蚂蚁、蝴蝶。", "primary_collocate": null, "pronunciation": "chóng zi", "ipa": "ʈʂʰʊŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "蚂蚁和蝴蝶都是小虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上看虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了很多有趣的虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩喜欢把虫子放在瓶子里。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙最爱吃会飞的虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，虫子都从泥土里出来了。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪种虫子会发光吗？", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去公园找虫子。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些虫子能帮花传粉。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的猫常常抓虫子玩。", "target_word": "虫子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "蟲子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "虫子：小小的动物，如蚂蚁、蝴蝶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25632224-7924-47df-ae1b-2e2ff713be96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。虫子 chóng zi，指蚂蚁、蝴蝶一类的小动物。"}, {"text": "童子", "is_correct": false, "explanation": "tóng 与 chóng 声母不同（t 与 ch），声调相同，意思是童子，即小孩子。"}, {"text": "笼子", "is_correct": false, "explanation": "lóng 与 chóng 声母不同（l 与 ch），声调相同，意思是笼子。"}, {"text": "筒子", "is_correct": false, "explanation": "tǒng 与 chóng 声母（t 与 ch）和声调都不同，意思是筒子，即圆筒。"}], "explanations": {"虫子": "正确答案。虫子 chóng zi，指蚂蚁、蝴蝶一类的小动物。", "童子": "tóng 与 chóng 声母不同（t 与 ch），声调相同，意思是童子，即小孩子。", "笼子": "lóng 与 chóng 声母不同（l 与 ch），声调相同，意思是笼子。", "筒子": "tǒng 与 chóng 声母（t 与 ch）和声调都不同，意思是筒子，即圆筒。"}, "sentence_index": null, "correct_answer": "虫子"}, "level_3": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。蚂蚁和蝴蝶都属于小虫子，“小虫子”是正确说法。"}, {"text": "石头", "is_correct": false, "explanation": "语义：蚂蚁和蝴蝶不是石头，这句话的意思不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：蚂蚁和蝴蝶不是房子，这句话的意思不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“小汽车”是固定说法，不能用来指蚂蚁和蝴蝶。"}], "explanations": {"虫子": "正确答案。蚂蚁和蝴蝶都属于小虫子，“小虫子”是正确说法。", "石头": "语义：蚂蚁和蝴蝶不是石头，这句话的意思不通。", "房子": "语义：蚂蚁和蝴蝶不是房子，这句话的意思不通。", "汽车": "搭配：“小汽车”是固定说法，不能用来指蚂蚁和蝴蝶。"}, "sentence_index": 0, "correct_answer": "虫子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一只大虫子，见了生人就汪汪叫。", "explanation": "这里应该用〈狗〉。会汪汪叫的是狗，虫子是蚂蚁、蝴蝶一类的小动物。"}, {"text": "他手里拿着一台虫子。", "explanation": "这里应该用〈只〉。“台”用于机器、电器，不用于小虫子。"}, {"text": "桌子上有一座虫子。", "explanation": "这里应该用〈只〉。“座”用于山、房屋等大而固定的东西，不用于虫子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。虫子 chóng zi，指蚂蚁、蝴蝶一类的小动物。"}, {"text": "橙子", "is_correct": false, "explanation": "橙子 chéng zi，指橙子果实，与 chóng 仅韵母不同（eng 与 ong），声调相同。"}, {"text": "瞳子", "is_correct": false, "explanation": "瞳子 tóng zi，指眼睛的瞳孔，与 chóng 仅声母不同（t 与 ch），声调相同。"}, {"text": "种子", "is_correct": false, "explanation": "zhǒng 与 chóng 声母不同（zh 与 ch），声调也不同，意思是植物的种子。"}], "explanations": {"虫子": "正确答案。虫子 chóng zi，指蚂蚁、蝴蝶一类的小动物。", "橙子": "橙子 chéng zi，指橙子果实，与 chóng 仅韵母不同（eng 与 ong），声调相同。", "瞳子": "瞳子 tóng zi，指眼睛的瞳孔，与 chóng 仅声母不同（t 与 ch），声调相同。", "种子": "zhǒng 与 chóng 声母不同（zh 与 ch），声调也不同，意思是植物的种子。"}, "sentence_index": null, "correct_answer": "虫子"}, "level_3": {"options": [{"text": "虫子", "is_correct": true, "explanation": "正确答案。有些虫子会发光，句中问的是哪种虫子会发光。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会发光，这句话的意思不通。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“会发光”的主语一般是萤火虫、灯等，不说饼干会发光。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子不会发光，这句话的意思不通。"}], "explanations": {"虫子": "正确答案。有些虫子会发光，句中问的是哪种虫子会发光。", "面包": "语义：面包不会发光，这句话的意思不通。", "饼干": "搭配：“会发光”的主语一般是萤火虫、灯等，不说饼干会发光。", "句子": "语义：句子不会发光，这句话的意思不通。"}, "sentence_index": 6, "correct_answer": "虫子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鱼缸里有几条虫子在游来游去。", "explanation": "这里应该用〈鱼〉。在鱼缸里游的是鱼，不是虫子。"}, {"text": "草地上有一根虫子在爬。", "explanation": "这里应该用〈只〉。“根”用于细长条状的东西，不用于虫子。"}, {"text": "我家的猫常常抓一块虫子玩。", "explanation": "这里应该用〈只〉。“块”用于块状物，不用于虫子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子的草丛里藏着一根小虫子。", "corrected_sentence": "院子的草丛里藏着一只小虫子。", "error_description": "量词错误：“根”用于细长条状的东西，虫子是小动物，应该说“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
