INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乳制品是用牛奶做的食物。", "primary_collocate": null, "pronunciation": "rǔ zhì pǐn", "ipa": "ʐu˨˩˦ ʈʂɨ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "牛奶是最常见的乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶和奶酪都是用牛奶做的乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早饭我喜欢吃面包和乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都买一些乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乳制品里有很多钙，对骨头好。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰淇淋也是一种乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店卖的乳制品很新鲜。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喝牛奶，也不吃别的乳制品。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热，乳制品很容易坏。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在超市的乳制品区买了酸奶。", "target_word": "乳制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "乳製品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乳制品：用牛奶做的食物，如酸奶、奶酪、冰淇淋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25632224-7924-47df-ae1b-2e2ff713be96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乳制品", "is_correct": true, "explanation": "正确。“牛奶是最常见的乳制品”，“乳制品”指用牛奶做成的食物，所属关系正确。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：牛奶不是蔬菜，与“最常见的蔬菜”的所属类别矛盾。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：牛奶不是粮食，与“最常见的粮食”不能指同一事物。"}, {"text": "肉类", "is_correct": false, "explanation": "语义：牛奶不属于肉类，与“最常见的肉类”不能指同一事物。"}], "explanations": {"乳制品": "正确。“牛奶是最常见的乳制品”，“乳制品”指用牛奶做成的食物，所属关系正确。", "蔬菜": "语义：牛奶不是蔬菜，与“最常见的蔬菜”的所属类别矛盾。", "粮食": "语义：牛奶不是粮食，与“最常见的粮食”不能指同一事物。", "肉类": "语义：牛奶不属于肉类，与“最常见的肉类”不能指同一事物。"}, "sentence_index": 0, "correct_answer": "乳制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天都买一台乳制品。", "explanation": "这里不能用〈台〉。〈台〉用于机器，“乳制品”是食品，应说“一些乳制品”或“一种乳制品”。"}, {"text": "我们超市进了一座乳制品。", "explanation": "这里不能用〈座〉。〈座〉用于山、楼房等大型固定物，“乳制品”是食品，不能用“座”来计量。"}, {"text": "茶叶蛋是一种乳制品。", "explanation": "这里应该用〈蛋制品〉。“蛋制品”以禽蛋为原料，茶叶蛋以鸡蛋为主料，不是乳制品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乳制品", "is_correct": true, "explanation": "正确。乳制品是可以卖的食品，能够“很新鲜”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是商品，商店不能“卖时间”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“新鲜”，与“这个商店卖的”的语境矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是商品，商店不能“卖天气”。"}], "explanations": {"乳制品": "正确。乳制品是可以卖的食品，能够“很新鲜”。", "时间": "语义：时间不是商品，商店不能“卖时间”。", "石头": "语义：石头不会“新鲜”，与“这个商店卖的”的语境矛盾。", "天气": "语义：天气不是商品，商店不能“卖天气”。"}, "sentence_index": 6, "correct_answer": "乳制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了一朵乳制品。", "explanation": "这里不能用〈朵〉。〈朵〉用于花朵，“乳制品”是食品类别，不能用“朵”来计量。"}, {"text": "我们超市进了一辆乳制品。", "explanation": "这里不能用〈辆〉。〈辆〉用于车辆，“乳制品”是食品，不能用“辆”来计量。"}, {"text": "这家超市的乳制品都是用大豆做的。", "explanation": "这里应该用〈豆制品〉。“乳制品”以乳汁为原料，用大豆做的应称“豆制品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们超市卖了三只乳制品。", "corrected_sentence": "我们超市卖了三种乳制品。", "error_description": "量词错误：〈只〉用于动物，“乳制品”是食品类别，应用〈种〉。正确说法是“三种乳制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店里有很多条乳制品。", "corrected_sentence": "这家店里有很多种乳制品。", "error_description": "量词错误：“条”用于细长的东西，“乳制品”是一类食品，应用〈种〉。正确说法是“很多种乳制品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
