INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22980, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情开始是这样，后来变得不一样了。", "primary_collocate": null, "pronunciation": "yuán lái", "ipa": "ɥɛn˧˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "他还住在原来的房子里。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们原来的老师调到别的学校了。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书放回原来的地方。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病好了，又回到原来的工作岗位。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路比原来宽多了。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我原来的手机坏了，所以买了新的。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市和原来不一样了。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们原来的计划改了。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师换了位子，不在原来那一排了。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬家了，原来的办公室现在是仓库。", "target_word": "原来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原来的", "label": "结构助词形式"}, {"form": "原來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "最初的、以前的样子，现在已经改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原来", "is_correct": true, "explanation": "“原来”指最初的、以前的样子，与“房子”搭配，表示仍住在过去的那套房子里。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能修饰“房子”，搭配不当。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的情绪，不能修饰“房子”，搭配不当。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”指人的品性，用来修饰房子语义荒谬，且与“还住在”的语境不符。"}], "explanations": {"原来": "“原来”指最初的、以前的样子，与“房子”搭配，表示仍住在过去的那套房子里。", "聪明": "搭配：“聪明”形容人的智力，不能修饰“房子”，搭配不当。", "高兴": "搭配：“高兴”形容人的情绪，不能修饰“房子”，搭配不当。", "懒惰": "语义：“懒惰”指人的品性，用来修饰房子语义荒谬，且与“还住在”的语境不符。"}, "sentence_index": 0, "correct_answer": "原来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节日原来古代的祭祀。", "explanation": "这里应该用〈源于〉。原来不能作动词表示「来源于」，说节日的来源要用〈源于〉。"}, {"text": "这个词原来于希腊语。", "explanation": "这里应该用〈源于〉。原来不作动词表示“来源于”，说明词语的来源要用〈源于〉。"}, {"text": "他原来了我的错误。", "explanation": "这里应该用〈原谅〉。原来没有“宽恕”的意思，对别人的错误不计较要用〈原谅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原来", "is_correct": true, "explanation": "“原来”指事物先前的样子，此处表示城市从前的样子，与“不一样了”呼应。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：“墙壁”是建筑构件，不能与“城市”作比较对象，句子语义荒谬。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮品，与“城市”不能相比较，句子语义荒谬。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指人的性情，不能用来比较“城市”，搭配不当。"}], "explanations": {"原来": "“原来”指事物先前的样子，此处表示城市从前的样子，与“不一样了”呼应。", "墙壁": "语义：“墙壁”是建筑构件，不能与“城市”作比较对象，句子语义荒谬。", "咖啡": "语义：“咖啡”是饮品，与“城市”不能相比较，句子语义荒谬。", "脾气": "搭配：“脾气”指人的性情，不能用来比较“城市”，搭配不当。"}, "sentence_index": 6, "correct_answer": "原来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失败的原来是他没有努力。", "explanation": "这里应该用〈原因〉。原来不能作名词表示“原因”，说明失败的缘由要用〈原因〉。"}, {"text": "我原来一天去过北京。", "explanation": "这里应该用〈前一天〉。原来表示事情先前的状况，不能用来指相对某个时间的前一天，要说“前一天”。"}, {"text": "长江的原来在青海。", "explanation": "这里应该用〈源头〉。原来不能作名词表示河流的发源处，说长江的发源地要用〈源头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店原来老板已经退休了。", "corrected_sentence": "这家店原来的老板已经退休了。", "error_description": "结构助词错误：“原来”修饰名词时要加“的”，应为“原来的老板”，省去“的”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区原来得树林已经砍掉了。", "corrected_sentence": "这个小区原来的树林已经砍掉了。", "error_description": "结构助词错误：“原来”修饰名词时要用“的”，“得”用于补语，不能用在这里，应为“原来的树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
