INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "差不多是这个数量，或者表示大概的时间。", "primary_collocate": null, "pronunciation": "dà yuē", "ipa": "ta˥˩ ɥe˥", "syllable_count": 2, "sentences": [{"text": "我家离学校大约两公里。", "target_word": "大约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大约五点，他就回家了。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书大约有三百页。", "target_word": "大约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议大约开了两个小时。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大约三十岁，在银行工作。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从这儿到机场，坐车大约要四十分钟。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们大约下个月搬家。", "target_word": "大约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室里大约有二十个学生。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大约七点出门，八点才到公司。", "target_word": "大约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包大约三百块钱。", "target_word": "大约", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在数量或时间前，表示不太精确的大概数目或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大约", "is_correct": true, "explanation": "正确：大约（dà yuē），副词，表示差不多的数量或时间。"}, {"text": "大学", "is_correct": false, "explanation": "学（xué）与约（yuē）声母不同（x 与 y），声调也不同，意思是高等教育机构。"}, {"text": "大雪", "is_correct": false, "explanation": "雪（xuě）与约（yuē）声母不同（x 与 y），声调也不同，意思是下得很大的雪。"}, {"text": "大院", "is_correct": false, "explanation": "院（yuàn）与约（yuē）韵母不同（üan 与 üe），声调也不同，意思是大的院子。"}], "explanations": {"大约": "正确：大约（dà yuē），副词，表示差不多的数量或时间。", "大学": "学（xué）与约（yuē）声母不同（x 与 y），声调也不同，意思是高等教育机构。", "大雪": "雪（xuě）与约（yuē）声母不同（x 与 y），声调也不同，意思是下得很大的雪。", "大院": "院（yuàn）与约（yuē）韵母不同（üan 与 üe），声调也不同，意思是大的院子。"}, "sentence_index": null, "correct_answer": "大约"}, "level_3": {"options": [{"text": "大约", "is_correct": true, "explanation": "正确：“大约”表示估计，符合“家离学校大约两公里”的大致距离。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有需要转折的内容，“离学校却两公里”说不通。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示再次，“离学校又两公里”表达的意思与句子无关。"}, {"text": "亦", "is_correct": false, "explanation": "语域：“亦”是书面用法，口语不用，且“也两公里”与句意不合。"}], "explanations": {"大约": "正确：“大约”表示估计，符合“家离学校大约两公里”的大致距离。", "却": "语义：“却”表示转折，句中没有需要转折的内容，“离学校却两公里”说不通。", "又": "语义：“又”表示再次，“离学校又两公里”表达的意思与句子无关。", "亦": "语域：“亦”是书面用法，口语不用，且“也两公里”与句意不合。"}, "sentence_index": 0, "correct_answer": "大约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他恰好大约三十岁。", "explanation": "这里应该用〈确切〉的说法。“大约”表示估计，与“恰好”的精确义相矛盾。"}, {"text": "他大约七点整出门。", "explanation": "这里应该用〈确切〉的时间说法，去掉“大约”。“大约”表示估计，与“七点整”的精确时间相矛盾。"}, {"text": "我大约一定是对的。", "explanation": "这里应该用〈可能〉。“大约”表示估计，与“一定”的确定语气相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大约", "is_correct": true, "explanation": "正确：“大约”表示估计时间，符合“下个月搬家”的大致时间。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“下个月”的将来时间矛盾。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去的经历，与“下个月”的将来时间矛盾。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是文言用法，口语不用，与“搬家”的口语语境不协调。"}], "explanations": {"大约": "正确：“大约”表示估计时间，符合“下个月搬家”的大致时间。", "刚": "语义：“刚”表示刚刚发生，与“下个月”的将来时间矛盾。", "曾": "语义：“曾”表示过去的经历，与“下个月”的将来时间矛盾。", "乃": "语域：“乃”是文言用法，口语不用，与“搬家”的口语语境不协调。"}, "sentence_index": 6, "correct_answer": "大约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三角形大约有三条边。", "explanation": "这里应该用〈正好〉。“三角形有三条边”是确定的事实，不能用估计的“大约”。"}, {"text": "我的身份证号码大约是十八位。", "explanation": "这里应该用〈确切〉的说法。“身份证号码”是确定的数字，不能用“大约”估计。"}, {"text": "法律规定大约十八岁成年。", "explanation": "这里应该用〈满〉。“法律规定”是确定的标准，不能用“大约”来估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路很大约长三公里。", "corrected_sentence": "这条路大约长三公里。", "error_description": "“大约”是表示估计的副词，不能被“很”修饰。“很大约长”错误，应为“大约长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师不大约明天回来。", "corrected_sentence": "老师大约明天回来。", "error_description": "“大约”表示估计，不能被“不”否定。“不大约明天回来”错误，应为“大约明天回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
