INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "深褐色是一种颜色，像巧克力的颜色。", "primary_collocate": null, "pronunciation": "shēn hè sè", "ipa": "ʂən˥ xɤ˥˩ sɤ˥˩", "syllable_count": 3, "sentences": [{"text": "我喜欢深褐色的鞋。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼睛是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "深褐色的头发很好看。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一件深褐色的外套。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的树叶变成了深褐色。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗的毛是深褐色的。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡倒进杯子里，是深褐色的。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用深褐色画那棵树。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "深褐色：像巧克力一样的深棕色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深褐色", "is_correct": true, "explanation": "深褐色：像巧克力一样的深棕色，用来描述鞋的颜色，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”不是颜色，不能用来描述鞋的颜色，句子不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是颜色，不能用来描述鞋的颜色，句子不通。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“脚”是身体部位，不能用来修饰鞋的颜色或属性，“脚的鞋”不成立。"}], "explanations": {"深褐色": "深褐色：像巧克力一样的深棕色，用来描述鞋的颜色，句意通顺。", "钢琴": "语义：“钢琴”不是颜色，不能用来描述鞋的颜色，句子不通。", "鸡蛋": "语义：“鸡蛋”不是颜色，不能用来描述鞋的颜色，句子不通。", "脚": "搭配：“脚”是身体部位，不能用来修饰鞋的颜色或属性，“脚的鞋”不成立。"}, "sentence_index": 0, "correct_answer": "深褐色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩是深褐色的。", "explanation": "这里应该用〈好〉。深褐色只表示颜色，形容成绩要用好、差这类评价词。"}, {"text": "这首歌的速度是深褐色的。", "explanation": "这里应该用〈快〉。深褐色只表示颜色，不能形容速度，形容速度要用快、慢这类词。"}, {"text": "这次旅行的价格是深褐色的。", "explanation": "这里应该用〈便宜〉。深褐色只表示颜色，不能形容价格，形容价格要用便宜、贵这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深褐色", "is_correct": true, "explanation": "深褐色：作“变成了”的宾语，指树叶变成的颜色，句意通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：树叶不能变成黑板，“变成了”后的名词要与树叶的变化相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：树叶不能变成电话，句意不通。"}, {"text": "高个子", "is_correct": false, "explanation": "体貌：“高个子”指人的身材，不能用来说树叶的变化。"}], "explanations": {"深褐色": "深褐色：作“变成了”的宾语，指树叶变成的颜色，句意通顺。", "黑板": "语义：树叶不能变成黑板，“变成了”后的名词要与树叶的变化相合。", "电话": "语义：树叶不能变成电话，句意不通。", "高个子": "体貌：“高个子”指人的身材，不能用来说树叶的变化。"}, "sentence_index": 6, "correct_answer": "深褐色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题是深褐色的。", "explanation": "这里应该用〈难〉。深褐色只表示颜色，不能形容题目的难易。"}, {"text": "她想用深褐色的早晨画那棵树。", "explanation": "这里应该用〈颜料〉。深褐色是颜色，不能修饰“早晨”这样的时间。"}, {"text": "她唱歌的声音是深褐色的。", "explanation": "这里应该用〈好听〉。深褐色只表示颜色，不能形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张纸慢慢变了成深褐色。", "corrected_sentence": "这张纸慢慢变成了深褐色。", "error_description": "错误：“变成了”中“成”和“了”的顺序颠倒，写成“变了成”不通。正确为“这张纸慢慢变成了深褐色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布的颜色是一个深褐色。", "corrected_sentence": "这块布的颜色是一种深褐色。", "error_description": "错误：颜色词“深褐色”应该用量词“种”，不能用“个”。正确为“一种深褐色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每两个东西中间有一样的时间或距离。", "primary_collocate": null, "pronunciation": "měi gé", "ipa": "mei˨˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "路边每隔五米种着一棵树。", "target_word": "每隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上每隔一百米就有一盏灯。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架每隔一层放一盆花。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们每隔一米站一个，排成一条长队。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你每隔一行写一句，这样看起来清楚。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在地里每隔半米挖一个小坑。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边每隔二十米就有一把长椅。", "target_word": "每隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯每隔几级就有一个小灯。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每隔一天见一次面。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书每隔十页有一张图片。", "target_word": "每隔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "相邻两个事物之间的距离或时间相等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b1c088-848e-452e-a53e-0280728c0626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每隔", "is_correct": true, "explanation": "正确：“每隔”表示相邻两者之间的距离相等，与“五米种一棵树”相符。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不表示相隔的距离，与“每隔五米”不符。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：“逐渐”多用于变化过程，不与“五米”这样的距离搭配。"}, {"text": "仅仅", "is_correct": false, "explanation": "语义：“仅仅”表示只有，与沿路按固定距离种树的规律矛盾。"}], "explanations": {"每隔": "正确：“每隔”表示相邻两者之间的距离相等，与“五米种一棵树”相符。", "一共": "语义：“一共”表示总计，不表示相隔的距离，与“每隔五米”不符。", "逐渐": "搭配：“逐渐”多用于变化过程，不与“五米”这样的距离搭配。", "仅仅": "语义：“仅仅”表示只有，与沿路按固定距离种树的规律矛盾。"}, "sentence_index": 0, "correct_answer": "每隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每隔学生都要交作业。", "explanation": "这里应该用〈每个〉。每隔要表示间隔的时间或距离，不能修饰人。"}, {"text": "我一年每隔去一次医院。", "explanation": "这里应该把“每隔”放在时段前，说成〈每隔一年〉。“每隔”必须位于它所修饰的时段之前。"}, {"text": "每隔下雨，他都带伞出门。", "explanation": "这里应该用〈每次〉。每隔要接表示间隔的时段或数量，不能直接接一个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每隔", "is_correct": true, "explanation": "正确：“每隔”表示按固定距离重复，与“二十米就有一把长椅”相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指忽然发生，与按固定距离设置长椅的规律不符。"}, {"text": "马上", "is_correct": false, "explanation": "体貌：“马上”表示即刻发生，与沿路的距离规律不符。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”指持续不断，与“二十米”的间隔矛盾。"}], "explanations": {"每隔": "正确：“每隔”表示按固定距离重复，与“二十米就有一把长椅”相符。", "突然": "语义：“突然”指忽然发生，与按固定距离设置长椅的规律不符。", "马上": "体貌：“马上”表示即刻发生，与沿路的距离规律不符。", "一直": "语义：“一直”指持续不断，与“二十米”的间隔矛盾。"}, "sentence_index": 6, "correct_answer": "每隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每隔五点就吃一顿饭。", "explanation": "这里应该用〈每到〉。每隔要接一段间隔，如“每隔五个小时”，不能接具体的时间点。"}, {"text": "这本书每隔都有一张图片。", "explanation": "这里应该用〈每章〉。每隔后必须接间隔的数量或时段，如“每隔十页”，不能单独使用。"}, {"text": "这座大楼十年每隔就加高一层。", "explanation": "这里应该把“每隔”放在时段前，说成〈每隔十年〉。“每隔”必须位于它所修饰的时段之前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里每隔了三米种着一棵树。", "corrected_sentence": "院子里每隔三米种着一棵树。", "error_description": "错误：“每隔了三米”；正确：“每隔三米”。“每隔”后直接接距离词，中间不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边每隔的三十米就有一盏路灯。", "corrected_sentence": "河边每隔三十米就有一盏路灯。", "error_description": "错误：“每隔的”；正确：“每隔”。“每隔”是副词，后面不加结构助词“的”，直接接时段或距离。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
