INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22988, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某个东西过来。", "primary_collocate": null, "pronunciation": "yǐn lái", "ipa": "in˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "村里没有水，他们从山上引来了泉水。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人从河里引来了水，给菜地浇水。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民修了水渠，把河水引来浇地。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的村子终于从镇上引来了电。", "target_word": "引来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把电线从路边引来，装上了一盏灯。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上开着灯，会把飞虫引来。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用骨头把邻居的小狗引来了。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拍了拍手，把小猫引来了。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边放了一盆糖水，把蜜蜂引来了。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在草地上撒了米，想把小鸟引来。", "target_word": "引来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引来了", "label": "完成体"}, {"form": "引来过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把水、电或动物引导过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b1c088-848e-452e-a53e-0280728c0626') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引来", "is_correct": true, "explanation": "正确。“从山上引来泉水”指把泉水引导到村里，符合“村里没有水”的语境。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：倒掉泉水与“村里没有水”的处境矛盾。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象通常是人或动物，不能与“泉水”搭配。"}, {"text": "引去", "is_correct": false, "explanation": "语义：把泉水引走与“村里没有水”的处境矛盾，句子要表示引到村里。"}], "explanations": {"引来": "正确。“从山上引来泉水”指把泉水引导到村里，符合“村里没有水”的语境。", "倒掉": "语义：倒掉泉水与“村里没有水”的处境矛盾。", "喂": "搭配：“喂”的对象通常是人或动物，不能与“泉水”搭配。", "引去": "语义：把泉水引走与“村里没有水”的处境矛盾，句子要表示引到村里。"}, "sentence_index": 0, "correct_answer": "引来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友从城里给我引来了一本书。", "explanation": "这里应该用〈送来〉。引来用于水、电、动物等被引导过来，不用于人送物品。"}, {"text": "工人把建材引来了工地。", "explanation": "这里应该用〈运到〉。引来用于引导水、电或动物，不用于运输建材。"}, {"text": "他把一张桌子引来了客厅。", "explanation": "这里应该用〈搬到〉。引来用于水、电、动物等被引导过来，不用于搬运家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引来", "is_correct": true, "explanation": "正确。用骨头把小狗引过来，符合“引来”的意思。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：前面说用骨头吸引小狗，却说“赶走”，与前面的动作矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，不能说“把小狗吃掉”。"}, {"text": "送走", "is_correct": false, "explanation": "语义：用骨头把小狗送走，与“用骨头”的吸引动作不合。"}], "explanations": {"引来": "正确。用骨头把小狗引过来，符合“引来”的意思。", "赶走": "语义：前面说用骨头吸引小狗，却说“赶走”，与前面的动作矛盾。", "吃掉": "搭配：“吃掉”的对象是食物，不能说“把小狗吃掉”。", "送走": "语义：用骨头把小狗送走，与“用骨头”的吸引动作不合。"}, "sentence_index": 6, "correct_answer": "引来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从国外引来了一本词典。", "explanation": "这里应该用〈寄来〉。引来用于水、电、动物等被引导过来，不用于邮寄物品。"}, {"text": "他在超市引来了一袋大米。", "explanation": "这里应该用〈买来〉。引来用于水、电、动物等被引导过来，不用于购买东西。"}, {"text": "他从厨房引来了一把刀。", "explanation": "这里应该用〈拿来〉。引来不用于从某处拿取物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民修了一条水渠，把河水把引来浇地。", "corrected_sentence": "村民修了一条水渠，把河水引来浇地。", "error_description": "重复使用“把”：一个“把”字句只用一次，应说“把河水引来浇地”，不说“把河水把引来浇地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吹了一声口哨，把小狗引来着。", "corrected_sentence": "他吹了一声口哨，把小狗引来了。", "error_description": "错误形式：“引来着”。正确形式：“引来了”。“引来”表示动作已有结果，不能加表示持续的“着”，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66431b1-0759-4bbf-94d1-5d452cb85690') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
