INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种工具，有长柄和宽头，可以用来挖土或铲东西。", "primary_collocate": null, "pronunciation": "chǎn zi", "ipa": "tʂʰan˨˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "他拿铲子在地上挖了一个洞。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树的时候，我们需要一把铲子。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用铲子把雪铲到路边。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铲子的柄很长，挖土不用弯腰。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们带着小铲子去海边玩沙。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用铲子把沙子装进车里。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在菜地里用铲子松土。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铲子放在门后面，你去拿一下。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借了邻居的铲子来挖花坛里的土。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把铲子是铁做的，很重。", "target_word": "铲子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把铲子", "label": "量词"}, {"form": "鏟子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有长柄和宽头、用来挖土铲东西的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25632224-7924-47df-ae1b-2e2ff713be96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。铲子 chǎn zi，指有长柄和宽头、用来挖土或铲东西的工具。"}, {"text": "毯子", "is_correct": false, "explanation": "t 与 ch 声母不同，声调相同，意思是毯子。"}, {"text": "篮子", "is_correct": false, "explanation": "l 与 ch 声母不同，lán（第二声）与 chǎn 声调也不同，意思是篮子。"}, {"text": "胆子", "is_correct": false, "explanation": "d 与 ch 声母不同，声调相同，意思是胆子，即胆量。"}, {"text": "剪子", "is_correct": false, "explanation": "j 与 ch 声母不同，声调相同，意思是剪子，即剪刀。"}], "explanations": {"铲子": "正确答案。铲子 chǎn zi，指有长柄和宽头、用来挖土或铲东西的工具。", "毯子": "t 与 ch 声母不同，声调相同，意思是毯子。", "篮子": "l 与 ch 声母不同，lán（第二声）与 chǎn 声调也不同，意思是篮子。", "胆子": "d 与 ch 声母不同，声调相同，意思是胆子，即胆量。", "剪子": "j 与 ch 声母不同，声调相同，意思是剪子，即剪刀。"}, "sentence_index": null, "correct_answer": "铲子"}, "level_3": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。用铲子挖洞符合句意。"}, {"text": "扇子", "is_correct": false, "explanation": "语义：扇子不能用来挖洞，这句话的意思不通。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子不能用来挖洞，这句话的意思不通。"}, {"text": "扫帚", "is_correct": false, "explanation": "搭配：“挖洞”的工具一般是铲、锹、镐，不搭配扫帚。"}], "explanations": {"铲子": "正确答案。用铲子挖洞符合句意。", "扇子": "语义：扇子不能用来挖洞，这句话的意思不通。", "盘子": "语义：盘子不能用来挖洞，这句话的意思不通。", "扫帚": "搭配：“挖洞”的工具一般是铲、锹、镐，不搭配扫帚。"}, "sentence_index": 0, "correct_answer": "铲子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿铲子在屋里扫地，扫得很干净。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，铲子是用来挖或铲的工具。"}, {"text": "门口放着一张铲子，你去拿一下。", "explanation": "这里应该用〈把〉。“张”用于平面的东西，铲子应该说“一把”。"}, {"text": "他买了一双铲子，要种花用。", "explanation": "这里应该用〈把〉。“双”用于成对的东西，铲子是单个的工具，应该说“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。铲子 chǎn zi，指有长柄和宽头、用来挖土或铲东西的工具。"}, {"text": "扇子", "is_correct": false, "explanation": "sh 与 ch 声母不同，shàn（第四声）与 chǎn（第三声）声调也不同，意思是扇子。"}, {"text": "盘子", "is_correct": false, "explanation": "p 与 ch 声母不同，pán（第二声）与 chǎn 声调不同，意思是盘子。"}, {"text": "毯子", "is_correct": false, "explanation": "t 与 ch 声母不同，声调相同，意思是毯子。"}, {"text": "厂子", "is_correct": false, "explanation": "chǎng 与 chǎn 韵母不同（ang 与 an），声调相同，意思是工厂。"}], "explanations": {"铲子": "正确答案。铲子 chǎn zi，指有长柄和宽头、用来挖土或铲东西的工具。", "扇子": "sh 与 ch 声母不同，shàn（第四声）与 chǎn（第三声）声调也不同，意思是扇子。", "盘子": "p 与 ch 声母不同，pán（第二声）与 chǎn 声调不同，意思是盘子。", "毯子": "t 与 ch 声母不同，声调相同，意思是毯子。", "厂子": "chǎng 与 chǎn 韵母不同（ang 与 an），声调相同，意思是工厂。"}, "sentence_index": null, "correct_answer": "铲子"}, "level_3": {"options": [{"text": "铲子", "is_correct": true, "explanation": "正确答案。用铲子松土符合句意。"}, {"text": "梳子", "is_correct": false, "explanation": "语义：梳子不能用来松土，这句话的意思不通。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：毛巾是软的，不能用来松土，这句话的意思不通。"}, {"text": "皮球", "is_correct": false, "explanation": "搭配：“用”后接的松土工具要能插入土壤，皮球不搭配这个用法。"}], "explanations": {"铲子": "正确答案。用铲子松土符合句意。", "梳子": "语义：梳子不能用来松土，这句话的意思不通。", "毛巾": "语义：毛巾是软的，不能用来松土，这句话的意思不通。", "皮球": "搭配：“用”后接的松土工具要能插入土壤，皮球不搭配这个用法。"}, "sentence_index": 6, "correct_answer": "铲子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵铲子是铁做的，很重。", "explanation": "这里应该用〈把〉。“棵”用于树木和植物，不用于铲子。"}, {"text": "这颗铲子是铁做的，很重。", "explanation": "这里应该用〈把〉。“颗”用于颗粒、果实等小而圆的东西，不用于铲子。"}, {"text": "这朵铲子是铁做的，很重。", "explanation": "这里应该用〈把〉。“朵”用于花朵，不用于铲子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一只铲子挖了一个坑。", "corrected_sentence": "他用一把铲子挖了一个坑。", "error_description": "量词错误：“只”多用于动物或成对物品中的一个，铲子是单个的工具，应说“一把”，不说“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我借了一块铲子去种花。", "corrected_sentence": "我借了一把铲子去种花。", "error_description": "量词错误：“块”用于块状的东西，铲子是有柄的工具，应该说“一把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
