INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放土种花的容器。", "primary_collocate": null, "pronunciation": "huā pén", "ipa": "xua˥ pʰən˧˥", "syllable_count": 2, "sentences": [{"text": "我家的窗台上放着两个花盆。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花盆里放了一些土，再种上花。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料花盆很轻，也很便宜。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆太旧了，爸爸换了一个大的。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的花需要每天浇水。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上桌子，打碎了花盆。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把种子放进花盆，然后盖上土。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里有很多花盆，红的白的都有。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把花盆搬进屋里。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在花盆下面放了一个盘子接水。", "target_word": "花盆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个花盆", "label": "量词"}, {"form": "花盆架", "label": "复合"}], "register": "中性", "sense_fingerprint": "放土种花的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25632224-7924-47df-ae1b-2e2ff713be96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22992, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”（huā pén）指放土种花的容器，即本词。"}, {"text": "花瓶", "is_correct": false, "explanation": "píng 与 pén 韵母不同（-ng 与 -n），意思是花瓶。"}, {"text": "花盘", "is_correct": false, "explanation": "pán 与 pén 元音不同（a 与 e），意思是花盘。"}, {"text": "花棚", "is_correct": false, "explanation": "péng 与 pén 韵母不同（-ng 与 -n），意思是花棚。"}, {"text": "花坛", "is_correct": false, "explanation": "tán 与 pén 声母不同（t 与 p），意思是花坛。"}], "explanations": {"花盆": "正确：“花盆”（huā pén）指放土种花的容器，即本词。", "花瓶": "píng 与 pén 韵母不同（-ng 与 -n），意思是花瓶。", "花盘": "pán 与 pén 元音不同（a 与 e），意思是花盘。", "花棚": "péng 与 pén 韵母不同（-ng 与 -n），意思是花棚。", "花坛": "tán 与 pén 声母不同（t 与 p），意思是花坛。"}, "sentence_index": null, "correct_answer": "花盆"}, "level_3": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”是装土种花的容器，窗台上放着两个花盆很自然。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”不能摆放在窗台上，与“放着两个”的意思不合。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”是行为模式，不是实物，不能放在窗台上。"}, {"text": "任务", "is_correct": false, "explanation": "搭配：“放”不与“任务”搭配，应说“布置任务”。"}], "explanations": {"花盆": "正确：“花盆”是装土种花的容器，窗台上放着两个花盆很自然。", "问题": "语义：“问题”不能摆放在窗台上，与“放着两个”的意思不合。", "习惯": "语义：“习惯”是行为模式，不是实物，不能放在窗台上。", "任务": "搭配：“放”不与“任务”搭配，应说“布置任务”。"}, "sentence_index": 0, "correct_answer": "花盆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家窗台上放着两条花盆。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，花盆要用“个”。"}, {"text": "窗台上插着一个花盆，里面有玫瑰。", "explanation": "这里应该用〈花瓶〉。插花要用花瓶，花盆是用来栽种花卉的容器。"}, {"text": "花盆里关着一只鹦鹉。", "explanation": "这里应该用〈鸟笼〉。花盆用来种花，不能用来关鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花盆", "is_correct": true, "explanation": "正确：“花盆”是能装土的容器，种子放进去再盖上土，符合句意。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”不能用来种植，放进口袋后也不能“盖上土”。"}, {"text": "信封", "is_correct": false, "explanation": "语义：“信封”是用来装信的，与“盖上土”的意思不合。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“放进”要接容器或地点，“墨水”是液体，应说“倒进”。"}], "explanations": {"花盆": "正确：“花盆”是能装土的容器，种子放进去再盖上土，符合句意。", "口袋": "语义：“口袋”不能用来种植，放进口袋后也不能“盖上土”。", "信封": "语义：“信封”是用来装信的，与“盖上土”的意思不合。", "墨水": "搭配：“放进”要接容器或地点，“墨水”是液体，应说“倒进”。"}, "sentence_index": 6, "correct_answer": "花盆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用花盆煮了一锅粥，给全家吃。", "explanation": "这里应该用〈锅〉。煮粥要用锅，花盆是放土种花的容器，不能用来煮东西。"}, {"text": "妈妈用花盆盛了汤，给客人喝。", "explanation": "这里应该用〈碗〉。花盆用来栽花，不能用来盛汤。"}, {"text": "他提着花盆去井边打水。", "explanation": "这里应该用〈水桶〉。打水要用水桶，花盆不能用来打水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上摆着一张花盆，里面种着花。", "corrected_sentence": "窗台上摆着一个花盆，里面种着花。", "error_description": "量词错误：“张”用于平面的东西，比如纸和桌子，“花盆”应该用“个”。正确的说法是“一个花盆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨前，他把两条旧花盆搬进了屋里。", "corrected_sentence": "下雨前，他把两个旧花盆搬进了屋里。", "error_description": "量词错误：“花盆”应用量词“个”，不能用“条”（“条”用于细长的东西）。正确说法是“两个旧花盆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
