INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "偷偷地走进来，不让人发现。", "primary_collocate": null, "pronunciation": "hùn jìn", "ipa": "xuən˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他趁着天黑混进了院子里。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人趁门开着的时候混进屋里，没有人发现。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男人没有票，混进了球场。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的人没看见，有个孩子混进来了。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想混进教室看看考试题。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷混进了商店，没有人发现。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着工作服混进了工厂。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们怎么才能混进他们的会议室呢？", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人混进火车站，没有买票。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们混进老师的办公室，拿了考卷。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混进了", "label": "体标"}, {"form": "混进去", "label": "方向补语"}], "register": "中性", "sense_fingerprint": "偷偷走进某处而不被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25632224-7924-47df-ae1b-2e2ff713be96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入、不被发现，与“趁着天黑”相合。"}, {"text": "照进", "is_correct": false, "explanation": "配价：“照进”的主语须是光线，不能说人“照进”院子。"}, {"text": "洒进", "is_correct": false, "explanation": "搭配：“洒”的对象多是液体或细碎之物，不能用来指人进入院子。"}, {"text": "流进", "is_correct": false, "explanation": "配价：“流进”的主语应该是液体，不能说人“流进”院子。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入、不被发现，与“趁着天黑”相合。", "照进": "配价：“照进”的主语须是光线，不能说人“照进”院子。", "洒进": "搭配：“洒”的对象多是液体或细碎之物，不能用来指人进入院子。", "流进": "配价：“流进”的主语应该是液体，不能说人“流进”院子。"}, "sentence_index": 0, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大大方方地混进了教室。", "explanation": "这里应该用〈走进〉。混进表示偷偷进入、不被发现，与“大大方方”矛盾。"}, {"text": "他报了名，正式混进了考试。", "explanation": "这里应该用〈参加〉。报了名的考生是合法入场的，应说“参加”；“混进”指偷偷进入。"}, {"text": "她作为主持人混进了会议，大家都向她问好。", "explanation": "这里应该用〈出席〉。主持人是正式受邀的，应说“出席”；“混进”指偷偷进入、不被察觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入，与“穿着工作服”的伪装情境相合。"}, {"text": "扛进", "is_correct": false, "explanation": "配价：“扛”要带被扛的物品作宾语，“她穿着工作服扛进了工厂”缺少宾语，不成立。"}, {"text": "吐进", "is_correct": false, "explanation": "语义：“吐进”指吐出的东西落入某处，不能用来指人偷偷进入工厂。"}, {"text": "吹进", "is_correct": false, "explanation": "配价：“吹”的施事通常是风，不能用人作主语。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入，与“穿着工作服”的伪装情境相合。", "扛进": "配价：“扛”要带被扛的物品作宾语，“她穿着工作服扛进了工厂”缺少宾语，不成立。", "吐进": "语义：“吐进”指吐出的东西落入某处，不能用来指人偷偷进入工厂。", "吹进": "配价：“吹”的施事通常是风，不能用人作主语。"}, "sentence_index": 6, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一路大声唱着歌，混进了办公室。", "explanation": "这里应该用〈走进〉。混进表示偷偷进入，“一路大声唱着歌”是公开进入，应说“走进”。"}, {"text": "老板亲自带路，他混进了会议室。", "explanation": "这里应该用〈进入〉。老板亲自带路是光明正大地进入，“混进”表示偷偷进入，与此矛盾。"}, {"text": "服务员端着托盘，混进了包厢。", "explanation": "这里应该用〈走进〉。服务员端着托盘是正常进入，“混进”表示偷偷进入，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她趁保安不注意，悄悄混进在了仓库。", "corrected_sentence": "她趁保安不注意，悄悄混进了仓库。", "error_description": "位置错误：“混进”与“了”之间不能插入“在”，应说“混进了仓库”，不能说“混进在了仓库”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人穿着制服，悄悄混进着大楼。", "corrected_sentence": "那个人穿着制服，悄悄混进了大楼。", "error_description": "体标错误：“混进”表示已完成的动作，应用“了”，不能用“着”（“着”表示持续的状态）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38bc2050-50e5-45ac-8ec6-473fdaf579e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "反义：“不同”指彼此不一样，与“像”（样子相近）相对。"}, {"text": "讲解", "is_correct": false, "explanation": "无关：“讲解”指说明道理，与“像”没有反义关系。"}, {"text": "保留", "is_correct": false, "explanation": "无关：“保留”指留住不放弃，与“像”没有反义关系。"}, {"text": "咨询", "is_correct": false, "explanation": "无关：“咨询”指请教、询问，与“像”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "反义：“不同”指彼此不一样，与“像”（样子相近）相对。", "讲解": "无关：“讲解”指说明道理，与“像”没有反义关系。", "保留": "无关：“保留”指留住不放弃，与“像”没有反义关系。", "咨询": "无关：“咨询”指请教、询问，与“像”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反驳", "is_correct": false, "explanation": "无关：“反驳”指用理由驳斥别人，与“像”没有反义关系。"}, {"text": "不同", "is_correct": true, "explanation": "反义：“不同”指彼此不一样，与“像”（样子相近）相对。"}, {"text": "设计", "is_correct": false, "explanation": "无关：“设计”指规划并绘制方案，与“像”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指把东西从一处移到另一处，与“像”没有反义关系。"}], "correct_answer": "不同", "explanations": {"反驳": "无关：“反驳”指用理由驳斥别人，与“像”没有反义关系。", "不同": "反义：“不同”指彼此不一样，与“像”（样子相近）相对。", "设计": "无关：“设计”指规划并绘制方案，与“像”没有反义关系。", "搬运": "无关：“搬运”指把东西从一处移到另一处，与“像”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "两个人或东西长得差不多。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕi̯ɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "你的眼睛很像你妈妈。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟长得像爸爸，高高的，爱笑。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗像它的妈妈，全身都是白的。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是姐妹，所以长得很像。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不像我哥哥，他个子高，我个子矮。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子看起来很像，只有颜色不同。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的声音像他爷爷一样。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和照片上的人不太像。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子像谁？我看像他舅舅。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两只猫像极了，我分不清。", "target_word": "像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相像", "label": "复合词"}, {"form": "像极了", "label": "程度补语"}], "register": "中性", "sense_fingerprint": "两个人或东西样子相近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f735cfaa-c81a-4eea-8896-d7ab5126a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香味。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是思考、希望。"}, {"text": "像", "is_correct": true, "explanation": "正确：“像”读作 xiàng，指两个人或东西样子相近。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（an 与 ang），意思是现在。"}, {"text": "性", "is_correct": false, "explanation": "xìng 与 xiàng 韵母不同（ing 与 ang），意思是性格、性质。"}], "explanations": {"香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香味。", "想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是思考、希望。", "像": "正确：“像”读作 xiàng，指两个人或东西样子相近。", "详": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。", "现": "xiàn 与 xiàng 韵母不同（an 与 ang），意思是现在。", "性": "xìng 与 xiàng 韵母不同（ing 与 ang），意思是性格、性质。"}, "sentence_index": null, "correct_answer": "像"}, "level_3": {"options": [{"text": "认识", "is_correct": false, "explanation": "语义：“认识”是知道某人，眼睛不能去认识人，句子说不通。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”是心里有好感，眼睛不能喜欢妈妈。"}, {"text": "像", "is_correct": true, "explanation": "正确：“像”表示眼睛与妈妈样子相近，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "配价：“照顾”的主语须是能行动的人，“眼睛”不能照顾妈妈。"}], "explanations": {"认识": "语义：“认识”是知道某人，眼睛不能去认识人，句子说不通。", "喜欢": "语义：“喜欢”是心里有好感，眼睛不能喜欢妈妈。", "像": "正确：“像”表示眼睛与妈妈样子相近，符合句意。", "照顾": "配价：“照顾”的主语须是能行动的人，“眼睛”不能照顾妈妈。"}, "sentence_index": 0, "correct_answer": "像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个结论像实验数据。", "explanation": "这里应该用〈一致〉。一致指两者相符、没有矛盾，像只表示样子或性质相近，不能说结论与数据相符。"}, {"text": "这件外套很像你的身份。", "explanation": "这里应该用〈符合〉。像表示样子或性质相近，说衣服与身份相称要用符合。"}, {"text": "一加一像二。", "explanation": "这里应该用〈等于〉。数字之间的相等要用等于，像只表示样子或性质相近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是箱子。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是声音大。"}, {"text": "像", "is_correct": true, "explanation": "正确：“像”读作 xiàng，指两个人或东西样子相近。"}, {"text": "县", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（an 与 ang），意思是县城。"}, {"text": "兴", "is_correct": false, "explanation": "xìng 与 xiàng 韵母不同（ing 与 ang），意思是高兴。"}], "explanations": {"箱": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是箱子。", "响": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是声音大。", "像": "正确：“像”读作 xiàng，指两个人或东西样子相近。", "县": "xiàn 与 xiàng 韵母不同（an 与 ang），意思是县城。", "兴": "xìng 与 xiàng 韵母不同（ing 与 ang），意思是高兴。"}, "sentence_index": null, "correct_answer": "像"}, "level_3": {"options": [{"text": "属于", "is_correct": false, "explanation": "搭配：“属于”后面接所属的人或物，不能与“一样”搭配，句子不通。"}, {"text": "听从", "is_correct": false, "explanation": "配价：“听从”的主语须是人，“声音”不能听从他爷爷。"}, {"text": "像", "is_correct": true, "explanation": "正确：“像”表示声音与爷爷相近，与“一样”搭配，符合句意。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”指不遵守，声音不能违背爷爷，句意不通。"}], "explanations": {"属于": "搭配：“属于”后面接所属的人或物，不能与“一样”搭配，句子不通。", "听从": "配价：“听从”的主语须是人，“声音”不能听从他爷爷。", "像": "正确：“像”表示声音与爷爷相近，与“一样”搭配，符合句意。", "违背": "语义：“违背”指不遵守，声音不能违背爷爷，句意不通。"}, "sentence_index": 6, "correct_answer": "像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书像我，别人不能借。", "explanation": "这里应该用〈属于〉。“像”表示样子相近，不能表示所属关系，说书是我的要用属于。"}, {"text": "他这次考试考得很像。", "explanation": "这里应该用〈好〉。像表示样子或性质相近，不能用来评价成绩或表现的好坏。"}, {"text": "我像这种颜色。", "explanation": "这里应该用〈喜欢〉。像表示样子相近，表示喜爱一种颜色要用喜欢，不能用像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子长得像了他舅舅。", "corrected_sentence": "这个孩子长得像他舅舅。", "error_description": "“像”是状态动词，后面不能直接跟动态助词“了”；若要表示变化，“了”应放在句末，如“长得越来越像他舅舅了”。应去掉“像”后面的“了”，说“长得像他舅舅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那两个孩子长很像，连笑起来都一个样。", "corrected_sentence": "那两个孩子长得很像，连笑起来都一个样。", "error_description": "“长”后的状态补语“很像”前漏了结构助词“得”，应说“长得很像”；“长很像”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17316628-84e8-491c-ba4c-4c820f1a3a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
