INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西有用处的特点。", "primary_collocate": null, "pronunciation": "gōng néng xìng", "ipa": "kʊŋ⁵⁵ nɤŋ³⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这个杯子的功能性很强。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机时，我最看重功能性。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子好看，但是功能性不高。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书包功能性很好，能放很多东西。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计房子时，功能性比样子更重要。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买鞋只看功能性，不看样子。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新机器的功能性比旧的好。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个工具的功能性很高。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间功能性不够，没有地方放书。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子功能性很高，还能当床。", "target_word": "功能性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "功能性食品", "label": "复合"}, {"form": "功能性饮料", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西好不好用、有没有用处的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "功能性", "is_correct": true, "explanation": "“功能性”指东西有用处的特点，与“很强”搭配，句意通顺。"}, {"text": "外观", "is_correct": false, "explanation": "搭配：“强”形容能力或功能，不用来形容外观，说外观要用“好看”“精致”等。"}, {"text": "容量", "is_correct": false, "explanation": "语义：容量指能装多少，要说“大”或“小”，不能说“强”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格只说高低，不能用“强”来形容，句子说的是杯子的用处。"}], "explanations": {"功能性": "“功能性”指东西有用处的特点，与“很强”搭配，句意通顺。", "外观": "搭配：“强”形容能力或功能，不用来形容外观，说外观要用“好看”“精致”等。", "容量": "语义：容量指能装多少，要说“大”或“小”，不能说“强”。", "价格": "语义：价格只说高低，不能用“强”来形容，句子说的是杯子的用处。"}, "sentence_index": 0, "correct_answer": "功能性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的功能性很漂亮。", "explanation": "这里应该用〈外观〉。功能性指东西有没有用处，说“漂亮”要用外观。"}, {"text": "这个音箱的功能性很好听。", "explanation": "这里应该用〈声音〉。功能性不能用“好听”来形容，说声音好听要用声音。"}, {"text": "这台电脑的功能性很快。", "explanation": "这里应该用〈性能〉。功能性说东西有没有用处，说“快”要用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "功能性", "is_correct": true, "explanation": "“功能性”指东西的用处，句中用来比较新旧机器，通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只用于人或动植物，机器不说年龄，“比旧的好”也不合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”一般只用于人，不用来说机器的特点。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历只用于人，机器没有学历，“比旧的好”也说不通。"}], "explanations": {"功能性": "“功能性”指东西的用处，句中用来比较新旧机器，通顺。", "年龄": "语义：年龄只用于人或动植物，机器不说年龄，“比旧的好”也不合。", "性格": "搭配：“性格”一般只用于人，不用来说机器的特点。", "学历": "语义：学历只用于人，机器没有学历，“比旧的好”也说不通。"}, "sentence_index": 6, "correct_answer": "功能性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的功能性很鲜艳。", "explanation": "这里应该用〈颜色〉。功能性说有没有用处，说“鲜艳”要用颜色。"}, {"text": "这碗汤的功能性很香。", "explanation": "这里应该用〈味道〉。功能性指用处，说“香”要用味道。"}, {"text": "这台冰箱的功能性很便宜。", "explanation": "这里应该用〈价格〉。功能性不能用“便宜”来形容，说价钱要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款水壶的功能性的很强，适合户外使用。", "corrected_sentence": "这款水壶的功能性很强，适合户外使用。", "error_description": "错误形式：“功能性的很强”。正确形式：“功能性很强”。“功能性”后面不接“的”，“很强”直接作谓语，“的”多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台相机的功能性高很，拍照很方便。", "corrected_sentence": "这台相机的功能性很高，拍照很方便。", "error_description": "错误形式：“高很”。正确形式：“很高”。程度副词“很”要放在形容词前面，应说“很高”，不能说“高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
