INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种菜的地方", "primary_collocate": null, "pronunciation": "cài yuán", "ipa": "tsʰaɪ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "学校后面有一个小菜园。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片菜园是邻居们一起种的。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，菜园里只剩下白菜。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在屋顶上做一个小菜园。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜园里的虫子吃了不少叶子。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个星期去菜园看一看。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，菜园里的菜比超市的好吃。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜园里种满了青菜和萝卜。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在菜园里种豆子。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从菜园里摘了一把青菜回家。", "target_word": "菜园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个菜园", "label": "量词"}, {"form": "一片菜园", "label": "量词"}, {"form": "菜園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "菜园：种菜的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba03f51-3fa7-4f07-875e-36a08896edd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜园", "is_correct": true, "explanation": "这里指种菜的小园子，与“学校后面有一个小”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是冷藏食物的电器，不能种菜，“学校后面有一个小冰箱”不合理。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“海洋”是广阔的水域，不能用“小”来修饰。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，学校后面不可能有一个小星星。"}], "explanations": {"菜园": "这里指种菜的小园子，与“学校后面有一个小”相符。", "冰箱": "语义：冰箱是冷藏食物的电器，不能种菜，“学校后面有一个小冰箱”不合理。", "海洋": "搭配：“海洋”是广阔的水域，不能用“小”来修饰。", "星星": "语义：星星在天上，学校后面不可能有一个小星星。"}, "sentence_index": 0, "correct_answer": "菜园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在菜园里修剪月季。", "explanation": "这里应该用〈花园〉。花园用于种植观赏花草，菜园是种蔬菜的地方，不用来修剪月季。"}, {"text": "周末我们去菜园看大象。", "explanation": "这里应该用〈动物园〉。动物园里养着大象等动物，菜园是种菜的地方，没有大象。"}, {"text": "菜园里养着很多奶牛。", "explanation": "这里应该用〈农场〉。农场可以养殖牲畜，菜园只用来种菜，不养奶牛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不种菜，“教室里的菜”不成立。"}, {"text": "菜园", "is_correct": true, "explanation": "这里指种菜的地方，与“菜比超市的好吃”的语境相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书、读书的地方，不种菜也不卖菜，“图书馆里的菜”不成立。"}, {"text": "游乐场", "is_correct": false, "explanation": "搭配：“菜”一般长在菜园或田地里，“游乐场里的菜”不搭配。"}], "explanations": {"教室": "语义：教室是上课的地方，不种菜，“教室里的菜”不成立。", "菜园": "这里指种菜的地方，与“菜比超市的好吃”的语境相符。", "图书馆": "语义：图书馆是借书、读书的地方，不种菜也不卖菜，“图书馆里的菜”不成立。", "游乐场": "搭配：“菜”一般长在菜园或田地里，“游乐场里的菜”不搭配。"}, "sentence_index": 6, "correct_answer": "菜园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋顶上有一张菜园。", "explanation": "这里应该用〈一片〉。“张”用于纸、桌子等平面的东西，菜园不能用“张”计量。"}, {"text": "学校旁边有一只菜园。", "explanation": "这里应该用〈一片〉。“只”用于动物，菜园不能用“只”计量。"}, {"text": "村口有一篇菜园。", "explanation": "这里应该用〈一片〉。“篇”用于文章，菜园不能用“篇”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家后面有一棵菜园。", "corrected_sentence": "他家后面有一片菜园。", "error_description": "量词错误：“棵”用于植物，菜园是一块地，应用“片”计量，不能说“一棵菜园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家门前有一扇菜园。", "corrected_sentence": "我家门前有一片菜园。", "error_description": "量词错误：菜园应用“片”计量，“扇”用于门窗，不能说“一扇菜园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
