INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做某件事。", "primary_collocate": null, "pronunciation": "xíng dòng", "ipa": "ɕiŋ˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们明天早上八点行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要马上行动起来。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成功，就要行动，不能只是想。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说到做到，马上开始行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察昨晚在城里行动了。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别再等了，今天就行动吧。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动之前，我们先开个会。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们分组行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先想好计划，再行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说：“少说话，多行动。”", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行动起来", "label": "补语"}, {"form": "行动计划", "label": "复合"}, {"form": "行动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "动手去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动", "is_correct": true, "explanation": "行动：做某件事，此处指明天早上八点开始做事。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：迷路指找不到方向，不是可以按计划安排在某个时间的事。"}, {"text": "长大", "is_correct": false, "explanation": "语义：长大是慢慢变化的过程，不能安排在明天早上八点做。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠指睡不着，不是为明天早上的安排而做的事。"}], "explanations": {"行动": "行动：做某件事，此处指明天早上八点开始做事。", "迷路": "语义：迷路指找不到方向，不是可以按计划安排在某个时间的事。", "长大": "语义：长大是慢慢变化的过程，不能安排在明天早上八点做。", "失眠": "语义：失眠指睡不着，不是为明天早上的安排而做的事。"}, "sentence_index": 0, "correct_answer": "行动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都去公园做行动。", "explanation": "这里应该用〈运动〉。行动指去做某件事，锻炼身体要用运动。"}, {"text": "比赛行动了两个小时。", "explanation": "这里应该用〈进行〉。行动指人有意做事，比赛持续的过程要用进行。"}, {"text": "这个程序行动得很快。", "explanation": "这里应该用〈运行〉。行动指人有意做事，程序工作要用运行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动", "is_correct": true, "explanation": "行动：做事，此处指在开会之前要做的事。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生不是可以安排在“开会”之前的事，与语境不合。"}, {"text": "下辈子", "is_correct": false, "explanation": "语义：下辈子是很远的将来，不能说“下辈子之前先开个会”。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”指没有按时到达，不能用“迟到之前”表示行动前的时间。"}], "explanations": {"行动": "行动：做事，此处指在开会之前要做的事。", "出生": "语义：出生不是可以安排在“开会”之前的事，与语境不合。", "下辈子": "语义：下辈子是很远的将来，不能说“下辈子之前先开个会”。", "迟到": "搭配：“迟到”指没有按时到达，不能用“迟到之前”表示行动前的时间。"}, "sentence_index": 6, "correct_answer": "行动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电话里行动了很久。", "explanation": "这里应该用〈说〉。行动指有目的地做事，打电话时说话要用说。"}, {"text": "我每天晚上都在家里行动。", "explanation": "这里应该用〈睡觉〉。行动指有目的地做事，夜里在家休息要用睡觉。"}, {"text": "这批货物用火车行动。", "explanation": "这里应该用〈运输〉。货物运送要用运输，行动不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都行动下来了。", "corrected_sentence": "大家都行动起来了。", "error_description": "“行动起来”表示开始行动，补语应用“起来”，不用“下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察分头行动的，抓住了小偷。", "corrected_sentence": "警察分头行动，抓住了小偷。", "error_description": "“分头行动”是完整的动作结构，后面不能直接加“的”，应删去“的”，说“警察分头行动，抓住了小偷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
