INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个人或东西看成另一种东西。", "primary_collocate": null, "pronunciation": "dàng zuò", "ipa": "tɑŋ˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他把我当作最好的朋友。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把这件事当作玩笑。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把手机当作电脑用。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次失败当作一次学习的机会。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把旧桌子当作书架用。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都把她当作家里人。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不把别人的帮助当作应该的事。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，人们把狗当作家人。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把我说的话当作命令。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把纸箱当作小房子玩了一下午。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当作了", "label": "体标"}, {"form": "当作过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：把A看成B，常用“把A当作B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c1a906-ea1f-4e51-bb2e-ae63d5c674b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当作", "is_correct": true, "explanation": "正确：“当作”表示把某人看成另一种东西，与“把…当作…”结构相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”不能同时带“我”和“最好的朋友”两个宾语，“把我喜欢最好的朋友”不成立。"}, {"text": "讨厌", "is_correct": false, "explanation": "配价：“讨厌”是心理动词，不能同时带“我”和“最好的朋友”两个宾语，“把我讨厌最好的朋友”不成立。"}, {"text": "称呼", "is_correct": false, "explanation": "配价：“称呼”后要用“为”引出称谓，“把我称呼最好的朋友”不成立。"}], "explanations": {"当作": "正确：“当作”表示把某人看成另一种东西，与“把…当作…”结构相合。", "喜欢": "搭配：“喜欢”不能同时带“我”和“最好的朋友”两个宾语，“把我喜欢最好的朋友”不成立。", "讨厌": "配价：“讨厌”是心理动词，不能同时带“我”和“最好的朋友”两个宾语，“把我讨厌最好的朋友”不成立。", "称呼": "配价：“称呼”后要用“为”引出称谓，“把我称呼最好的朋友”不成立。"}, "sentence_index": 0, "correct_answer": "当作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈当作我已经吃过了，就没做饭。", "explanation": "这里应该用〈以为〉。妈妈是误认为我吃过了，表示错误的认识要用“以为”；“当作”是有意把A看成B。"}, {"text": "他把我当作很高兴，所以什么也没说。", "explanation": "这里应该用〈觉得〉。“当作”的宾语应是名词性的对象，不能接“很高兴”这样的形容词短语；表达感受时要用“觉得”。"}, {"text": "他把这份计划当作了三年，才终于完成。", "explanation": "这里应该用〈花〉。“当作”要把对象看成另一种事物，表示耗费时间时应说“花了三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能用来表示把帮助看作某种事情，“拿应该的事”不成立。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”指应对问题，与“别人的帮助”和“应该的事”的关系无关。"}, {"text": "当作", "is_correct": true, "explanation": "正确：“当作”表示把别人的帮助看成应该的事，与“从不”的否定相合。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”后不能直接接“把…”宾语和“应该的事”这样的名词短语，句子不成立。"}], "explanations": {"拿": "搭配：“拿”不能用来表示把帮助看作某种事情，“拿应该的事”不成立。", "回答": "语义：“回答”指应对问题，与“别人的帮助”和“应该的事”的关系无关。", "当作": "正确：“当作”表示把别人的帮助看成应该的事，与“从不”的否定相合。", "感到": "配价：“感到”后不能直接接“把…”宾语和“应该的事”这样的名词短语，句子不成立。"}, "sentence_index": 6, "correct_answer": "当作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我当作这次比赛会很难，所以提前准备。", "explanation": "这里应该用〈认为〉。“当作”后接的是具体对象，表示把它看成另一种事物；对“比赛会很难”这样的判断，要用“认为”。"}, {"text": "这本书我当作了一个星期才看完。", "explanation": "这里应该用〈花〉。“当作”表示把A看成B，不能表示耗费时间；应说“花了一个星期”。"}, {"text": "他把这篇文章当作读完了，就去睡觉了。", "explanation": "这里“当作”后接的是动作，不是被看成的事物；应去掉“当作”，说“他读完了这篇文章，就去睡觉了。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把我很当作亲人。", "corrected_sentence": "他把我当作亲人。", "error_description": "错误：“把”字结构中，“很”不能插在宾语“我”和动词“当作”之间，句中多加了“很”。应说“他把我当作亲人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都把她当作着自己人。", "corrected_sentence": "我们都把她当作自己人。", "error_description": "错误：“当作”后不能直接加“着”，应说“我们都把她当作自己人。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
