INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体、气体等沿着一定路线周而复始地流动。", "primary_collocate": null, "pronunciation": "xún huán", "ipa": "ɕyn˧˥ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "血液在身体里不停地循环。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暖气管里的热水一直在循环。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水泵让池里的水不停循环。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼缸的水要循环，鱼才不会生病。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气在房间里循环，所以不闷。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷却液在发动机里循环，让机器降温。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心脏停了，血就不能循环了。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电风扇开着，屋里的空气循环得很快。", "target_word": "循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器让油在管道里循环。", "target_word": "循环", "complexity_tier": "T3", "furigana": "zhè tái jī qì ràng yóu zài guǎn dào lǐ xún huán。", "sentence_source": "generated"}, {"text": "水在管子里循环，像车轮转个不停。", "target_word": "循环", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "循環", "label": "繁体"}, {"form": "循环水", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，液体、气体等沿着一定路线一圈圈流转（血液循环、水循环流动）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "循环", "is_correct": true, "explanation": "循环：动词，指液体沿固定路线周而复始地流动，与“血液在身体里”相符。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”表示不流动，与“不停地”矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "语义：血液不会“生长”，与血液流动的语境不符。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”指人或车离开某地，不用于血液，搭配不当。"}], "explanations": {"循环": "循环：动词，指液体沿固定路线周而复始地流动，与“血液在身体里”相符。", "停滞": "语义：“停滞”表示不流动，与“不停地”矛盾。", "生长": "语义：血液不会“生长”，与血液流动的语境不符。", "出发": "搭配：“出发”指人或车离开某地，不用于血液，搭配不当。"}, "sentence_index": 0, "correct_answer": "循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "泪水顺着脸颊循环下来。", "explanation": "这里应该用〈流淌〉。循环指液体沿固定路线回流，泪水流下后不会回到原处，应说〈流淌〉。"}, {"text": "这群孩子循环进了教室，打破了安静。", "explanation": "这里应该用〈涌进〉。循环指液体、气体沿固定路线回流，孩子进教室是单向的，不说〈循环〉。"}, {"text": "他从石缝里循环出来了。", "explanation": "这里应该用〈钻〉。循环指液体、气体沿固定路线回流，人从石缝里钻出是单向的，不说〈循环〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "循环", "is_correct": true, "explanation": "循环：动词，指液体沿固定路线周而复始地流动，与“心脏停了”形成因果。"}, {"text": "下降", "is_correct": false, "explanation": "语义：“下降”指数值或位置降低，与血液循环的流动义不符。"}, {"text": "旋转", "is_correct": false, "explanation": "语义：“旋转”指绕轴转动，与血液沿血管流动的路线不符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”用于人，不能用于血液，搭配不当。"}], "explanations": {"循环": "循环：动词，指液体沿固定路线周而复始地流动，与“心脏停了”形成因果。", "下降": "语义：“下降”指数值或位置降低，与血液循环的流动义不符。", "旋转": "语义：“旋转”指绕轴转动，与血液沿血管流动的路线不符。", "散步": "搭配：“散步”用于人，不能用于血液，搭配不当。"}, "sentence_index": 6, "correct_answer": "循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木头顺着河水循环，漂到了下游。", "explanation": "这里应该用〈漂流〉。循环指液体或气体沿固定路线回流，木头顺水漂走后不会回到原处。"}, {"text": "他把门票循环给了每个同学。", "explanation": "这里应该用〈分发〉。循环指液体、气体沿固定路线回流，门票是一次性递出，不说〈循环〉。"}, {"text": "孩子们把小球循环到了桌子底下。", "explanation": "这里应该用〈滚〉。循环指沿固定路线回流，小球滚到桌下是单向的，应说〈滚〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统把温水在地板下循环。", "corrected_sentence": "这套系统让温水在地板下循环。", "error_description": "“循环”是不及物动词，不能用“把”字句处置对象，应用“让”引出使役，说“让温水在地板下循环”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷水在管子里循环一个，又回到了水箱。", "corrected_sentence": "冷水在管子里循环一圈，又回到了水箱。", "error_description": "“循环”作动词，表示绕行一周，其动量补语应用量词“圈”，不能用“个”，应说“循环一圈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
