INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用某个东西来帮自己做事情。", "primary_collocate": null, "pronunciation": "lì yòng", "ipa": "li˥˩ joŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我利用午休时间看书。", "target_word": "利用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他利用下班后的时间学做饭。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈利用旧衣服做了一个包。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们利用周末去爬山。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她利用出差的机会参观了博物馆。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子利用废纸做了一个小玩具。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他利用坐车的时间背单词。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸利用空盒子做了一个小桌子。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想利用这个机会练习说汉语。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们利用课间休息聊天儿。", "target_word": "利用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "利用了", "label": "完成体"}, {"form": "利用过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "拿时间、机会或东西来帮自己做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e52338-d86c-46e6-8c0d-e6c3d2a19ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利用", "is_correct": true, "explanation": "lì yòng：拿某个东西来帮自己做事，是正确答案。"}, {"text": "利于", "is_correct": false, "explanation": "lì yú 与 lì yòng 韵母不同（yú 与 yòng），意思是“对……有好处”。"}, {"text": "利益", "is_correct": false, "explanation": "lì yì 与 lì yòng 韵母不同（yì 与 yòng），意思是“好处”。"}, {"text": "利诱", "is_correct": false, "explanation": "lì yòu 与 lì yòng 韵母不同（yòu 与 yòng），意思是“用好处去引诱”。"}], "explanations": {"利用": "lì yòng：拿某个东西来帮自己做事，是正确答案。", "利于": "lì yú 与 lì yòng 韵母不同（yú 与 yòng），意思是“对……有好处”。", "利益": "lì yì 与 lì yòng 韵母不同（yì 与 yòng），意思是“好处”。", "利诱": "lì yòu 与 lì yòng 韵母不同（yòu 与 yòng），意思是“用好处去引诱”。"}, "sentence_index": null, "correct_answer": "利用"}, "level_3": {"options": [{"text": "利用", "is_correct": true, "explanation": "利用：“利用午休时间”表示把午休时间拿来做事，符合句意。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“时间”作宾语。"}, {"text": "等待", "is_correct": false, "explanation": "搭配：“等待”的对象不能是“午休时间”，“等待午休时间看书”不通。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的对象应是话题，与“午休时间看书”的句意不符。"}], "explanations": {"利用": "利用：“利用午休时间”表示把午休时间拿来做事，符合句意。", "睡": "配价：“睡”是不及物动词，不能带“时间”作宾语。", "等待": "搭配：“等待”的对象不能是“午休时间”，“等待午休时间看书”不通。", "讨论": "语义：“讨论”的对象应是话题，与“午休时间看书”的句意不符。"}, "sentence_index": 0, "correct_answer": "利用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我利用了昨晚的一场噩梦。", "explanation": "这里应该用〈做〉。“利用”指拿来派上用场，噩梦是做出来的，要说“做了一场噩梦”。"}, {"text": "我们利用了周末的快乐。", "explanation": "这里应该用〈享受〉。“利用”强调拿来派用场，快乐要用“享受”。"}, {"text": "他利用了一场大雨，全身都湿了。", "explanation": "这里应该用〈淋〉。“利用”指拿来派上用场，被雨打湿要说“淋了一场大雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利用", "is_correct": true, "explanation": "lì yòng：拿某个东西来帮自己做事，是正确答案。"}, {"text": "弃用", "is_correct": false, "explanation": "qì yòng 与 lì yòng 声母不同（q 与 l），意思是“不再使用”。"}, {"text": "自用", "is_correct": false, "explanation": "zì yòng 与 lì yòng 声母不同（z 与 l），意思是“自己使用”。"}, {"text": "试用", "is_correct": false, "explanation": "shì yòng 与 lì yòng 声母不同（sh 与 l），意思是“试着使用”。"}, {"text": "日用", "is_correct": false, "explanation": "rì yòng 与 lì yòng 声母不同（r 与 l），意思是“日常使用的”。"}], "explanations": {"利用": "lì yòng：拿某个东西来帮自己做事，是正确答案。", "弃用": "qì yòng 与 lì yòng 声母不同（q 与 l），意思是“不再使用”。", "自用": "zì yòng 与 lì yòng 声母不同（z 与 l），意思是“自己使用”。", "试用": "shì yòng 与 lì yòng 声母不同（sh 与 l），意思是“试着使用”。", "日用": "rì yòng 与 lì yòng 声母不同（r 与 l），意思是“日常使用的”。"}, "sentence_index": null, "correct_answer": "利用"}, "level_3": {"options": [{"text": "利用", "is_correct": true, "explanation": "利用：“利用坐车的时间”表示把坐车的时间拿来用，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“时间”搭配，“吃坐车的时间”不成词组。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“时间”作宾语。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔坐车的时间”与“背单词”的句意矛盾。"}], "explanations": {"利用": "利用：“利用坐车的时间”表示把坐车的时间拿来用，符合句意。", "吃": "搭配：“吃”不能与“时间”搭配，“吃坐车的时间”不成词组。", "唱": "配价：“唱”不能带“时间”作宾语。", "扔": "语义：“扔坐车的时间”与“背单词”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "利用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们利用了这次困难。", "explanation": "这里应该用〈克服〉。“利用”不能用于困难，要用“克服”。"}, {"text": "大家利用了这阵寒冷。", "explanation": "这里应该用〈抵御〉。“利用”指拿来派上用场，寒冷要用“抵御”，不能说“利用寒冷”。"}, {"text": "同学们利用了这份心跳。", "explanation": "这里应该用〈感受〉。“利用”指拿来派上用场，心跳不是可供利用的工具或资源，要说“感受心跳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正在利用了晚上的时间写作业。", "corrected_sentence": "我正在利用晚上的时间写作业。", "error_description": "“了”误加在“利用”后：“正在”表示动作进行中，不能与“了”同用，应说“正在利用晚上的时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在利用了空闲时间背单词。", "corrected_sentence": "他正在利用空闲时间背单词。", "error_description": "“了”误加在“利用”后：“正在”表示动作进行中，不能与“了”同用，应说“正在利用空闲时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
